INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'BROAD', 210, 'How did you design and manage persistent memory in your system, and what role does long-term memory play across sessions?', '{"key_points": [{"id": "KP1", "description": "Hierarchical Memory Architecture: Distinguishes ephemeral session working memory from durable multi-session persistent context.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, PostgreSQL, Redis, working memory.", "Differentiates ephemeral session state (in-memory LangGraph state / Redis buffer) from persistent long-term storage (PostgreSQL/vector database).", "Identifies distinct memory tiers such as Session Memory, Workflow Memory, and Persistent Customer/User Context."]}, {"id": "KP2", "description": "Explain how persistent attributes (user preferences, past interactions, verified profile details) are retrieved across distinct sessions.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL user_profiles, Redis HGETALL, session hydration, JSONB attributes, metadata filtering.", "Explains how persistent attributes (user preferences, past interactions, verified profile details) are retrieved across distinct sessions.", "Queries durable user preferences from PostgreSQL or Redis hashes (e.g. HGETALL user:{id}:prefs) to hydrate the system prompt at the beginning of each session."]}, {"id": "KP3", "description": "Context Engineering & Token Management: Describes mechanisms to compact, summarize, and prioritize memory within LLM token constraints.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, top-k, LLM, llm token.", "Implements recursive summarization, sliding window trimming, or message compaction to prevent token budget overflow.", "Applies semantic retrieval or relevance filtering to inject only top-k contextually relevant past memory turns."]}, {"id": "KP4", "description": "Explain staleness control or conflict detection to prevent outdated customer facts from poisoning current generation.", "required": false, "acceptable_evidence": ["Technical keywords: TTL expiration, timestamp versioning, valid_from, conflict resolution, memory invalidation.", "Explains staleness control or conflict detection to prevent outdated customer facts from poisoning current generation.", "Applies timestamp-based validity windows (valid_from/valid_to) and explicit TTL policies so newer conversational facts overwrite stale or conflicting user profile attributes."]}, {"id": "KP5", "description": "Privacy, Governance & Eviction: Addresses data retention, privacy boundaries, and cache eviction across sessions.", "required": false, "acceptable_evidence": ["Technical keywords: GDPR, CCPA, TTL, LRU eviction.", "Enforces PII masking or sanitization prior to storing conversational turns into durable memory.", "Defines Time-to-Live (TTL), LRU eviction, or user-initiated memory deletion policies for regulatory compliance (GDPR/CCPA).", "Ensures strict tenant and user isolation so memory cannot cross user or organization boundaries."]}], "critical_failures": ["Treats all conversation state as unbounded ephemeral memory without durable cross-session persistence.", "Fails to describe any token management, summarization, or context pruning strategy to prevent context window exhaustion."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How did you implement PII detection and masking, and what tools or frameworks did you use?', '{"key_points": [{"id": "KP1", "description": "PII Detection Pipeline & Recognizers: Details entity extraction using pattern matching, checksums, and named entity recognition.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, PII, NER, SSN.", "Utilizes Microsoft Presidio Analyzer, spaCy NER, or regex-based recognizers to detect sensitive entities (SSN, credit card, phone, email, MRN).", "Customizes pattern recognizers with context words and validation algorithms (e.g., Luhn check for cards)."]}, {"id": "KP2", "description": "Explain handling both structured entities (regex/checksum) and unstructured free-text entities (Transformer/NER models).", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, spaCy NER, HuggingFace Transformers, RoBERTa NER, regex pattern matching, Luhn checksum.", "Explains handling both structured entities (regex/checksum) and unstructured free-text entities (Transformer/NER models).", "Combines regex pattern matching and Luhn checksum validation for structured PII (credit cards, SSNs) with fine-tuned NER Transformer models to detect unstructured entities like names and home addresses."]}, {"id": "KP3", "description": "Masking & Anonymization Strategies: Describes redaction, pseudonymization, and reversible tokenization mechanisms.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, pseudonymization, SSN, <SSN>.", "Applies Microsoft Presidio Anonymizer or custom transformers to replace PII with synthetic surrogates, hashes, or typed tags (e.g., <SSN>).", "Implements reversible pseudonymization or vault mapping if downstream workflows require re-identifying entities safely."]}, {"id": "KP4", "description": "Redacts sensitive data early in the ingestion pipeline before embedding generation or vector database storage.", "required": false, "acceptable_evidence": ["Technical keywords: pre-ingestion redaction, PII sanitization, vector hygiene, embedding poisoning, token replacement.", "Redacts sensitive data early in the ingestion pipeline before embedding generation or vector database storage.", "Executes automated redaction at the API gateway prior to chunking and vector embedding generation, ensuring raw PII never enters Milvus or external LLM contexts."]}, {"id": "KP5", "description": "Latency, Auditing & Edge Cases: Addresses performance overhead, zero-leakage trade-offs, and audit trails.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, OCR, request pipelines, PII.", "Measures and optimizes PII analysis latency impact on real-time streaming LLM request pipelines.", "Maintains immutable audit logs of redaction events without logging sensitive plaintext data.", "Addresses edge cases such as misspelled names, OCR artifacts, or non-standard number formats."]}], "critical_failures": ["Relies entirely on LLM system prompt instructions to omit PII without deterministic detection/masking software.", "Fails to identify standard PII tools (such as Presidio, regex, or NER pipelines) or cannot explain how masking is performed."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you approach collaboration with client teams when integrating AI systems into their existing infrastructure and workflows?', '{"key_points": [{"id": "KP1", "description": "Technical Discovery & Infrastructure Assessment: Demonstrates thorough auditing of client systems, APIs, and data governance.", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA, IAM, SAML, data governance.", "Conducts architecture discovery workshops to map client legacy APIs, database schemas, and networking constraints (VPCs, firewalls).", "Assesses client data security, compliance standards (SOC2, HIPAA), and identity providers (SAML, Okta, IAM)."]}, {"id": "KP2", "description": "Identify integration touchpoints for AI components (e.g., webhook listeners, Kafka topics, REST endpoints).", "required": true, "acceptable_evidence": ["Technical keywords: OpenAPI Swagger, Kafka event consumers, webhook listeners, REST contracts, schema validation.", "Identifies integration touchpoints for AI components (e.g., webhook listeners, Kafka topics, REST endpoints).", "Publishes formal OpenAPI schemas and asynchronous event specifications (Kafka topics or webhook contracts) to integrate AI services seamlessly into client microservices."]}, {"id": "KP3", "description": "Expectation Alignment & Non-Determinism Management: Manages client expectations around AI system capabilities and accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, p95, AI, LLM.", "Educates client engineering and product leaders on probabilistic LLM behavior and hallucination mitigation.", "Defines shared Service Level Objectives (SLOs) and evaluation baselines (Hit Rate, accuracy thresholds, p95 latency).", "Establishes fallback paths and Human-in-the-Loop review mechanisms for low-confidence outputs."]}, {"id": "KP4", "description": "Iterative Rollout & Knowledge Transfer: Implements phased deployment with documentation and team enablement.", "required": false, "acceptable_evidence": ["Technical keywords: API, iterative, rollout, knowledge.", "Executes phased migration (shadow deployment -> pilot user group -> full production cutover).", "Provides comprehensive API documentation, architecture runbooks, and telemetry dashboards to client engineers.", "Conducts hands-on pairing sessions to enable client engineers to maintain and monitor the system post-launch."]}], "critical_failures": ["Assumes client infrastructure can be rewritten to suit the AI system rather than integrating into existing workflows.", "Fails to address client stakeholder alignment, data governance, or probabilistic system expectations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you design AI systems that support multiple user roles with different requirements and outputs?', '{"key_points": [{"id": "KP1", "description": "Role-Based Retrieval & Data Segmentation: Enforces authorization barriers at retrieval and data ingestion layers.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, tenant_id, allowed_roles, based retrieval.", "Embeds role and permission metadata (tenant_id, allowed_roles, department) into vector database payloads and relational tables.", "Enforces pre-filtering during vector search (e.g., Milvus boolean expression filtering) so restricted chunks are never retrieved."]}, {"id": "KP2", "description": "Differentiates access levels across personas (e.g., recruiter sees candidate resumes and salary notes; hiring manager sees sanitized technical assessment only).", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, claims-based access, JWT claims, field-level masking, tenant isolation.", "Differentiates access levels across personas (e.g., recruiter sees candidate resumes and salary notes; hiring manager sees sanitized technical assessment only).", "Applies role-based attribute filtering to mask salary figures or raw candidate resumes when generating reports for non-admin hiring managers."]}, {"id": "KP3", "description": "Persona-Specific Prompting & Output Formatting: Adapts model tone, depth, and schema based on authenticated role.", "required": true, "acceptable_evidence": ["Technical keywords: output schemas, information leakage, persona, output.", "Injects persona-tailored system prompts that calibrate output technical depth, brevity, and business focus.", "Uses role-specific structured output schemas (e.g., executive summary for managers vs granular interview rubric for interviewers).", "Validates generated output against role permissions to prevent indirect information leakage across personas."]}, {"id": "KP4", "description": "Auditing, Security & Session Context: Ensures tamper-proof role propagation and audit logging.", "required": false, "acceptable_evidence": ["Technical keywords: JWT, session memory, scopes memory.", "Extracts authenticated user roles securely from signed JWT claims rather than trusting client-provided prompt headers.", "Maintains separate session memory contexts or scopes memory queries by user role to avoid cross-role contamination.", "Logs all role-based data accesses for enterprise security auditing and compliance."]}], "critical_failures": ["Relies on prompt instructions alone to restrict access to sensitive role-specific data without database-level filtering.", "Fails to explain how retrieval or generation changes across different user personas."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you ensure data security and prevent leakage of sensitive information when working with AI systems in regulated industries?', '{"key_points": [{"id": "KP1", "description": "Data Ingestion & Transit Protection: Secures data entering the AI pipeline with strict encryption and masking.", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA, TLS 1.3, REST, AI.", "Implements TLS 1.3 in transit and KMS envelope encryption at rest for vector embeddings and document stores.", "Runs automated PII/PHI redaction (HIPAA Safe Harbor / Presidio) prior to text storage and embedding generation."]}, {"id": "KP2", "description": "Configures private network connectivity (AWS PrivateLink, VPC Endpoints) to prevent data transit over the public internet.", "required": true, "acceptable_evidence": ["Technical keywords: AWS PrivateLink, VPC Interface Endpoints, internal security groups, TLS 1.3, egress filtering.", "Configures private network connectivity (AWS PrivateLink, VPC Endpoints) to prevent data transit over the public internet.", "Routes model inference and vector database traffic exclusively through AWS VPC Interface Endpoints and PrivateLink to eliminate public internet exposure."]}, {"id": "KP3", "description": "Vendor Agreements & Zero Data Retention: Manages external LLM provider boundaries and multi-tenant isolation.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, Zero Data Retention, ZDR, LLM.", "Enforces Zero Data Retention (ZDR) agreements and Business Associate Agreements (BAA) with LLM cloud providers.", "Deploys self-hosted or dedicated single-tenant model endpoints (e.g., AWS Bedrock private tenancy, vLLM on private EKS).", "Implements multi-tenant data partitioning in vector databases using partition keys or isolated namespaces."]}, {"id": "KP4", "description": "Guardrails, Jailbreak Prevention & Compliance Auditing: Enforces egress security and compliance logging.", "required": false, "acceptable_evidence": ["Technical keywords: data leakage, prompt injection, jailbreak, output guardrails.", "Applies output guardrails (e.g., NeMo Guardrails, Llama Guard) to inspect generated responses for sensitive data leakage.", "Protects against prompt injection and data extraction attacks using input sanitization and delimiter bounding.", "Maintains immutable access logs with SIEM integration (Splunk, CloudWatch) for SOC2/HIPAA audit trails."]}], "critical_failures": ["Sends sensitive or unredacted enterprise data to public commercial LLM APIs without enterprise privacy agreements.", "Fails to articulate multi-tenant isolation or network-level security controls in regulated environments."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate a strong hire, and what behaviors indicate success in an AI or tooling-focused team?', '{"key_points": [{"id": "KP1", "description": "Core Technical & Engineering Competencies: Identifies key skills required for building reliable AI systems.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, AI, API, CI.", "Assesses deep understanding of non-deterministic systems, debugging complex pipelines, and evaluation methodologies.", "Evaluates strong software engineering hygiene (clean architecture, testing, API design, CI/CD) alongside ML knowledge."]}, {"id": "KP2", "description": "Tests practical problem-solving over theoretical trivia through realistic coding or system design exercises.", "required": true, "acceptable_evidence": ["Technical keywords: live pair programming, architectural trade-offs, debugging exercise, production scenario, code review.", "Tests practical problem-solving over theoretical trivia through realistic coding or system design exercises.", "Evaluates candidates using realistic troubleshooting scenarios, system design whiteboard sessions, and hands-on debugging rather than rote algorithmic trivia."]}, {"id": "KP3", "description": "Behavioral Indicators & Mindset: Highlights curiosity, resilience with ambiguous problems, and ownership.", "required": true, "acceptable_evidence": ["Technical keywords: bias for shipping, premature optimization, AI.", "Looks for intellectual curiosity and rapid adaptation to rapidly evolving AI tooling and research.", "Values pragmatic trade-off decision making (bias for shipping vs premature optimization).", "Assesses intellectual honesty when models fail and rigor in root-cause analysis rather than prompt tinkering."]}, {"id": "KP4", "description": "Collaboration & Team Culture: Assesses communication, mentorship, and cross-functional empathy.", "required": false, "acceptable_evidence": ["Technical keywords: culture, assesses, mentorship, cross.", "Evaluates ability to communicate technical uncertainties clearly to product managers and non-technical stakeholders.", "Looks for constructive code review culture, pair programming openness, and knowledge sharing.", "Identifies team-first attitudes that prioritize overall product velocity over individual credit."]}], "critical_failures": ["Focuses solely on resume credentials or academic pedigree without assessing hands-on software engineering rigor.", "Ignores behavioral signals such as adaptability, collaboration, and dealing with ambiguous non-deterministic problems."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate and compare opportunities when transitioning from a contract role to a full-time position?', '{"key_points": [{"id": "KP1", "description": "Technical Ownership & Roadmap Impact: Evaluates long-term system ownership versus short-term task execution.", "required": true, "acceptable_evidence": ["Technical keywords: architecture, scaling, roadmap, impact.", "Prioritizes full lifecycle ownership (architecture, deployment, monitoring, scaling) over temporary deliverable handoffs.", "Evaluates ability to influence the multi-year technology stack and product vision."]}, {"id": "KP2", "description": "Assesses opportunities to build foundational platform infrastructure rather than isolated feature patches.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD automation, Terraform IaC, shared microservices, observability platform, developer tooling.", "Assesses opportunities to build foundational platform infrastructure rather than isolated feature patches.", "Focuses on building reusable core services, centralized telemetry pipelines, and infrastructure-as-code modules rather than temporary one-off feature patches."]}, {"id": "KP3", "description": "Compensation, Equity & Stability: Analyzes total reward structure and organizational stability.", "required": true, "acceptable_evidence": ["Technical keywords: base salary, equity, stock options, 401k.", "Compares hourly contract rates against full-time total compensation (base salary, equity/stock options, healthcare, 401k).", "Assesses company financial health, runway, funding stage, and headcount stability.", "Weighs employment protections and long-term career safety versus contract volatility."]}, {"id": "KP4", "description": "Cultural Alignment & Team Growth: Considers mentorship, community, and personal career progression.", "required": false, "acceptable_evidence": ["Technical keywords: cultural alignment, cultural, growth, mentorship.", "Evaluates engineering leadership culture, code review standards, and team learning environment.", "Assesses internal promotion ladders, staff-level technical leadership tracks, and skill development support.", "Considers team camaraderie and integration into company mission compared to contract outsider status."]}], "critical_failures": ["Shows no structured framework for comparing roles, focusing only on superficial factors.", "Fails to articulate the difference in ownership and long-term technical impact between contract and full-time employment."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate new opportunities, and what aspects are most important to you when considering a role?', '{"key_points": [{"id": "KP1", "description": "Technical Challenge & Impact: Evaluates problem complexity and alignment with AI engineering domain.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, AI, challenge, impact.", "Prioritizes high-impact technical problems (e.g. real-world AI adoption, low-latency inference, production RAG).", "Looks for opportunities to solve non-trivial engineering challenges rather than building commodity wrappers."]}, {"id": "KP2", "description": "Assesses modern technical stack and engineering practices within the prospective team.", "required": true, "acceptable_evidence": ["Technical keywords: Docker containerization, Kubernetes, FastAPI, PyTorch, Prometheus, LangGraph, automated testing.", "Assesses modern technical stack and engineering practices within the prospective team.", "Evaluates engineering hygiene, including containerized deployments, modern async frameworks (FastAPI), comprehensive pytest coverage, and CI/CD pipelines."]}, {"id": "KP3", "description": "Team Caliber & Engineering Leadership: Assesses the quality and values of potential peers and management.", "required": true, "acceptable_evidence": ["Technical keywords: caliber, engineering, potential, assesses.", "Evaluates technical competency of engineering managers and prospective peers.", "Assesses psychological safety, culture of constructive feedback, and blameless retrospectives.", "Looks for leaders who provide mentorship while granting autonomy and ownership."]}, {"id": "KP4", "description": "Business Viability & Personal Growth: Considers long-term career trajectory and company stability.", "required": false, "acceptable_evidence": ["Technical keywords: product-market fit, viability, personal, growth.", "Evaluates company business model, product-market fit, and economic stability.", "Considers career trajectory, clear progression paths, and skill expansion in emerging technologies.", "Balancing work-life boundaries, flexibility, and overall compensation package."]}], "critical_failures": ["Cannot articulate what factors make an opportunity appealing beyond compensation alone.", "Shows no interest in team dynamics, technical challenge, or engineering culture."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate opportunities across different company sizes and domains when making career decisions?', '{"key_points": [{"id": "KP1", "description": "Startup vs Enterprise Trade-offs: Demonstrates clear analysis of speed, scope, resources, and governance.", "required": true, "acceptable_evidence": ["Technical keywords: established compliance, startup, trade, clear.", "Identifies startup strengths: rapid iteration, broad ownership, low bureaucracy, immediate customer impact.", "Identifies enterprise strengths: high scale, specialized tooling, established compliance/security, mentorship resources."]}, {"id": "KP2", "description": "Recognizes startup risks (runway, shifting priorities) vs enterprise constraints (tech debt, slower approvals).", "required": true, "acceptable_evidence": ["Technical keywords: runway management, technical debt, release velocity, regulatory compliance, engineering autonomy.", "Recognizes startup risks (runway, shifting priorities) vs enterprise constraints (tech debt, slower approvals).", "Weighs the risk of short startup financial runways against enterprise bureaucratic release cycles, change approval boards, and accumulated legacy tech debt."]}, {"id": "KP3", "description": "Domain Complexity & Data Matures: Evaluates industry-specific challenges (e.g. Healthcare, Finance, SaaS).", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA, SEC, FINRA, Finance.", "Recognizes regulatory hurdles (HIPAA in healthcare, SEC/FINRA in finance) and how they shape engineering pace.", "Assesses data availability and quality maturity across domains (clean warehouses vs sparse messy logs).", "Aligns personal domain interest with business mission and ethical considerations."]}, {"id": "KP4", "description": "Career Stage & Personal Fit: Reflects on how company size aligns with current professional development goals.", "required": false, "acceptable_evidence": ["Technical keywords: career, stage, personal, reflects.", "Articulates why their current career stage benefits from either broad generalist startup ownership or deep enterprise specialization.", "Shows adaptability to adjust engineering approach based on organizational maturity.", "Demonstrates clear self-awareness regarding comfort with ambiguity vs structured processes."]}], "critical_failures": ["Demonstrates one-dimensional bias without understanding the legitimate trade-offs between startup agility and enterprise scale.", "Fails to acknowledge how domain regulations or company scale impact software engineering workflows."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How do you evaluate team collaboration practices, such as pair programming and user research sessions, in improving AI product development?', '{"key_points": [{"id": "KP1", "description": "Pair Programming in AI Engineering: Details how collaborative coding enhances quality and knowledge sharing.", "required": true, "acceptable_evidence": ["Technical keywords: AI, ML, complex graph, data parsers.", "Explains how pair programming accelerates debugging non-deterministic AI pipeline behaviors and complex graph architectures.", "Facilitates rapid cross-skilling between ML engineers and backend infrastructure engineers.", "Reduces defect escape rates in critical production components (guardrails, evaluation pipelines, data parsers)."]}, {"id": "KP2", "description": "User Research Integration: Connects direct user observation to AI prompt and UX improvements.", "required": true, "acceptable_evidence": ["Technical keywords: UX, research, integration, AI.", "Observes actual end-user interaction to identify real failure modes, prompt confusion, and edge cases.", "Uses user feedback to refine system tone, output structure, citation presentation, and confidence thresholds.", "Prevents engineering teams from optimizing irrelevant offline metrics that do not correlate with user satisfaction."]}, {"id": "KP3", "description": "Operational Cadence & Trade-offs: Balances collaborative time investment with deep individual focus.", "required": false, "acceptable_evidence": ["Technical keywords: complex refactor, tricky bug triage, cadence, trade.", "Balances pair programming sessions with uninterrupted deep work blocks for algorithmic exploration.", "Establishes clear goals for pairing sessions (e.g. complex refactor, tricky bug triage) to maximize efficiency.", "Translates qualitative user research sessions into structured test cases for golden evaluation datasets."]}], "critical_failures": ["Dismisses collaborative practices or user research as a waste of engineering time.", "Fails to connect user feedback to tangible AI system improvements like prompt tuning or evaluation datasets."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate the risks and long-term potential of joining a startup in a highly competitive AI market?', '{"key_points": [{"id": "KP1", "description": "Defensibility & Technical Moat: Evaluates proprietary differentiation beyond simple API wrappers.", "required": true, "acceptable_evidence": ["Technical keywords: API, IP, OpenAI feature releases.", "Assesses whether the product has a proprietary data flywheel, domain-specific evaluation, or deep workflow integration.", "Differentiates vulnerable ''thin wrapper'' startups from systems with genuine IP (custom orchestrators, proprietary models, fine-tuned adapters).", "Evaluates threat of commoditization from foundational model provider updates (e.g., OpenAI feature releases)."]}, {"id": "KP2", "description": "Unit Economics & Inference Costs: Analyzes cost structure, token consumption, and margin sustainability.", "required": true, "acceptable_evidence": ["Technical keywords: prompt caching, unit economics, token API billing, API.", "Analyzes inference compute costs (GPU hosting vs token API billing) relative to customer subscription pricing.", "Considers cost optimization strategies: prompt caching, model routing, smaller specialized SLMs vs frontier LLMs.", "Assesses burn rate and runway in relation to infrastructure and token expenses."]}, {"id": "KP3", "description": "Team Execution & Regulatory Exposure: Evaluates founding team capability and compliance risks.", "required": false, "acceptable_evidence": ["Technical keywords: product-market fit, fit metrics, exposure, founding.", "Evaluates technical leadership track record in shipping scalable software and adapting to market shifts.", "Considers regulatory headwinds, copyright risks, and data licensing exposure in target industries.", "Assesses product-market fit metrics such as retention, organic usage growth, and workflow stickiness."]}], "critical_failures": ["Fails to recognize the fragility of thin API wrappers facing foundation model provider encroachment.", "Ignores AI unit economics, inference costs, or proprietary data moats when assessing startup viability."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate whether a role aligns more with AI/ML versus Generative AI, and what are your expectations for such a role?', '{"key_points": [{"id": "KP1", "description": "Predictive ML vs Generative AI Workflows: Distinguishes core technical methodologies and objectives.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, XGBoost, ML, AI.", "Defines traditional ML: supervised/unsupervised algorithms (XGBoost, Scikit-learn), feature engineering, mathematical loss minimization, tabular data.", "Defines Generative AI: foundation models, prompting, context engineering, RAG pipelines, agentic orchestration, non-deterministic generation."]}, {"id": "KP2", "description": "Contrasts training from scratch / feature stores with pre-trained model adaptation / retrieval grounding.", "required": true, "acceptable_evidence": ["Technical keywords: classical ML vs GenAI, feature store, Feast, PyTorch, LoRA fine-tuning, RAG retrieval grounding, Milvus.", "Contrasts training from scratch / feature stores with pre-trained model adaptation / retrieval grounding.", "Contrasts classical ML workflows (training scikit-learn/PyTorch models from scratch, feature stores like Feast) with Generative AI (RAG with Milvus, prompt engineering, LoRA adapters)."]}, {"id": "KP3", "description": "Evaluation, Tooling & Infrastructure: Contrasts development stacks and validation paradigms.", "required": true, "acceptable_evidence": ["Technical keywords: Pandas, LangGraph, Milvus, cross-validation.", "Traditional ML stack: MLflow, Feast, Pandas, AUC-ROC, F1-score, RMSE, cross-validation.", "GenAI stack: LangGraph, Milvus, Presidio, DeepEval, Hit Rate, Faithfulness, LLM-as-a-judge, token monitoring.", "Differentiates deterministic regression testing from qualitative semantic evaluation."]}, {"id": "KP4", "description": "Role Expectations & Engineering Hybridization: Explains practical responsibilities and personal orientation.", "required": false, "acceptable_evidence": ["Technical keywords: ML, BGE, BGE reranker, intent classifiers.", "Articulates expectations for system integration, latency optimization, and guardrail enforcement in GenAI roles.", "Recognizes modern hybrid architectures combining traditional ML (e.g. BGE reranker, intent classifiers) with GenAI LLMs.", "Clearly states personal career preferences and technical depth in either or both domains."]}], "critical_failures": ["Conflates traditional predictive modeling with Generative AI prompting and RAG architectures.", "Cannot differentiate the metrics, tooling, or infrastructure used in ML vs Generative AI systems."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate working in a small, fast-paced, and ambiguous startup environment compared to a large organization?', '{"key_points": [{"id": "KP1", "description": "Navigating Ambiguity & Self-Direction: Thrives with minimal specification and rapidly evolving priorities.", "required": true, "acceptable_evidence": ["Technical keywords: navigating, direction, thrives, minimal.", "Demonstrates ability to formulate technical specs and architecture when user stories are unformed or ambiguous.", "Acts with high autonomy, making sound engineering decisions without requiring constant supervisory approval."]}, {"id": "KP2", "description": "Pivots quickly when customer feedback or market signals invalidate previous hypotheses.", "required": true, "acceptable_evidence": ["Technical keywords: MVP prototyping, rapid pivot, sunk cost fallacy, customer feedback loops, startup velocity, sprint cadence.", "Pivots quickly when customer feedback or market signals invalidate previous hypotheses.", "Pivots architecture and feature roadmaps rapidly based on early customer analytics and feedback loops without getting attached to sunk engineering costs."]}, {"id": "KP3", "description": "Engineering Speed vs Technical Debt: Pragmatically balances rapid delivery against long-term stability.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, automated tests, basic security.", "Ships functional MVPs rapidly to validate product assumptions with live users.", "Consciously manages technical debt, documenting shortcuts and refactoring foundational paths as scale grows.", "Avoids premature over-engineering while establishing critical safeguards (automated tests, logging, basic security)."]}, {"id": "KP4", "description": "Cross-Functional Versatility: Willingness to wear multiple hats across the product lifecycle.", "required": false, "acceptable_evidence": ["Technical keywords: data pipelines, cross, versatility, willingness.", "Assists across frontend, backend, devops, data pipelines, and customer support when needed.", "Collaborates directly with founders, sales, and end users to understand pain points.", "Maintains composure and positive momentum in high-pressure, resource-constrained environments."]}], "critical_failures": ["Requires rigid corporate processes, complete specifications, and dedicated support teams to make progress.", "Paralyzed by ambiguous requirements or resists making decisions without management consensus."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you handle ambiguous requirements during project planning and requirement gathering?', '{"key_points": [{"id": "KP1", "description": "Stakeholder Discovery & Scope Clarification: Deconstructs high-level business goals through structured inquiry.", "required": true, "acceptable_evidence": ["Technical keywords: budget, stakeholder, discovery, scope.", "Conducts targeted stakeholder discovery sessions to identify user personas, primary workflows, and pain points.", "Maps input data availability, expected system outputs, latency bounds, and traffic volumes.", "Separates hard constraints (security, regulatory, budget) from flexible nice-to-have features."]}, {"id": "KP2", "description": "Prototyping & Technical Spike Exploration: Uses rapid POCs and Request for Comments (RFCs) to de-risk unknowns.", "required": true, "acceptable_evidence": ["Technical keywords: RFC, detailing trade-offs, success metrics, RFCs.", "Builds minimal technical spikes or proof-of-concept prototypes to validate architectural assumptions.", "Drafts Request for Comments (RFC) or Architecture Decision Records (ADRs) detailing trade-offs, schemas, and risks.", "Establishes quantifiable acceptance criteria and success metrics (e.g., accuracy thresholds, throughput)."]}, {"id": "KP3", "description": "Iterative Feedback Loops & Risk Management: Validates incrementally with users to prevent misaligned builds.", "required": false, "acceptable_evidence": ["Technical keywords: feedback loops, iterative, feedback, loops.", "Breaks ambiguous monolithic initiatives into phased, testable milestones with regular demo cadences.", "Maintains living specification documents that evolve with stakeholder clarifications.", "Implements defensive software design allowing modular component substitution as requirements solidify."]}], "critical_failures": ["Begins full-scale engineering on vague requirements without attempting clarification or stakeholder validation.", "Lacks any systematic discovery or documentation process (RFC, ADR, acceptance criteria) to resolve ambiguities."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle collaboration in remote teams and across different time zones?', '{"key_points": [{"id": "KP1", "description": "Asynchronous Communication Hygiene: Employs thorough written documentation to enable independent progress.", "required": true, "acceptable_evidence": ["Technical keywords: Notion, Confluence, Slack, Loom.", "Writes detailed pull request descriptions, context-rich commit messages, and clear issue tickets.", "Documents design decisions, architecture diagrams, and meeting summaries asynchronously (Notion, Confluence, Slack).", "Records concise video or demo walkthroughs (Loom) to explain complex workflows without requiring real-time meetings."]}, {"id": "KP2", "description": "Time Zone Management & Work Hand-Offs: Optimizes overlap windows and enables round-the-clock progress.", "required": true, "acceptable_evidence": ["Technical keywords: urgent alignment, management, overlap, windows.", "Maximizes overlapping hours for critical unblocking discussions, code pairing, and urgent alignment.", "Structures daily hand-off summaries so teammates in earlier or later time zones can seamlessly pick up work.", "Respects teammate local working hours, avoiding expectations of off-hours immediate message responses."]}, {"id": "KP3", "description": "Proactive Alignment & Remote Culture: Prevents silos and fosters interpersonal trust.", "required": false, "acceptable_evidence": ["Technical keywords: proactive alignment, proactive, remote, culture.", "Proactively surfaces blockers early in standups or team channels rather than waiting in silence.", "Participates actively in virtual team building, retrospectives, and social check-ins.", "Assumes positive intent and practices empathetic, clear communication in written chats."]}], "critical_failures": ["Relies entirely on synchronous meetings to convey information, causing bottlenecks in remote distributed teams.", "Fails to document context or manage handoffs across differing time zones."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle conflicts within a team, and what strategies do you use to resolve disagreements effectively?', '{"key_points": [{"id": "KP1", "description": "De-escalation & Active Listening: Listens with empathy to understand differing perspectives without personal bias.", "required": true, "acceptable_evidence": ["Technical keywords: active, listening, listens, empathy.", "Initiates 1-on-1 private conversations promptly to address friction before resentment escalates.", "Practices active listening to genuinely understand the colleague''s technical rationale and underlying concerns."]}, {"id": "KP2", "description": "Maintain a blameless, empathetic stance, separating ideas from personal egos.", "required": true, "acceptable_evidence": ["Technical keywords: blameless culture, objective benchmarking, RFC review, active listening, conflict resolution, consensus building.", "Maintains a blameless, empathetic stance, separating ideas from personal egos.", "Maintains a blameless, empathetic stance by separating architectural proposals from personal egos and using objective benchmarks (latency profiles, RFC reviews) to resolve disputes."]}, {"id": "KP3", "description": "Data-Driven Resolution: Resolves technical disagreements using empirical benchmarks and prototypes.", "required": true, "acceptable_evidence": ["Technical keywords: frames trade-offs, cost, ADRs, matrix scoring.", "Proposes building quick benchmark spikes or A/B tests to evaluate competing approaches with objective data.", "Frames trade-offs against shared business goals (latency, cost, maintainability) rather than personal preference.", "Applies formal decision frameworks (ADRs, matrix scoring) to reach transparent technical consensus."]}, {"id": "KP4", "description": "Disagree and Commit: Aligns with the finalized decision and maintains strong team cohesion.", "required": false, "acceptable_evidence": ["Technical keywords: disagree, commit, aligns, finalized.", "Demonstrates ability to ''disagree and commit'' wholeheartedly once a leadership or team consensus is reached.", "Follows up to ensure interpersonal relationships remain positive and productive post-resolution.", "Reflects on lessons learned to refine team architectural debate processes."]}], "critical_failures": ["Handles conflict through passive-aggressive behavior, personal attacks, or complete avoidance.", "Refuses to compromise or commit to team decisions when their own preferred approach is not chosen."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle situations where dependencies on other teams block your progress?', '{"key_points": [{"id": "KP1", "description": "Technical Decoupling & Mocking: Unblocks forward progress by building contract mocks and synthetic data.", "required": true, "acceptable_evidence": ["Technical keywords: API, UI, api schemas, OpenAPI.", "Agrees on API schemas/contracts (OpenAPI, protobuf) with dependency team early and mocks responses.", "Generates synthetic datasets or stubs to continue downstream development, testing, and UI integration."]}, {"id": "KP2", "description": "Designs modular interfaces that allow plugging in the real dependency once delivered with minimal refactoring.", "required": true, "acceptable_evidence": ["Technical keywords: API contract mocking, WireMock, in-memory stubs, interface decoupling, cross-team dependency tracking, blocker escalation.", "Designs modular interfaces that allow plugging in the real dependency once delivered with minimal refactoring.", "Mocks unreleased upstream services using defined API contracts (OpenAPI schemas, WireMock, or in-memory stubs) to unblock local development."]}, {"id": "KP3", "description": "Proactive Cross-Team Communication: Surfaces blockers transparently and aligns on priority timelines.", "required": true, "acceptable_evidence": ["Technical keywords: proactive, cross, surfaces, blockers.", "Communicates blocker impact early in shared channels, sprint standups, or scrum-of-scrums.", "Collaborates directly with dependency team to understand their constraints and explore reduced-scope unblockers.", "Escalates through engineering managers with clear business impact if cross-team priorities remain misaligned."]}, {"id": "KP4", "description": "Backlog Realignment & Alternative Value Delivery: Pivots to alternative high-value deliverables while waiting.", "required": false, "acceptable_evidence": ["Technical keywords: technical debt, PR, reviewing their PR, contributing upstream code.", "Shifts immediate sprint focus to other high-priority roadmap tasks, technical debt, or documentation.", "Assists the blocking team directly (e.g. reviewing their PR or contributing upstream code) if feasible.", "Documents timeline impacts and adjusts downstream delivery expectations proactively."]}], "critical_failures": ["Becomes entirely idle and halts work without attempting to mock dependencies or surface blockers.", "Fails to communicate dependency delays until deadlines are missed."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle situations where the root cause of an issue lies outside your immediate responsibility but still impacts the user experience?', '{"key_points": [{"id": "KP1", "description": "End-to-End Ownership Mentality: Prioritizes user experience regardless of organizational fault boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Jaeger, mentality, experience.", "Rejects ''not my problem'' attitude; treats degraded user experience as a personal priority to solve.", "Traces issue end-to-end through distributed logs, traces (Jaeger, OpenTelemetry), and network hops to pin down the root cause."]}, {"id": "KP2", "description": "Collects concrete telemetry evidence (reproduction steps, error payloads, timestamped traces) to present to the responsible team.", "required": true, "acceptable_evidence": ["Technical keywords: distributed trace spans, reproduction payload, Datadog, CloudWatch, defensive fallback, incident ownership.", "Collects concrete telemetry evidence (reproduction steps, error payloads, timestamped traces) to present to the responsible team.", "Gathers reproducible HTTP request/response payloads, Datadog/CloudWatch trace spans, and error logs before filing a high-priority incident ticket with the owning team."]}, {"id": "KP3", "description": "Defensive Resiliency & Fallback Engineering: Implements graceful degradation within their own service.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, UI.", "Adds circuit breakers, caching fallbacks, or meaningful default responses so upstream outages don''t break the user experience.", "Displays empathetic, transparent error messaging in the UI rather than silent failures or raw stack traces.", "Implements retry mechanisms with exponential backoff and jitter to survive transient upstream hiccups."]}, {"id": "KP4", "description": "Collaborative Partnering & Long-Term Fix: Works with external team to prevent recurrence.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, collaborative, partnering, recurrence.", "Pairs constructively with the external service owner to help debug and patch the underlying flaw.", "Advocates for automated integration tests or contract tests across service boundaries.", "Contributes to blameless post-mortem analysis with shared remediation action items."]}], "critical_failures": ["Abandons the issue because the faulty component belongs to another team, ignoring customer impact.", "Fails to implement defensive fallbacks or graceful degradation within their own service."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle working in environments with fluctuating workloads, tight deadlines, and high expectations for delivery?', '{"key_points": [{"id": "KP1", "description": "Ruthless Prioritization & Scope Negotiation: Manages delivery by focusing on essential high-impact deliverables.", "required": true, "acceptable_evidence": ["Technical keywords: MVP, ruthless, scope, negotiation.", "Decomposes monolithic deadlines into core MVP deliverables vs deferrable secondary features.", "Negotiates sprint scope proactively with product managers rather than over-committing and failing silently."]}, {"id": "KP2", "description": "Apply the 80/20 rule to deliver the highest value user capabilities under tight constraints.", "required": true, "acceptable_evidence": ["Technical keywords: Pareto 80/20 rule, scope management, milestone delivery, backlog grooming, velocity tracking, trade-off communication.", "Applies the 80/20 rule to deliver the highest value user capabilities under tight constraints.", "Applies the Pareto principle (80/20 rule) to scope down deliverables to core functional requirements that unblock business milestones on time."]}, {"id": "KP3", "description": "Quality Safeguards Under Pressure: Maintains engineering discipline without cutting catastrophic corners.", "required": true, "acceptable_evidence": ["Technical keywords: feature flags, CI/CD, CI, CD.", "Preserves non-negotiable standards: automated regression tests, peer code reviews, and security scanning.", "Tracks deliberate technical shortcuts in a debt backlog with scheduled remediation post-launch.", "Avoids frantic unreviewed hotfixes by relying on feature flags and automated CI/CD pipelines."]}, {"id": "KP4", "description": "Personal Resilience & Team Support: Maintains sustainable pace and supports team morale.", "required": false, "acceptable_evidence": ["Technical keywords: personal, resilience, sustainable, morale.", "Communicates bandwidth limits transparently to prevent burnout across sustained crunches.", "Fosters calm, supportive communication and assists overwhelmed teammates with critical unblockers.", "Conducts post-crunch retrospectives to identify systemic causes of workload surges and improve planning."]}], "critical_failures": ["Cuts vital security or quality testing corners under deadline pressure, leading to production catastrophes.", "Accepts unrealistic deadlines passively without communicating risks, then misses delivery commitments."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you stay updated with advancements in AI, and how do you evaluate and adopt new frameworks or tools effectively?', '{"key_points": [{"id": "KP1", "description": "Research Ingestion & Continuous Learning: Curates technical information from authoritative AI sources.", "required": true, "acceptable_evidence": ["Technical keywords: AI, ICML, ICLR, GitHub.", "Follows arXiv preprints, top AI conferences (NeurIPS, ICML, ICLR), and reputable technical engineering blogs.", "Participates in open-source AI communities, GitHub repository releases, and developer discords."]}, {"id": "KP2", "description": "Distinguish substantive architectural breakthroughs (e.g. flash attention, speculative decoding) from hype.", "required": true, "acceptable_evidence": ["Technical keywords: FlashAttention-2, vLLM PagedAttention, speculative decoding, architectural evaluation, POC benchmarking, research paper review.", "Distinguishes substantive architectural breakthroughs (e.g. flash attention, speculative decoding) from hype.", "Distinguishes foundational efficiency breakthroughs (FlashAttention-2, vLLM PagedAttention, speculative decoding) from ephemeral wrappers, validating them in isolated POC benchmarks."]}, {"id": "KP3", "description": "Empirical Benchmarking & Spike Evaluation: Tests new frameworks in controlled, isolated environments.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Milvus, FastAPI, AWS.", "Constructs standardized benchmark spikes measuring latency, token throughput, memory footprint, and developer ergonomic gains.", "Tests compatibility against existing infrastructure (Milvus, FastAPI, LangGraph, AWS ECS).", "Evaluates community maturity, documentation completeness, release cadence, and issue resolution velocity."]}, {"id": "KP4", "description": "Disciplined Production Adoption Framework: Manages migration risks and avoids unnecessary framework churn.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, cost reduction, maintenance simplification.", "Requires measurable ROI (cost reduction, accuracy gain, maintenance simplification) before adopting new tools.", "Performs shadow testing or canary rollout of new models/frameworks alongside current production stack.", "Prepares rollback plans and encapsulates external library dependencies behind clean internal adapter interfaces."]}], "critical_failures": ["Adopts new AI libraries impulsively based on social media hype without benchmarking or evaluating production risks.", "Has no structured method or metrics to evaluate whether a new tool improves upon existing production baselines."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How have you designed and implemented secure authentication and registration workflows in your applications?', '{"key_points": [{"id": "KP1", "description": "Secure Registration & Password Storage: Implements salted hashing, validation, and account verification.", "required": true, "acceptable_evidence": ["Technical keywords: SQL, XSS, bcrypt, Argon2.", "Hashes passwords using slow, memory-hard algorithms (bcrypt, Argon2, PBKDF2) with unique cryptographic salts.", "Enforces password complexity policies and validates inputs against SQL injection and XSS.", "Implements email verification flows with time-limited, cryptographically secure verification tokens."]}, {"id": "KP2", "description": "Token Lifecycle & Session Management: Implements OAuth2/OIDC, short-lived JWTs, and refresh token rotation.", "required": true, "acceptable_evidence": ["Technical keywords: OIDC, JWT, refresh token, HttpOnly.", "Issues short-lived signed access tokens (JWT with RS256/ES256) and long-lived secure refresh tokens.", "Stores refresh tokens securely (HttpOnly, Secure, SameSite cookies or mobile keychain) with one-time rotation and invalidation on reuse.", "Implements multi-factor authentication (TOTP, WebAuthn) for high-security user tiers."]}, {"id": "KP3", "description": "Attack Mitigation & Observability: Protects auth endpoints against brute-force and credential stuffing.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, token bucket, Redis, IP.", "Enforces IP and account-based rate limiting on login/registration endpoints using Redis token bucket or AWS WAF.", "Employs constant-time string comparison to prevent timing attacks during credential validation.", "Logs authentication attempts (success, failure, IP, user-agent) into security audit streams without logging plain credentials."]}], "critical_failures": ["Stores passwords in plaintext or uses obsolete broken hashing algorithms like MD5 or unsalted SHA-1.", "Fails to protect token transmission or ignores brute-force attack vectors on login endpoints."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How is your previous experience relevant to this AI infrastructure role, and what are the core responsibilities concerning alerts, logs, and proactive troubleshooting?', '{"key_points": [{"id": "KP1", "description": "Telemetry & Distributed Tracing: Implements structured logging and end-to-end tracing across AI microservices.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, request_id, token_counts.", "Implements correlation IDs and distributed tracing (OpenTelemetry, Langfuse, AWS X-Ray) across gateway, agent, and vector search hops.", "Structures logs in JSON format with contextual metadata (request_id, model, token_counts, latency_ms, status_code)."]}, {"id": "KP2", "description": "Monitors infrastructure metrics (CPU, GPU memory, queue depth) alongside application metrics (p95 latency, error rates).", "required": true, "acceptable_evidence": ["Technical keywords: GPU VRAM utilization, Prometheus metrics, Grafana dashboards, P95 latency, CloudWatch alert rules, runbook automation.", "Monitors infrastructure metrics (CPU, GPU memory, queue depth) alongside application metrics (p95 latency, error rates).", "Monitors system-level metrics (GPU VRAM, CUDA utilization, CPU load) in Prometheus alongside application metrics (P95 latency, LLM token throughput) with automated Grafana alert rules."]}, {"id": "KP3", "description": "Alerting Strategy & SLO Monitoring: Calibrates actionable alerts while preventing alert fatigue.", "required": true, "acceptable_evidence": ["Technical keywords: SLO, PagerDuty, AWS, CloudWatch.", "Defines multi-window Service Level Indicators (SLIs) and Service Level Objectives (SLOs) tied to error budget burn rates.", "Configures tiered severity alerting (P1 page vs P3 Jira ticket) in PagerDuty/Opsgenie linked to AWS CloudWatch alarms.", "Implements anomaly detection on token spend, sudden spike in fallback triggers, or surge in 5xx error responses."]}, {"id": "KP4", "description": "Proactive Troubleshooting & Incident Runbooks: Executes disciplined root-cause analysis and operational runbooks.", "required": false, "acceptable_evidence": ["Technical keywords: DB, limit backoff, canary transactions, vector DB failover.", "Maintains codified operational runbooks for standard failure modes (vector DB failover, rate limit backoff, container restarts).", "Conducts proactive health checks, synthetic canary transactions, and load tests to catch degradations before users do.", "Performs blameless post-mortems with timeline reconstruction and actionable preventative engineering items."]}], "critical_failures": ["Has no structured approach to logging, relying on unstructured console prints without correlation IDs.", "Cannot articulate how to set up alerts or distinguish critical user-impacting outages from noisy warnings."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'BROAD', 150, 'How long have you been working with Generative AI, and what kinds of use cases have you implemented in that time?', '{"key_points": [{"id": "KP1", "description": "Production Use Case Architecture: Details specific deployed GenAI solutions and architectural components.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, case architecture, vector search.", "Describes concrete deployed use cases (e.g. enterprise RAG over recruiting/healthcare docs, customer support copilot, code generation, summarization).", "Articulates the technical pipeline: document ingestion, embedding generation, vector search, orchestration, prompt engineering, output formatting."]}, {"id": "KP2", "description": "Clarifies exact role and technical contributions in building, evaluating, or maintaining the system.", "required": true, "acceptable_evidence": ["Technical keywords: production GenAI delivery, LangGraph orchestration, hybrid vector search, RAGAS evaluation, latency reduction, hallucination mitigation.", "Clarifies exact role and technical contributions in building, evaluating, or maintaining the system.", "Details specific engineering contributions: designing RAG pipelines with hybrid vector search, implementing LangGraph agents, or building automated evaluation suites with RAGAS."]}, {"id": "KP3", "description": "Production Hurdles & Hallucination Mitigation: Explains how non-determinism, latency, and quality challenges were solved.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, function calling, prompt caching, output guardrails.", "Addresses mitigation of model hallucinations using grounding in retrieved chunks, citations, and output guardrails.", "Implements streaming responses, asynchronous queuing, or prompt caching to manage latency budgets.", "Enforces structured JSON outputs (Pydantic, function calling) to reliably parse model responses into downstream systems."]}, {"id": "KP4", "description": "Evolution & Technology Trajectory: Shows progression from basic prompting to sophisticated architectures.", "required": false, "acceptable_evidence": ["Technical keywords: LangGraph, tool calling, GPT-3, GPT.", "Traces journey from naive single-prompt completions to advanced agentic workflows (LangGraph, tool calling, multi-agent collaboration).", "Evaluates progression across model generations (e.g., GPT-3.5 to GPT-4o, Claude 3.5 Sonnet, open-source Llama 3/Mistral).", "Demonstrates mature perspective on when simple deterministic code is superior to complex LLM invocations."]}], "critical_failures": ["Speaks only in high-level generic buzzwords without describing a single concrete implemented AI application.", "Cannot explain how real production challenges (hallucinations, latency, structured outputs) were handled in their projects."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How was the GDK outline implemented into your project?', '{"key_points": [{"id": "KP1", "description": "SDK Lifecycle & Interface Binding: Integrates core GDK abstractions and lifecycle events into application architecture.", "required": true, "acceptable_evidence": ["Technical keywords: WebSockets, SDK, GDK, IPC.", "Integrates GDK lifecycle hooks, event listeners, and hardware/platform state management into app lifecycle.", "Implements wrapper classes or adapter layers to decouple vendor GDK calls from core business logic.", "Configures required manifest permissions, low-level drivers, or communication channels (Bluetooth, WebSockets, IPC)."]}, {"id": "KP2", "description": "Resource Management & Asynchronous Handling: Handles hardware constraints, threading, and battery/power profiles.", "required": true, "acceptable_evidence": ["Technical keywords: GDK, UI, main loop.", "Offloads heavy GDK sensor/media processing to background worker threads to keep UI/main loop unblocked.", "Optimizes power consumption and memory footprint to accommodate device hardware boundaries.", "Implements graceful fallback handling when platform capabilities or network connectivity are unavailable."]}, {"id": "KP3", "description": "Testing, Build Automation & Compatibility: Manages SDK versioning, mock emulation, and automated builds.", "required": false, "acceptable_evidence": ["Technical keywords: CI, SDK, GDK.", "Builds mock SDK stubs or emulator harnesses for local unit and integration testing without physical hardware.", "Manages GDK dependency versioning and backward compatibility across differing device firmware releases.", "Integrates hardware build targets into continuous integration (CI) pipelines."]}], "critical_failures": ["Binds vendor SDK calls directly throughout UI components without abstraction or architectural separation.", "Fails to manage asynchronous execution or resource limits, causing application freezing or crashes."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you adapt your teaching approach based on learners- backgrounds, experience levels, and programming skills?', '{"key_points": [{"id": "KP1", "description": "Audience Assessment & Scaffolding: Diagnoses learner background and breaks complex concepts into progressive milestones.", "required": true, "acceptable_evidence": ["Technical keywords: audience, scaffolding, diagnoses, learner.", "Assesses prior programming experience, math background, and mental models before diving into advanced material.", "Uses relatable analogies and high-level architectural mental models for novices before introducing syntax."]}, {"id": "KP2", "description": "Skips foundational syntax and dives straight into architectural nuances, concurrency, or performance for experienced engineers.", "required": true, "acceptable_evidence": ["Technical keywords: pedagogical adaptation, live pair programming, interactive code review, syntax vs architecture, scaffolding concepts.", "Skips foundational syntax and dives straight into architectural nuances, concurrency, or performance for experienced engineers.", "Adapts technical depth: focuses on fundamental variables, loops, and data structures for beginners while diving into concurrency, async event loops, and system design for seniors."]}, {"id": "KP3", "description": "Hands-On Practical Application: Pairs conceptual explanations with immediate interactive coding and debugging.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, REST, API, rag pipeline.", "Employs interactive coding notebooks, sandboxes, or pair-programming exercises rather than passive lectures.", "Encourages learners to read stack traces, write test cases, and debug errors independently with guided hints.", "Provides real-world use cases (e.g., building a mini RAG pipeline or REST API) to anchor theoretical knowledge."]}, {"id": "KP4", "description": "Feedback Loops & Psychological Safety: Fosters an encouraging environment with continuous comprehension checks.", "required": false, "acceptable_evidence": ["Technical keywords: feedback loops, feedback, loops, psychological.", "Creates psychological safety where asking questions and making syntax mistakes is actively encouraged.", "Runs frequent micro-comprehension checks (asking the learner to explain the concept back in their own words).", "Adjusts instructional pacing dynamically based on non-verbal cues or coding friction points."]}], "critical_failures": ["Applies a rigid one-size-fits-all lecture style regardless of whether the learner is a novice or senior engineer.", "Relies exclusively on high-level jargon without verifying comprehension or providing hands-on coding opportunities."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you clearly communicate your experience and contributions in interviews without ambiguity or overly general statements?', '{"key_points": [{"id": "KP1", "description": "Structured Narrative & Individual Ownership: Uses structured frameworks (STAR) and differentiates ''I'' from ''we''.", "required": true, "acceptable_evidence": ["Technical keywords: STAR, vector index, STAR methodology.", "Structures technical stories logically: Situation, Task, Action, and Result (STAR methodology).", "Clearly delineates their personal technical design decisions and code contributions from general team activities.", "Avoids vague passive statements (''the system was built'') in favor of active ownership (''I designed the vector index schema'')."]}, {"id": "KP2", "description": "Quantifiable Technical & Business Impact: Anchors outcomes in concrete operational and performance metrics.", "required": true, "acceptable_evidence": ["Technical keywords: p95, measurable metrics, Hit Rate 92%.", "Cites measurable metrics: latency reduction (e.g. p95 from 1.2s to 300ms), throughput, cost savings, or evaluation accuracy (Hit Rate 92%).", "Connects technical achievements directly to business outcomes (e.g., recruiter screening hours reduced by 40%).", "Explains how success was verified post-deployment using monitoring and user adoption data."]}, {"id": "KP3", "description": "Technical Precision & Intellectual Honesty: Explains architectural rationale, trade-offs, and lessons learned.", "required": false, "acceptable_evidence": ["Technical keywords: HNSW, Pinecone, Milvus, precision.", "Explains the ''why'' behind architectural choices (e.g. choosing Milvus HNSW over Pinecone due to VPC compliance).", "Discusses technical challenges, unexpected bugs, and trade-offs candidly without defensiveness.", "Adjusts technical explanation depth dynamically based on interviewer signals and questions."]}], "critical_failures": ["Speaks entirely in vague generalities (''we implemented AI for the company'') without claiming any specific personal technical contribution.", "Fails to cite any quantifiable results, metrics, or technical rationale for their work."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you collaborate with product owners and business stakeholders to define requirements, roadmap, and technical feasibility?', '{"key_points": [{"id": "KP1", "description": "Requirements Translation & Technical Feasibility: Bridges high-level product vision to pragmatic engineering architecture.", "required": true, "acceptable_evidence": ["Technical keywords: API, engineering architecture, feasibility, bridges.", "Translates vague product user stories into detailed technical specifications, API contracts, and data models.", "Evaluates technical feasibility, infrastructure dependencies, and latency/cost implications early in sprint planning."]}, {"id": "KP2", "description": "Identify hidden edge cases and non-deterministic AI risks that product stakeholders may overlook.", "required": true, "acceptable_evidence": ["Technical keywords: non-deterministic failure modes, LLM hallucination risk, technical feasibility analysis, SLO definition, MVP scoping.", "Identifies hidden edge cases and non-deterministic AI risks that product stakeholders may overlook.", "Identifies non-deterministic LLM failure modes (hallucinations, token rate limits, cold-start latency) during requirements gathering to manage expectations and define realistic SLOs."]}, {"id": "KP3", "description": "Roadmap Prioritization & Trade-off Negotiation: Negotiates scope and delivery milestones constructively.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, MVP, API.", "Partners with Product Owners to sequence high-impact MVP features vs fast-follow iterations.", "Presents clear technical trade-offs (e.g., speed of delivery vs long-term scalability, self-hosted vs SaaS API costs).", "Advocates for technical debt remediation, testing infrastructure, and observability within roadmap capacity."]}, {"id": "KP4", "description": "Continuous Communication & Feedback Loops: Maintains alignment through demos and agile rituals.", "required": false, "acceptable_evidence": ["Technical keywords: feedback loops, continuous, feedback, loops.", "Runs regular sprint demos and working sessions to gather early feedback on prototype behavior.", "Communicates unforeseen blockers or scope changes proactively before milestone deadlines.", "Fosters mutual respect and shared ownership of product success between product and engineering."]}], "critical_failures": ["Acts as an adversarial ''order-taker'' or rejects product requests without offering viable technical alternatives.", "Fails to communicate technical constraints, costs, or feasibility risks to product leadership."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you convince stakeholders and end-users to adopt an AI-based system over existing manual or legacy workflows?', '{"key_points": [{"id": "KP1", "description": "Building Trust Through Explainability & Citations: Provides transparent, verifiable AI outputs to overcome skepticism.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, AI, clear guardrails.", "Equips AI responses with clickable source citations, exact document references, and confidence scores.", "Designs human-in-the-loop review mechanisms so users retain control and final approval over critical actions.", "Demonstrates clear guardrails preventing harmful hallucinations or rogue automated actions."]}, {"id": "KP2", "description": "Empirical Proof & Side-by-Side Validation: Proves superiority over legacy workflows with measurable data.", "required": true, "acceptable_evidence": ["Technical keywords: side validation, empirical, proof, AI.", "Runs side-by-side pilot comparisons benchmarking AI turnaround time and accuracy against manual baseline processes.", "Demonstrates concrete productivity multipliers (e.g., reducing 45-minute manual document review to 2 minutes).", "Invites skeptical domain experts to evaluate golden test sets and participate in system calibration."]}, {"id": "KP3", "description": "Change Management & UX Friction Reduction: Minimizes workflow disruption through seamless integration.", "required": false, "acceptable_evidence": ["Technical keywords: UX, ATS, CRM, Slack.", "Embeds AI seamlessly into existing user tools (Slack, ATS, CRM, internal web portal) rather than forcing new dashboards.", "Conducts training sessions, creates walkthrough guides, and actively gathers user feedback to resolve pain points.", "Celebrates early user wins and champions internal power users to drive viral adoption."]}], "critical_failures": ["Forces AI adoption through top-down mandates without addressing user trust, accuracy fears, or workflow disruption.", "Fails to provide citations, explainability, or human review mechanisms to validate probabilistic AI outputs."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you describe your communication style in a team setting?', '{"key_points": [{"id": "KP1", "description": "Clarity, Conciseness & Active Listening: Communicates directly while valuing team input.", "required": true, "acceptable_evidence": ["Technical keywords: precision, clarity, conciseness, active.", "Communicates technical thoughts with structured precision, avoiding rambling or ambiguous jargon.", "Practices active listening during discussions, validating understanding before formulating counterarguments."]}, {"id": "KP2", "description": "Welcomes diverse perspectives and solicits input from quieter team members during meetings.", "required": true, "acceptable_evidence": ["Technical keywords: asynchronous-first, RFC documentation, pull request etiquette, active listening, transparent communication.", "Welcomes diverse perspectives and solicits input from quieter team members during meetings.", "Practices proactive, transparent, and asynchronous-first communication via detailed design docs (RFCs) and clear pull request descriptions."]}, {"id": "KP3", "description": "Proactive Transparency & Blocker Communication: Shares status, risks, and blockers openly.", "required": true, "acceptable_evidence": ["Technical keywords: proactive, blocker, shares, status.", "Surfaces impediments and potential delivery risks immediately in standups and shared chat channels.", "Communicates mistakes and production incidents transparently with a blameless root-cause focus.", "Provides regular, succinct progress updates on complex tasks without requiring managerial micromanagement."]}, {"id": "KP4", "description": "Audience Adaptation & Asynchronous Hygiene: Adapts message delivery to technical and non-technical stakeholders.", "required": false, "acceptable_evidence": ["Technical keywords: RFCs, pull request summaries, ticket comments.", "Translates low-level architectural nuances into business impact for product and executive stakeholders.", "Invests in high-quality asynchronous written documentation (RFCs, pull request summaries, ticket comments).", "Maintains a respectful, encouraging, and collaborative tone across all communication channels."]}], "critical_failures": ["Hoards information, works in isolation, or hides technical blockers until deadlines are blown.", "Cannot adapt communication style when talking to non-technical team members or cross-functional peers."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you describe your ideal team and hiring manager?', '{"key_points": [{"id": "KP1", "description": "Leadership Style & Manager Support: Values mentorship, clear context, and autonomy over micromanagement.", "required": true, "acceptable_evidence": ["Technical keywords: style, manager, mentorship, clear.", "Values a manager who provides clear strategic context, unblocks team obstacles, and shields the team from noise.", "Appreciates autonomy to solve problems technically while receiving actionable feedback during regular 1-on-1s."]}, {"id": "KP2", "description": "Values a manager who supports career development, skill expansion, and professional recognition.", "required": true, "acceptable_evidence": ["Technical keywords: psychological safety, autonomous ownership, blameless post-mortems, engineering rigor, career mentorship.", "Values a manager who supports career development, skill expansion, and professional recognition.", "Looks for engineering leadership that fosters psychological safety, empowers autonomous decision-making, and supports professional development with rigorous code reviews."]}, {"id": "KP3", "description": "Team Culture & Psychological Safety: Flourishes in collaborative, blameless, high-standard environments.", "required": true, "acceptable_evidence": ["Technical keywords: pairing, knowledge-sharing brown bags, culture, psychological.", "Describes a culture of psychological safety where team members openly discuss failures and take smart risks.", "Values high engineering craftsmanship, rigorous code reviews, and shared ownership of system quality.", "Enjoys collaborative peer interactions (pairing, technical debates, knowledge-sharing brown bags)."]}, {"id": "KP4", "description": "Self-Alignment & Contribution to the Ideal: Articulates personal role in fostering this desired culture.", "required": false, "acceptable_evidence": ["Technical keywords: contribution, ideal, articulates, personal.", "Explains how they personally contribute to team morale, mentoring junior engineers, and onboarding newcomers.", "Demonstrates adaptability to work effectively even when team conditions are imperfect or evolving.", "Shows appreciation for diversity of thought, background, and technical viewpoints within a team."]}], "critical_failures": ["Expresses desire for complete isolation without managerial check-ins or accountability.", "Demonstrates toxic cultural expectations (blame-oriented culture, hostility toward code reviews or process)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you design a system to auto-generate test sequences or test plans using AI within a hardware verification workflow?', '{"key_points": [{"id": "KP1", "description": "Hardware Spec Parsing & Test Plan Generation: Ingests architectural specs to generate comprehensive test coverage matrices.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, AXI, AHB, LLM.", "Ingests hardware specifications (register maps, bus protocol specs like AXI/AHB, functional block specs) via RAG pipeline.", "Uses LLM to generate structured test plans mapping functional requirements to verification coverage targets (cross-coverage, functional bins)."]}, {"id": "KP2", "description": "Formats test plans into standard spreadsheets or YAML matrices integrated with verification management tools.", "required": true, "acceptable_evidence": ["Technical keywords: SystemVerilog, UVM testbench, YAML test matrix, hardware verification, Cadence, Synopsys, constraint-random testing.", "Formats test plans into standard spreadsheets or YAML matrices integrated with verification management tools.", "Generates structured YAML test plans and SystemVerilog/UVM constraint sequences validated against hardware interface specifications (PCIe, AXI) for automated simulator ingestion."]}, {"id": "KP3", "description": "Constrained-Random Sequence Synthesis: Generates valid SystemVerilog / UVM sequence code.", "required": true, "acceptable_evidence": ["Technical keywords: generators, SystemVerilog, UVM, honoring protocol.", "Synthesizes UVM sequence items, sequence macros, and constrained-random stimulus generators honoring protocol rules.", "Injects domain-specific verification rules into system prompts to prevent illegal bus states or deadlock sequences.", "Generates directed corner-case tests (boundary values, back-to-back transactions, error injection) targeting unreached coverage holes."]}, {"id": "KP4", "description": "Compilation, Simulation Loop & Formal Verification: Integrates with EDA simulation tools and verifies correctness.", "required": false, "acceptable_evidence": ["Technical keywords: EDA, VCS, LLM, SVA.", "Implements automated compiler/linter feedback loop (VCS, Questa, Xcelium) where syntax errors trigger iterative LLM self-correction.", "Validates generated sequences against formal property verification (SVA assertions) before regression suite inclusion.", "Measures incremental code and functional coverage improvements to evaluate AI test quality."]}], "critical_failures": ["Generates pure unconstrained random numbers without understanding hardware protocols or UVM testbench architecture.", "Fails to provide any validation loop (compilation/simulation) to verify that generated test sequences are syntactically and functionally valid."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you design modular, reusable AI systems that can support multiple teams and use cases?', '{"key_points": [{"id": "KP1", "description": "Shared Core Abstractions & Decoupling: Provides reusable building blocks for ingestion, retrieval, and orchestration.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, MCP, Milvus, vector indexing.", "Designs shared platform modules: unified document parsing (Docling), vector indexing (Milvus), and model gateways.", "Provides pluggable agent orchestration interfaces (e.g., standard LangGraph node templates or MCP tool wrappers)."]}, {"id": "KP2", "description": "Encapsulates model providers behind standard unified SDKs/APIs with centralized rate limiting and fallback routing.", "required": true, "acceptable_evidence": ["Technical keywords: AI Gateway, unified SDK, rate limiting, semantic caching, provider failover, tenant isolation, reusable microservice.", "Encapsulates model providers behind standard unified SDKs/APIs with centralized rate limiting and fallback routing.", "Builds an internal AI Gateway microservice that wraps diverse LLM providers behind a standardized OpenAI-compatible API interface with centralized rate limiting and semantic caching."]}, {"id": "KP3", "description": "Multi-Tenant Isolation & Governance: Ensures secure data separation, access control, and cost chargebacks.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, RBAC, PII, tenant isolation.", "Enforces strict multi-tenant data isolation via collection partitioning, tenant namespaces, and RBAC policies.", "Tracks token usage and infrastructure costs on a per-team/per-project basis for chargeback or showback.", "Maintains centralized security guardrails, PII redaction, and compliance auditing across all participating teams."]}, {"id": "KP4", "description": "Developer Experience & Self-Service Onboarding: Enables team autonomy through templates and documentation.", "required": false, "acceptable_evidence": ["Technical keywords: CLI, API, CloudWatch, Langfuse.", "Provides self-service scaffolding CLI, starter repository templates, and comprehensive API documentation.", "Exposes centralized observability (Langfuse, CloudWatch) dashboards pre-configured for every onboarding team.", "Runs internal office hours and architecture review sessions to assist client teams with bespoke customizations."]}], "critical_failures": ["Proposes building bespoke, siloed AI systems from scratch for every team without shared platform infrastructure.", "Fails to address multi-tenant data isolation, security guardrails, or usage attribution across teams."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you handle a client-facing engineering role where you must translate business requirements into technical solutions?', '{"key_points": [{"id": "KP1", "description": "Consultative Discovery & Business Translation: Uncovers true operational needs and maps them to technical architectures.", "required": true, "acceptable_evidence": ["Technical keywords: p95, p95 latency, p95 latency <800ms, Hit Rate >90%.", "Conducts structured client stakeholder interviews to uncover root business problems rather than accepting surface-level feature requests.", "Translates high-level business goals (e.g., reduce support handle time) into concrete system requirements (p95 latency <800ms, Hit Rate >90%)."]}, {"id": "KP2", "description": "Documents technical specifications and system architecture diagrams in language accessible to client business leaders.", "required": true, "acceptable_evidence": ["Technical keywords: C4 architecture model, technical discovery workshop, SLA definition, client stakeholder alignment, data flow diagrams.", "Documents technical specifications and system architecture diagrams in language accessible to client business leaders.", "Authors system architecture diagrams (C4 model), API data flow charts, and executive summaries that bridge technical depth with business ROI during client discovery workshops."]}, {"id": "KP3", "description": "Expectation Scoping & Managing Constraints: Handles technical feasibility, budget, and scope creep.", "required": true, "acceptable_evidence": ["Technical keywords: API, expectation, managing, AI.", "Sets realistic expectations around AI capabilities, probabilistic generation, and necessary data quality prerequisites.", "Manages scope creep diplomatically by establishing formal change request processes and phased milestone rollouts.", "Presents technical trade-offs transparently (e.g., latency vs accuracy, SaaS API costs vs self-hosted infrastructure)."]}, {"id": "KP4", "description": "Client Communication & Executive Demonstrations: Delivers high-impact presentations and builds executive trust.", "required": false, "acceptable_evidence": ["Technical keywords: client, executive, demonstrations, delivers.", "Conducts compelling interactive demos focusing on user workflow improvements rather than raw code.", "Maintains executive presence, professionalism, and calmness when addressing skeptical client stakeholders.", "Establishes weekly cadence reports with transparent tracking of milestones, deliverables, and risks."]}], "critical_failures": ["Treats client interactions with technical arrogance or dismisses client business concerns as unimportant.", "Agrees unconditionally to impossible client requirements without communicating technical constraints or costs."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you plan your transition from your current role to ensure a smooth and timely onboarding into the new venture?', '{"key_points": [{"id": "KP1", "description": "Professional Offboarding & Knowledge Transfer: Leaves current team well-documented and fully supported.", "required": true, "acceptable_evidence": ["Technical keywords: professional, offboarding, knowledge, transfer.", "Authors comprehensive offboarding documentation, architecture runbooks, and open ticket status handoffs.", "Conducts dedicated 1-on-1 walkthroughs and code pairing with successor engineers on critical components.", "Ties up loose ends, completes or delegates ongoing PRs, and avoids leaving behind unmaintained zombie code."]}, {"id": "KP2", "description": "Rapid Onboarding & 30-60-90 Day Ramp-Up: Proactively drives learning and early impact in the new role.", "required": true, "acceptable_evidence": ["Technical keywords: PR, drive architecture, codebase architecture, understand code.", "Sets clear 30-60-90 day milestones: 30 days (understand code, ship first PR), 60 days (own a component), 90 days (drive architecture).", "Proactively sets up local development environment, runs tests, and audits codebase architecture in week one.", "Schedules 1-on-1 coffee chats with key engineering and product peers to understand team priorities and domain context."]}, {"id": "KP3", "description": "Cultural Acclimation & Early Value Delivery: Delivers small, high-leverage contributions early.", "required": false, "acceptable_evidence": ["Technical keywords: cultural, acclimation, value, delivers.", "Picks up bug fixes or documentation improvements early to validate the deployment pipeline and build credibility.", "Observes existing team conventions, code review culture, and communication norms before proposing major overhauls.", "Aligns closely with manager expectations through frequent feedback check-ins during the first month."]}], "critical_failures": ["Plans an abrupt exit from current role without knowledge transfer or handoff documentation.", "Has no structured onboarding strategy, expecting to be passively spoon-fed tasks for months."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you prepare for introductory startup interviews that focus on your background and motivation?', '{"key_points": [{"id": "KP1", "description": "Crisp Narrative Arc & Authentic Motivation: Communicates career progression and genuine excitement for the startup''s mission.", "required": true, "acceptable_evidence": ["Technical keywords: product market, founder vision, crisp, narrative.", "Delivers a cohesive 2-3 minute elevator pitch connecting past technical experiences to the company''s current stage.", "Articulates specific reasons for joining this particular startup (product market, technical challenge, founder vision) rather than generic desire.", "Highlights passion for high-velocity iteration, end-to-end product impact, and startup dynamism."]}, {"id": "KP2", "description": "Demonstrating Startup Cultural Alignment: Highlights comfort with ambiguity, grit, and broad ownership.", "required": true, "acceptable_evidence": ["Technical keywords: cultural alignment, devops, frontend, customer debugging.", "Shares stories demonstrating resourcefulness and shipping with minimal supervision under tight resource constraints.", "Shows willingness to wear multiple hats (devops, frontend, customer debugging) beyond narrow job descriptions.", "Demonstrates resilience and composure when priorities shift rapidly in response to customer feedback."]}, {"id": "KP3", "description": "Targeted Company Research & Thoughtful Inquiries: Displays deep preparation and strategic curiosity.", "required": false, "acceptable_evidence": ["Technical keywords: unit economics, targeted, company, research.", "Has thoroughly researched company product, competitive landscape, tech stack, and recent press/releases.", "Asks insightful, non-generic questions regarding unit economics, key architectural bottlenecks, and near-term product milestones.", "Maintains high energy, professionalism, and conversational engagement throughout the interview."]}], "critical_failures": ["Gives a rambling, unfocused background walkthrough without clear relevance to the startup or role.", "Reveals preference for corporate bureaucracy, rigid specialization, or complete aversion to risk and ambiguity."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you structure and collaborate within a team when transitioning a project from POC to production with additional engineers joining?', '{"key_points": [{"id": "KP1", "description": "Architectural Hardening & Code Modularization: Modularizes monolithic POC code to enable parallel engineering streams.", "required": true, "acceptable_evidence": ["Technical keywords: POC, API, configuration schemas, ingestion.", "Refactors scrappy POC code into clean modular microservices or bounded packages (ingestion, retrieval, API, agent).", "Replaces hardcoded configurations and credentials with environment variables, secrets managers, and configuration schemas."]}, {"id": "KP2", "description": "Define clean API contracts and interface boundaries so multiple new engineers can work simultaneously without merge conflicts.", "required": true, "acceptable_evidence": ["Technical keywords: API contracts, interface boundaries, modular architecture, Git branch strategy, parallel development.", "Defines clean API contracts and interface boundaries so multiple new engineers can work simultaneously without merge conflicts.", "Defines explicit OpenAPI interface boundaries and abstract base classes so multiple engineers can implement backend services concurrently without merge conflicts."]}, {"id": "KP3", "description": "Engineering Standards & CI/CD Pipeline: Establishes testing, code quality gates, and automated deployments.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, CI/CD, GitHub Actions, CI.", "Sets up automated CI/CD pipelines (GitHub Actions) with linters (Ruff/Flake8), type checks (Mypy), and unit/integration test suites.", "Implements branch protection rules, PR templates, and required peer reviews to maintain code quality.", "Creates comprehensive developer onboarding guides, Docker compose setups, and seed datasets for local environments."]}, {"id": "KP4", "description": "Team Collaboration & Mentorship Cadence: Organizes sprint ceremonies, ownership areas, and pair programming.", "required": false, "acceptable_evidence": ["Technical keywords: UI, data pipelines, UI integration, standups.", "Assigns clear component ownership (e.g. data pipelines, evaluation harness, UI integration) to incoming engineers.", "Pairs with new teammates on their first PRs to walk through system architecture and design idioms.", "Establishes lightweight agile rituals (standups, sprint planning, tech demos) to maintain alignment and momentum."]}], "critical_failures": ["Deploys raw hacky POC code directly to production without testing, modularization, or CI/CD pipelines.", "Fails to establish onboarding documentation or branching conventions, leading to chaotic team coordination."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 90, 'In GraphQL, what is the purpose of types, queries, and mutations, and how do they work together?', '{"key_points": [{"id": "KP1", "description": "Type System & Schema Definition Language: Explains GraphQL types as strongly typed structural contracts.", "required": true, "acceptable_evidence": ["Technical keywords: GraphQL, ID, SDL, Int.", "Defines Object types, Scalar types (Int, Float, String, Boolean, ID), Input types, Enums, and custom scalars in SDL.", "Explains non-nullable fields (!) and list wrappers ([Type]) in establishing strict client-server contracts."]}, {"id": "KP2", "description": "Contrasts typed graph schemas with weakly typed REST endpoints in preventing over-fetching and under-fetching.", "required": true, "acceptable_evidence": ["Technical keywords: GraphQL schema, SDL, over-fetching, under-fetching, DataLoader, N+1 query problem, REST comparison.", "Contrasts typed graph schemas with weakly typed REST endpoints in preventing over-fetching and under-fetching.", "Contrasts GraphQL''s strongly typed schema and client-specified field selection with REST''s fixed endpoint payloads, eliminating over-fetching while using DataLoader to batch DB calls."]}, {"id": "KP3", "description": "Queries vs Mutations & Operational Semantics: Differentiates read-only queries from write mutations.", "required": true, "acceptable_evidence": ["Technical keywords: mutations, semantics, idempotent, operations.", "Explains Queries as idempotent read-only operations that traverse the graph to retrieve specified fields.", "Explains Mutations as explicit write operations (create, update, delete) causing server-side side effects.", "Notes operational execution difference: query fields run in parallel; mutation root fields execute serially to prevent race conditions."]}, {"id": "KP4", "description": "Resolvers, DataLoader & Production Considerations: Explains how types, queries, and mutations execute.", "required": false, "acceptable_evidence": ["Technical keywords: DataLoader, nested graph, resolvers, mutations.", "Details how root queries and mutations map to resolver functions that fetch data from databases or downstream microservices.", "Explains the N+1 query problem in nested graph traversal and how DataLoader uses batching/caching to solve it.", "Addresses query complexity limits, depth limiting, and authentication/authorization at the resolver level."]}], "critical_failures": ["Conflates queries and mutations, claiming they have identical operational and execution semantics.", "Cannot explain what types are in GraphQL or how resolvers execute requests against the schema."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'Walk me through the clustering problem you solved.', '{"key_points": [{"id": "KP1", "description": "Problem Formulation & Feature Preprocessing: Prepares data and addresses distance-metric sensitivity.", "required": true, "acceptable_evidence": ["Technical keywords: Euclidean distance, StandardScaler, MinMaxScaler, PCA.", "Defines the business objective (e.g. customer segmentation, anomaly grouping, document clustering).", "Performs feature scaling (StandardScaler, MinMaxScaler) to prevent dominant numeric ranges in Euclidean distance.", "Applies dimensionality reduction (PCA, UMAP, t-SNE) for high-dimensional or sparse data to combat the curse of dimensionality."]}, {"id": "KP2", "description": "Algorithm Selection & Hyperparameter Tuning: Justifies algorithm and determines optimal cluster count.", "required": true, "acceptable_evidence": ["Technical keywords: min_samples, DBSCAN, WCSS, optimal cluster.", "Selects and justifies algorithm (K-Means for spherical clusters, DBSCAN for density/noise, Hierarchical for taxonomies).", "Determines optimal k using mathematical heuristics: Elbow method (inertia/WCSS), Silhouette analysis, Davies-Bouldin index.", "Handles algorithm-specific parameters (e.g., eps and min_samples for DBSCAN, initialization with k-means++)."]}, {"id": "KP3", "description": "Cluster Interpretation & Business Validation: Evaluates cluster quality and operational utility.", "required": false, "acceptable_evidence": ["Technical keywords: profiles cluster, temporal consistency, personalized recommendations, targeted workflows.", "Profiles cluster centroids to extract meaningful domain personas and distinct behavioral traits.", "Validates cluster stability using bootstrap resampling or cross-temporal consistency checks.", "Integrates cluster assignments into downstream applications (e.g., personalized recommendations, targeted workflows)."]}], "critical_failures": ["Applies K-Means without scaling features, ignoring the effect of feature magnitude on distance metrics.", "Cannot explain how the number of clusters was chosen or how cluster quality was evaluated."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Walk me through the infrastructure you provisioned.', '{"key_points": [{"id": "KP1", "description": "Networking & Compute Topology: Architects secure VPC networking and compute orchestration.", "required": true, "acceptable_evidence": ["Technical keywords: load balancer, Kubernetes, VPC, NAT.", "Configures VPC architecture with public/private subnets across multiple Availability Zones, NAT Gateways, and Route Tables.", "Provisions containerized compute (AWS ECS Fargate, EKS Kubernetes, or EC2 Auto Scaling Groups) behind an Application Load Balancer.", "Implements network isolation keeping database and internal AI services in private subnets without public IPs."]}, {"id": "KP2", "description": "Storage, Caching & Managed Services: Provisions persistent data stores and caching tiers.", "required": true, "acceptable_evidence": ["Technical keywords: Pinecone, Milvus, PostgreSQL, Redis.", "Provisions relational databases (Amazon RDS PostgreSQL with Multi-AZ failover) and caching (ElastiCache Redis).", "Provisions vector database instances (Milvus cluster on Kubernetes or managed OpenSearch/Pinecone).", "Configures Amazon S3 buckets with server-side encryption (KMS), lifecycle rules, and versioning for document storage."]}, {"id": "KP3", "description": "Infrastructure as Code & Security Governance: Automates deployment using IaC and least privilege IAM.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, Terraform, Infrastructure as Code, IaC.", "Defines entire infrastructure in Terraform / OpenTofu with modular reusable modules, remote S3 state backend, and DynamoDB locking.", "Enforces least-privilege IAM roles and policies for ECS task execution, Lambda functions, and CI/CD pipelines.", "Configures CloudWatch log groups, Prometheus metrics scrapers, and CloudTrail audit logging."]}], "critical_failures": ["Deploys critical production databases and backend servers into public subnets with 0.0.0.0/0 open ingress.", "Manages cloud infrastructure solely via manual AWS console clicks without any Infrastructure as Code."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'We need to know a little bit about you - can you tell me your most recent background, education, and any recent work you''ve had, or internships?', '{"key_points": [{"id": "KP1", "description": "Academic & Foundational Overview: Summarizes relevant educational background and computer science grounding.", "required": true, "acceptable_evidence": ["Technical keywords: science grounding, succinctly states, academic, foundational.", "Succinctly states degree (Computer Science, Engineering, Data Science, or related technical field) and relevant coursework.", "Highlights strong foundational knowledge in algorithms, system architecture, database theory, or machine learning.", "Transitions smoothly from academic foundation to professional career trajectory."]}, {"id": "KP2", "description": "Recent Work Experience & Technical Impact: Highlights concrete engineering projects and contributions.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, Milvus, FastAPI.", "Details recent role and responsibilities (e.g. building RAG pipelines, microservices, agentic workflows, data platforms).", "Highlights specific technologies mastered (Python, LangGraph, Milvus, FastAPI, Docker, AWS, PostgreSQL).", "Articulates concrete business outcomes or technical achievements delivered in recent projects/internships."]}, {"id": "KP3", "description": "Delivery Style & Alignment with Target Role: Demonstrates professionalism, enthusiasm, and relevant domain interest.", "required": false, "acceptable_evidence": ["Technical keywords: AI, style, target, professionalism.", "Delivers an engaging, well-paced pitch in 2-3 minutes without getting bogged down in minutiae.", "Expresses genuine passion for building robust, production-grade AI systems.", "Connects past learning and engineering milestones directly to the technical requirements of the prospective role."]}], "critical_failures": ["Provides a completely disjointed or rambling monologue without mentioning education or recent work.", "Fails to mention any technical tools, systems, or responsibilities from their recent experience."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What approach would you take to resolve interpersonal conflicts while maintaining professionalism and team productivity?', '{"key_points": [{"id": "KP1", "description": "Private, Empathetic Engagement: Resolves personal friction discreetly and with emotional intelligence.", "required": true, "acceptable_evidence": ["Technical keywords: empathetic, engagement, resolves, personal.", "Moves interpersonal discussions to a private 1-on-1 setting rather than publicly in Slack channels or standups.", "Maintains a calm, respectful tone and seeks to understand personal frustrations or underlying stressors.", "Assumes positive intent and avoids accusing or defensive language."]}, {"id": "KP2", "description": "Focusing on Shared Objectives & Common Ground: Realigns interpersonal differences around team goals.", "required": true, "acceptable_evidence": ["Technical keywords: focusing, objectives, common, ground.", "Reframes interpersonal conflict around mutual goals: shipping a reliable product, hitting sprint milestones.", "Identifies shared values and common ground before negotiating specific working agreements.", "Establishes clear communication boundaries and expectations for future collaboration."]}, {"id": "KP3", "description": "Productivity Safeguards & Professional Follow-Through: Ensures team velocity and team morale are preserved.", "required": false, "acceptable_evidence": ["Technical keywords: HR, productivity, safeguards, professional.", "Prevents interpersonal tension from spilling over into code reviews, architectural debates, or other team members.", "Checks in after a few days to ensure working relationship is healthy and productive.", "Knows when to involve an engineering manager or HR if interpersonal behavior becomes hostile or unmanageable."]}], "critical_failures": ["Engages in hostile public arguments, passive-aggressive retaliation, or gossip within the team.", "Refuses to work with colleagues due to personal friction, harming team productivity."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'BROAD', 90, 'What are the core components of Apache Spark, and how do they interact in large-scale data processing workflows?', '{"key_points": [{"id": "KP1", "description": "Cluster Architecture & Master-Worker Topology: Explains Driver, Cluster Manager, Executors, and Worker Nodes.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes, SparkSession, SparkContext, DAG.", "Details the Driver Program: creates SparkSession/SparkContext, converts code into DAG execution plan, coordinates tasks.", "Details the Cluster Manager (YARN, Kubernetes, Mesos, Standalone): allocates compute resources across the cluster."]}, {"id": "KP2", "description": "Detail Executors on Worker Nodes: long-running JVM processes that execute assigned tasks and store partitioned data in memory/disk.", "required": true, "acceptable_evidence": ["Technical keywords: Spark Executor, Worker Node, JVM process, task execution, block manager, off-heap memory, garbage collection.", "Details Executors on Worker Nodes: long-running JVM processes that execute assigned tasks and store partitioned data in memory/disk.", "Explains that Executors are dedicated JVM worker processes that run task threads, cache RDD partitions in memory/disk, and report status back to the Driver."]}, {"id": "KP3", "description": "Execution Lifecycle & DAG Scheduling: Explains Jobs, Stages, Tasks, and Catalyst Optimization.", "required": true, "acceptable_evidence": ["Technical keywords: lazy evaluation, Catalyst optimizer, DAG, TaskScheduler.", "Explains how lazy evaluation compiles transformations into a DAG, optimized by the Catalyst Optimizer.", "Details DAGScheduler breaking jobs into Stages at wide shuffle boundaries (e.g. groupBy, join).", "Explains TaskScheduler distributing individual task units across executor cores for parallel execution on data partitions."]}, {"id": "KP4", "description": "Memory Management & Data Abstractions: Differentiates RDDs, DataFrames, and unified memory.", "required": false, "acceptable_evidence": ["Technical keywords: heap, DataFrames, unified memory, heap memory.", "Differentiates low-level RDDs from optimized DataFrames/Datasets using Project Tungsten off-heap memory and code generation.", "Explains Spark unified memory manager partitioning heap into Execution Memory (shuffles/joins) vs Storage Memory (caching).", "Discusses narrow transformations (map, filter - no shuffle) vs wide transformations (reduceByKey, join - cross-network shuffle)."]}], "critical_failures": ["Believes Spark Driver executes all data processing tasks locally in a single machine memory space.", "Cannot differentiate Driver from Executor, or does not understand that wide transformations cause network shuffles."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What are the key considerations when designing applications that must support both web and mobile clients?', '{"key_points": [{"id": "KP1", "description": "API Gateway & Client Adaptation (BFF Pattern): Tailors payload size and endpoints to client capabilities.", "required": true, "acceptable_evidence": ["Technical keywords: GraphQL, gRPC, API, BFF.", "Implements Backend-for-Frontend (BFF) pattern or GraphQL to allow mobile clients to request trimmed payloads.", "Minimizes payload overhead (JSON compression via Gzip/Brotli, Protobuf/gRPC) to save mobile cellular bandwidth.", "Consolidates chatty multi-request web flows into single batched endpoints for high-latency mobile networks."]}, {"id": "KP2", "description": "Offline Resilience & State Synchronization: Handles intermittent connectivity and client caching.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, WebSockets, UI, FCM.", "Implements local caching (SQLite, Room, IndexedDB) with optimistic UI updates for seamless offline experience.", "Employs conflict resolution strategies (CRDTs, Last-Write-Wins, client-server version vectors) upon network reconnection.", "Utilizes push notifications (APNs, FCM) and WebSockets/SSE for real-time state synchronization."]}, {"id": "KP3", "description": "Authentication, Versioning & Device Constraints: Manages long-lived mobile sessions and API deprecation.", "required": false, "acceptable_evidence": ["Technical keywords: refresh token, HttpOnly cookies, API, HttpOnly.", "Implements secure biometric auth and refresh token rotation on mobile keychains vs HttpOnly cookies on web.", "Maintains strict API backward compatibility and semantic versioning due to delayed mobile app store release updates.", "Optimizes background sync to conserve device battery and avoid OS termination."]}], "critical_failures": ["Serves heavy desktop payloads to mobile clients over slow cellular networks without compression or field filtering.", "Ignores mobile offline scenarios, network drops, or backward compatibility across older installed mobile app versions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What are the key considerations when working with large-scale data systems in AI-driven applications?', '{"key_points": [{"id": "KP1", "description": "High-Throughput Ingestion & Storage Architecture: Implements scalable ingestion and tiered storage.", "required": true, "acceptable_evidence": ["Technical keywords: Delta Lake, parquet, Kafka, columnar storage.", "Decouples data producers and consumers using distributed streaming queues (Kafka, AWS Kinesis).", "Implements tiered lakehouse storage (Parquet/Delta Lake on S3) partitioned by date, tenant, or entity ID.", "Batches writes and utilizes columnar storage formats with snappy/zstd compression for query speed and cost."]}, {"id": "KP2", "description": "Data Quality, Schema Drift & Lineage: Ensures clean, validated data feeds AI models.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, DBT, DLQ, AI.", "Enforces strict schema validation (Great Expectations, Pydantic, Protobuf) at ingestion boundaries to prevent schema drift.", "Maintains automated data lineage (OpenLineage, dbt) to trace document versions feeding vector embeddings or training sets.", "Quarantines malformed records in Dead Letter Queues (DLQ) for alerting and remediation."]}, {"id": "KP3", "description": "Indexing & Vector Search Scalability: Addresses embedding generation throughput and vector search latency.", "required": false, "acceptable_evidence": ["Technical keywords: HNSW, Milvus, recall, TTL.", "Batches text embeddings and utilizes GPU-accelerated inference workers to keep pace with ingestion volume.", "Configures vector index parameters (Milvus HNSW M/efConstruction or IVF-PQ) balancing recall against search latency.", "Implements incremental re-indexing and TTL eviction policies to prevent index bloat."]}], "critical_failures": ["Performs synchronous, unbatched writes to relational databases or vector indices during high-volume ingestion.", "Has no schema validation or data quality checks, allowing corrupt data to silently degrade downstream AI models."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What aspects of your professional experience best demonstrate your ability to solve problems and deliver successful outcomes?', '{"key_points": [{"id": "KP1", "description": "Complex Technical Problem Formulation: Clearly outlines a non-trivial engineering obstacle.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, severe latency, rag pipeline, data pipeline.", "Frames a challenging real-world problem (e.g., severe latency in RAG pipeline, high false-positive rate, production outage, data pipeline bottleneck).", "Analyzes why initial conventional approaches fell short or failed.", "Articulates the business and engineering stakes involved in resolving the problem."]}, {"id": "KP2", "description": "Innovative Technical Action & Execution: Details rigorous root-cause analysis and implementation.", "required": true, "acceptable_evidence": ["Technical keywords: quantization, dense search, profilers.", "Conducts disciplined diagnostic profiling (profilers, distributed traces, query explain plans).", "Implements an innovative, scalable solution (e.g. hybrid sparse/dense search, query caching, async worker queue, model quantization).", "Demonstrates hands-on engineering execution and persistence through iterations."]}, {"id": "KP3", "description": "Quantifiable Outcome & Organizational Value: Proves tangible business and technical success.", "required": false, "acceptable_evidence": ["Technical keywords: concrete metrics, 85% drop, $50k, year.", "Cites concrete metrics: latency reduction (e.g., 85% drop), cost savings ($50k/year), accuracy gain, or uptime stability.", "Shares lasting engineering impact (e.g., adopted as company-wide standard, unblocked enterprise client rollout).", "Reflects on key architectural takeaways and how it shaped subsequent engineering designs."]}], "critical_failures": ["Presents a trivial or routine assignment (''I wrote a script someone asked for'') without demonstrating genuine problem-solving.", "Fails to provide any measurable outcome or evidence of technical success."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What factors do you consider when transitioning an AI system from MVP/POC to enterprise-scale production?', '{"key_points": [{"id": "KP1", "description": "Reliability, Latency & Concurrency Hardening: Transforms POC scripts into robust distributed microservices.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, POC, API, request latency.", "Replaces unhandled API calls with timeouts, circuit breakers, exponential backoff, and graceful fallbacks.", "Scales compute horizontally behind load balancers with autoscaling policies driven by queue depth or request latency."]}, {"id": "KP2", "description": "Implement asynchronous processing for long-running generation tasks to meet SLA targets.", "required": true, "acceptable_evidence": ["Technical keywords: Celery workers, RabbitMQ, SQS, async task execution, webhook callbacks, SLA targets.", "Implements asynchronous processing for long-running generation tasks to meet SLA targets.", "Offloads long-running generative tasks to asynchronous background worker queues (Celery/RabbitMQ or AWS SQS), returning job IDs immediately to satisfy low-latency API SLAs."]}, {"id": "KP3", "description": "Governance, Guardrails & Evaluation Gates: Installs safety checks and automated evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset, prompt injection, output guardrails, HIPAA.", "Deploys input/output guardrails (Presidio PII masking, toxicity/hallucination checks, prompt injection shields).", "Integrates automated golden dataset evaluation (DeepEval/Ragas) in CI/CD before any prompt or model update deploys.", "Enforces enterprise RBAC, audit logging, and data privacy compliance (SOC2, HIPAA)."]}, {"id": "KP4", "description": "Production Observability & Cost Governance: Tracks system health, drift, and unit economics.", "required": false, "acceptable_evidence": ["Technical keywords: prompt caching, data drift, unit economics, LLM.", "Deploys LLM observability (Langfuse, CloudWatch) capturing traces, user feedback, token consumption, and latency distributions.", "Monitors for data drift, retrieval quality degradation, and user sentiment over time.", "Optimizes model costs via prompt caching, routing simple queries to smaller models, and provisioned throughput."]}], "critical_failures": ["Believes deploying a POC to production simply requires uploading a Jupyter notebook or wrapping a script in a basic endpoint.", "Ignores security guardrails, automated evaluation, or production monitoring."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What internal teams utilized the ML platform/infrastructure you developed, and what types of projects were those teams focused on?', '{"key_points": [{"id": "KP1", "description": "Stakeholder Personas & Diverse Workflows: Identifies different internal teams and their technical requirements.", "required": true, "acceptable_evidence": ["Technical keywords: API, SQL, BI, experimentation.", "Identifies internal consumer groups: Data Scientists (model training/experimentation), Backend Engineers (API integration), Analysts (SQL/BI dashboards).", "Understands differing needs: low-latency online inference vs large-scale batch processing vs ad-hoc analytics."]}, {"id": "KP2", "description": "Provides tailored interfaces: Python SDK for data scientists, REST/gRPC endpoints for backend engineers, web UI for operators.", "required": true, "acceptable_evidence": ["Technical keywords: Python SDK, REST endpoints, gRPC streaming, internal ML platform, developer experience, self-service UI.", "Provides tailored interfaces: Python SDK for data scientists, REST/gRPC endpoints for backend engineers, web UI for operators.", "Exposes multi-tier platform interfaces: a pip-installable Python SDK for data scientists, low-latency gRPC/REST APIs for backend services, and a web dashboard for operations."]}, {"id": "KP3", "description": "Concrete Supported Projects & Business Impact: Details actual models and workflows running on the platform.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, project isolation, Feast, MLflow.", "Details deployed projects: fraud detection, recommender systems, customer call center RAG, document parsing.", "Explains how the platform accelerated model time-to-market (e.g. deployment time reduced from months to days).", "Demonstrates multi-project isolation, shared feature stores (Feast), and model registries (MLflow)."]}, {"id": "KP4", "description": "Platform Operations, SLA & User Feedback: Manages reliability and developer satisfaction.", "required": false, "acceptable_evidence": ["Technical keywords: SLA, inference latency, platform, operations.", "Maintains platform uptime and inference latency SLAs for client engineering teams.", "Gathers ongoing feedback from data science consumers to refine platform APIs and compute resource quotas.", "Provides onboarding workshops and reusable template repositories to streamline adoption."]}], "critical_failures": ["Cannot name the internal teams using the platform or describes a system with zero actual internal users.", "Fails to explain what business problems or models were supported by the infrastructure."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What is AB testing? How did you implement it in your current projects? Why do you need AB testing?', '{"key_points": [{"id": "KP1", "description": "A/B Testing Principles & Hypothesis Formulation: Explains randomized controlled trials and statistical baselines.", "required": true, "acceptable_evidence": ["Technical keywords: A/B testing, hypothesis, formulation, randomized.", "Defines A/B testing as controlled randomized experimentation comparing variant B against control A under identical conditions.", "Formulates testable null (H0) and alternative (H1) hypotheses tied to core business metrics."]}, {"id": "KP2", "description": "Explain why offline evaluation alone is insufficient due to real-world user distribution shifts and behavior differences.", "required": true, "acceptable_evidence": ["Technical keywords: offline vs online evaluation, distribution drift, user feedback loops, statistical power, sample ratio mismatch.", "Explains why offline evaluation alone is insufficient due to real-world user distribution shifts and behavior differences.", "Explains that offline test sets cannot capture real-world user intent variation, cognitive biases, or production latency friction, necessitating live controlled A/B experiments."]}, {"id": "KP3", "description": "Traffic Splitting & Deployment Architecture: Implements deterministic user assignment and rollout safety.", "required": true, "acceptable_evidence": ["Technical keywords: user_id, MurmurHash3, LaunchDarkly, API.", "Implements consistent user hashing (e.g., MurmurHash3 on user_id) to ensure persistent bucket allocation.", "Deploys feature flag systems (LaunchDarkly, Split) or API Gateway canary traffic routing (e.g., 90/10 split)."]}, {"id": "KP4", "description": "Monitors guardrail metrics (latency, error rate, uninstalls) with automated rollback triggers if degradation occurs.", "required": false, "acceptable_evidence": ["Technical keywords: guardrail metrics, p99 latency, 5xx error rate, automated rollback, Canary release, circuit breaker.", "Monitors guardrail metrics (latency, error rate, uninstalls) with automated rollback triggers if degradation occurs.", "Continuously evaluates guardrail safety metrics (P99 latency, 5xx error spike, user abandonment) with automated rollback triggers if the candidate variant degrades performance."]}, {"id": "KP5", "description": "Statistical Rigor & Decision Making: Analyzes sample size, p-values, and statistical significance.", "required": false, "acceptable_evidence": ["Technical keywords: MDE, 80%, statistical, rigor.", "Calculates required sample size and experiment duration in advance based on Minimum Detectable Effect (MDE) and statistical power (80%).", "Evaluates p-values and confidence intervals, warning against peeking problems and p-hacking.", "Makes clear ship/rollback decisions based on statistical significance without confounding seasonal variations."]}], "critical_failures": ["Does not understand what A/B testing is or confuses it with unit testing or manual QA.", "Assigns users randomly on every request rather than maintaining sticky consistent user assignment across the session."]}', 1),
('HIRING_MANAGER', 'DevOps and Cloud', 'CI/CD & GitOps', 'EASY', 'BROAD', 90, 'What is the SAFe (Scaled Agile Framework), and how does it differ from standard Agile practices in coordinating multiple teams?', '{"key_points": [{"id": "KP1", "description": "SAFe Core Principles & Architecture: Explains enterprise-scale Agile structures and Agile Release Trains.", "required": true, "acceptable_evidence": ["Technical keywords: ARTs, architecture, agile, structures.", "Explains SAFe as a framework designed to scale Agile across dozens of teams and hundreds of engineers in large enterprises.", "Defines Agile Release Trains (ARTs) as self-organizing teams of agile teams aligned to a common mission and cadence."]}, {"id": "KP2", "description": "Contrasts SAFe enterprise alignment and governance with single-team Scrum/Kanban flexibility.", "required": true, "acceptable_evidence": ["Technical keywords: SAFe, Program Increment planning, Agile Release Train, enterprise governance, Scrum, Kanban.", "Contrasts SAFe enterprise alignment and governance with single-team Scrum/Kanban flexibility.", "Contrasts SAFe''s cross-team alignment through Program Increment (PI) planning and Agile Release Trains (ARTs) with the localized autonomy of standalone Scrum or Kanban squads."]}, {"id": "KP3", "description": "Program Increment (PI) Planning & Dependency Management: Details synchronization rituals across teams.", "required": true, "acceptable_evidence": ["Technical keywords: PI, program, increment, planning.", "Explains PI Planning as a recurring cadence-based event where all teams plan the next 8-12 weeks together.", "Identifies and maps cross-team dependencies and shared architecture risks on the program board.", "Establishes committed vs uncommitted PI objectives with business value scores assigned by business owners."]}, {"id": "KP4", "description": "Governance, System Demos & Practical Trade-offs: Evaluates architectural runway and framework overhead.", "required": false, "acceptable_evidence": ["Technical keywords: ART, practical trade-offs, demos, practical.", "Conducts integrated System Demos at the ART level to validate working end-to-end software every iteration.", "Manages Architectural Runway: technical enablers built ahead of business features to ensure stability.", "Discusses trade-offs candidly: high coordination overhead and meeting fatigue vs coordinated enterprise releases."]}], "critical_failures": ["Cannot explain what SAFe stands for or believes it is identical to standard team-level Scrum.", "Fails to identify PI Planning, Agile Release Trains, or cross-team dependency synchronization."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What is the role of a data analyst compared to an AI/ML analyst?', '{"key_points": [{"id": "KP1", "description": "Analytical Focus & Core Deliverables: Distinguishes retrospective business intelligence from predictive/model analysis.", "required": true, "acceptable_evidence": ["Technical keywords: ROC-AUC, SQL, BI, AI.", "Data Analyst focus: descriptive and diagnostic analytics, historical trends, business KPIs, SQL reporting, and BI dashboards (Tableau, PowerBI).", "AI/ML Analyst focus: predictive and prescriptive modeling, feature importance, model evaluation metrics (ROC-AUC, F1, Hit Rate), and inference validation.", "Contrasts historical backward-looking reporting with forward-looking probabilistic modeling and experimentation."]}, {"id": "KP2", "description": "Technical Stack & Methodologies: Contrasts tooling, data manipulation, and validation frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: cross-validation, BI, AI, ML.", "Data Analyst stack: advanced SQL, Excel, BI tools, basic Python/R for cohort analysis and data cleaning.", "AI/ML Analyst stack: Python/Scikit-learn, statistical hypothesis testing, feature stores, model registry evaluation, and ML lifecycle tools.", "Differentiates deterministic aggregations from statistical cross-validation and machine learning error analysis."]}, {"id": "KP3", "description": "Stakeholder Collaboration & Production Impact: Explains interaction with engineering and business teams.", "required": false, "acceptable_evidence": ["Technical keywords: AI, ML, warehouse governance.", "Data Analyst partners primarily with business operations, marketing, and finance to drive data-informed decisions.", "AI/ML Analyst bridges data science teams and MLOps engineers to calibrate model behavior, monitor drift, and analyze model edge cases.", "Explains how both roles collaborate synergistically on data warehouse governance and metric definition."]}], "critical_failures": ["Claims Data Analysts and ML Analysts have identical responsibilities and technical skill sets.", "Cannot articulate the difference between descriptive business intelligence and machine learning model evaluation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'BROAD', 90, 'What is your approach to working with large-scale unstructured data and enabling user-facing applications to interact with it effectively?', '{"key_points": [{"id": "KP1", "description": "Document Ingestion & Semantic Chunking: Parses complex documents while preserving structure and context.", "required": true, "acceptable_evidence": ["Technical keywords: semantic chunking, document_id, page_number, section_header.", "Employs advanced layout-aware parsers (Docling, PyMuPDF, Unstructured) to extract text, tables, and hierarchical headings.", "Applies semantic chunking with optimal token bounds (e.g., 512 tokens with 10-20% overlap) rather than naive character splitting.", "Preserves document metadata (document_id, title, page_number, section_header, creation_date) alongside chunk payloads."]}, {"id": "KP2", "description": "Hybrid Retrieval & Reranking Architecture: Combines dense vector search with sparse keyword matching.", "required": true, "acceptable_evidence": ["Technical keywords: dense embeddings, BM25, Reciprocal Rank Fusion, RRF.", "Generates dense embeddings (e.g. BAAI/bge-large-en, text-embedding-3) indexed in Milvus using HNSW.", "Combines dense semantic retrieval with sparse keyword search (BM25) using Reciprocal Rank Fusion (RRF) for exact term matching.", "Employs a Cross-Encoder reranker (BGE-Reranker-Large) to re-score candidate chunks for maximum precision."]}, {"id": "KP3", "description": "User Interaction & Traceability: Delivers grounded generative responses with clickable citations.", "required": false, "acceptable_evidence": ["Technical keywords: UI, [Doc p. 4], Hit Rate@K, Mean Reciprocal Rank.", "Generates grounded responses strictly constrained to retrieved context with inline citation tags ([Doc p. 4]).", "Provides interactive UI features: document previews, highlighting source text snippets, and feedback thumbs up/down.", "Monitors retrieval metrics (Hit Rate@K, Mean Reciprocal Rank) and hallucination rates in production."]}], "critical_failures": ["Performs naive fixed-size chunking that splits tables and sentences arbitrarily without metadata preservation.", "Relies solely on basic keyword search or naive vector similarity without hybrid retrieval or reranking."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What is your experience with different stages of the verification lifecycle, including your involvement (or lack thereof) in tape-out?', '{"key_points": [{"id": "KP1", "description": "Verification Methodology & Testbench Architecture: Details UVM/SystemVerilog verification environments.", "required": true, "acceptable_evidence": ["Technical keywords: generators, UVM, SystemVerilog, RTL.", "Develops constrained-random verification testbenches using SystemVerilog and Universal Verification Methodology (UVM).", "Implements UVM scoreboards, drivers, monitors, and sequence generators to validate RTL against architectural specs.", "Defines functional coverage models (covergroups, coverpoints, cross-coverage) and monitors code coverage (line, branch, toggle)."]}, {"id": "KP2", "description": "Regression Management & Bug Hunting: Manages massive parallel simulations and debug workflows.", "required": true, "acceptable_evidence": ["Technical keywords: LSF, DVE, RTL, Slurm.", "Executes distributed nightly and weekend regression suites on compute farm clusters (LSF/Slurm).", "Performs waveform debugging (Verdi, DVE) to trace RTL signal mismatches and protocol violations.", "Tracks bug lifecycle using formal issue tracking, prioritizing critical corner-case design flaws."]}, {"id": "KP3", "description": "Tape-Out Criteria & Sign-Off Readiness: Explains formal verification and tape-out milestones.", "required": false, "acceptable_evidence": ["Technical keywords: RTL, SVA, JasperGold, SVA assertions.", "Articulates sign-off criteria: 100% functional and code coverage closure, zero unresolved P1/P2 RTL bugs.", "Applies formal property verification (SVA assertions, JasperGold) to mathematically prove safety and liveness properties.", "Clearly states personal extent of involvement during tape-out reviews, post-silicon bringup, or handoff to foundry."]}], "critical_failures": ["Cannot explain basic verification terminology (UVM, coverage closure, regressions, RTL simulation).", "Fails to articulate tape-out sign-off criteria or claims full ownership of tape-out without technical depth."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'EASY', 'BROAD', 90, 'What is your experience with frameworks like PyTorch and TensorFlow, and how have you used them in real-world applications?', '{"key_points": [{"id": "KP1", "description": "Execution Paradigms & Developer Ergonomics: Contrasts eager execution, dynamic graphs, and debugging.", "required": true, "acceptable_evidence": ["Technical keywords: PyTorch, autograd, tf.function, TensorFlow.", "Contrasts PyTorch''s native dynamic computation graph (autograd eager execution) with TensorFlow''s graph mode (@tf.function).", "Highlights PyTorch''s intuitive Pythonic debugging (standard pdb/breakpoints) and dominant adoption in research/GenAI."]}, {"id": "KP2", "description": "Discuss TensorFlow/Keras structured model definition and high-level training abstraction (model.fit).", "required": true, "acceptable_evidence": ["Technical keywords: TensorFlow, Keras, model.fit, tf.data pipeline, SavedModel, static computation graph, TensorRT.", "Discusses TensorFlow/Keras structured model definition and high-level training abstraction (model.fit).", "Details TensorFlow/Keras structured model training with model.fit(), tf.data input pipelines, and serialization to SavedModel for high-throughput serving via Triton or TensorRT."]}, {"id": "KP3", "description": "Production Serving & Deployment Ecosystem: Evaluates deployment tooling and inference runtimes.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, TorchScript, TorchServe, ONNX.", "Evaluates serving stacks: TorchScript / TorchServe / TensorRT / vLLM vs TensorFlow Serving / TFLite / ONNX.", "Compares ecosystem tooling: Hugging Face Transformers / PyTorch Lightning vs TensorFlow Extended (TFX) and TensorBoard.", "Addresses mobile and edge deployment considerations (TFLite vs PyTorch Mobile/ExecuTorch)."]}, {"id": "KP4", "description": "Practical Implementation & Model Training: Details real-world deep learning application experience.", "required": false, "acceptable_evidence": ["Technical keywords: Transformer, fine-tuning, FP16, BF16.", "Shares concrete project experience: fine-tuning transformer models, computer vision architectures, or embedding generation.", "Implements distributed training strategies (PyTorch DDP, FSDP, DeepSpeed) across multi-GPU setups.", "Handles mixed precision training (FP16/BF16 with torch.cuda.amp) to accelerate training and reduce VRAM usage."]}], "critical_failures": ["Believes PyTorch and TensorFlow have identical execution architectures without understanding dynamic vs static graphs.", "Cannot explain how models trained in either framework are exported and served in production."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'EASY', 'BROAD', 90, 'What is your experience with predictive analytics using sensor data, and how did you apply it for proactive issue detection?', '{"key_points": [{"id": "KP1", "description": "Sensor Stream Preprocessing & Feature Engineering: Cleans noisy temporal data and extracts domain features.", "required": true, "acceptable_evidence": ["Technical keywords: FFT, sensor drift, rolling moving averages, Kalman filters.", "Handles sensor data challenges: missing timestamps, sensor drift, variable sampling rates, noise smoothing (rolling moving averages, Kalman filters).", "Extracts time-domain features (rolling mean, variance, kurtosis, peak-to-peak) and frequency-domain features (FFT, spectral energy)."]}, {"id": "KP2", "description": "Calculates physical degradation indicators (temperature differentials, vibration harmonics, pressure drops).", "required": true, "acceptable_evidence": ["Technical keywords: sensor telemetry, FFT spectral analysis, vibration harmonics, temperature delta, anomaly detection, predictive maintenance.", "Calculates physical degradation indicators (temperature differentials, vibration harmonics, pressure drops).", "Extracts physics-based domain features (FFT vibration frequency harmonics, thermal gradient shifts) from high-frequency telemetry to detect equipment degradation before physical failure."]}, {"id": "KP3", "description": "Anomaly Detection & Failure Prediction Models: Selects and trains appropriate predictive models.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, SVM, LSTM, Autoencoders.", "Implements unsupervised anomaly detection for unlabelled sensor failure modes (Isolation Forests, Autoencoders, One-Class SVM).", "Applies supervised time-to-failure regression or classification (LSTM, XGBoost on lag features, Survival Analysis) when failure logs exist.", "Calibrates decision thresholds using Precision-Recall curves to balance early warning lead time against false alarm fatigue."]}, {"id": "KP4", "description": "Edge Ingestion, Alerting & Operational Integration: Deploys proactive alerting workflows.", "required": false, "acceptable_evidence": ["Technical keywords: Kafka, AWS, RUL, alert routing.", "Integrates with streaming platforms (AWS IoT Core, Kafka, Kinesis) for real-time sensor ingestion.", "Configures automated alert routing with severity classification and estimated Remaining Useful Life (RUL).", "Validates model efficacy through post-maintenance inspection logs and reduced unplanned downtime metrics."]}], "critical_failures": ["Treats high-frequency sensor streams as static independent rows without temporal or frequency feature extraction.", "Fails to explain how anomalies or impending equipment failures were detected or validated."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'EASY', 'BROAD', 90, 'What is your experience with unsupervised learning techniques like clustering and dimensionality reduction, and how have you applied them?', '{"key_points": [{"id": "KP1", "description": "Dimensionality Reduction Mechanics: Explains linear vs non-linear manifold projection.", "required": true, "acceptable_evidence": ["Technical keywords: PCA, SVD, SNE, UMAP.", "Explains Principal Component Analysis (PCA): orthogonal linear projection maximizing explained variance via eigendecomposition/SVD.", "Explains non-linear techniques (t-SNE, UMAP): preserving local neighborhood topology for high-dimensional embedding visualization."]}, {"id": "KP2", "description": "Apply dimensionality reduction to mitigate the curse of dimensionality, eliminate multicollinearity, and reduce compute cost.", "required": true, "acceptable_evidence": ["Technical keywords: PCA, t-SNE, UMAP, curse of dimensionality, multicollinearity, vector compression, explained variance.", "Applies dimensionality reduction to mitigate the curse of dimensionality, eliminate multicollinearity, and reduce compute cost.", "Applies PCA or UMAP to compress high-dimensional feature spaces, eliminating multicollinear columns while preserving 95%+ of variance to improve downstream clustering speed."]}, {"id": "KP3", "description": "Clustering Algorithms & Geometry: Selects appropriate algorithms based on data distribution.", "required": true, "acceptable_evidence": ["Technical keywords: DBSCAN, harabasz index, bouldin index, K-Means.", "Differentiates partition-based (K-Means), density-based (DBSCAN/HDBSCAN), and hierarchical clustering approaches.", "Highlights K-Means assumptions (spherical clusters, isotropic variance) vs DBSCAN''s ability to discover arbitrary shapes and isolate noise.", "Evaluates clustering quality quantitatively using Silhouette Score, Calinski-Harabasz Index, and Davies-Bouldin Index."]}, {"id": "KP4", "description": "Real-World Application & Downstream Integration: Applies unsupervised techniques to business problems.", "required": false, "acceptable_evidence": ["Technical keywords: world, application, downstream, integration.", "Shares concrete use cases: document topic discovery, customer segmentation, anomaly detection, or vector embedding visualization.", "Combines dimensionality reduction as a preprocessing step prior to running clustering algorithms.", "Validates cluster interpretability with business stakeholders to ensure actionable operational groupings."]}], "critical_failures": ["Uses t-SNE for feature reduction prior to general supervised learning without understanding its non-parametric out-of-sample limitations.", "Cannot explain how to evaluate clustering quality without ground-truth labels."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'EASY', 'BROAD', 90, 'What is your experience working in Agile environments, and how do you handle communication gaps or sprint delays?', '{"key_points": [{"id": "KP1", "description": "Agile Ceremonies & Iterative Velocity: Leverages Scrum rituals for continuous alignment.", "required": true, "acceptable_evidence": ["Technical keywords: continuous alignment, agile, ceremonies, iterative.", "Participates actively in sprint planning, daily standups, backlog grooming, and sprint retrospectives.", "Breaks epics into well-estimated user stories with clear Acceptance Criteria and Definition of Done."]}, {"id": "KP2", "description": "Tracks sprint burndown and team velocity to calibrate sustainable sprint commitments.", "required": true, "acceptable_evidence": ["Technical keywords: sprint burndown, velocity tracking, story point calibration, capacity planning, standup blocker escalation.", "Tracks sprint burndown and team velocity to calibrate sustainable sprint commitments.", "Tracks historical team velocity and burndown curves in Jira to calibrate realistic sprint capacity, proactively flagging delays during daily standups to negotiate scope."]}, {"id": "KP3", "description": "Proactive Blocker Resolution & Delay Mitigation: Handles sprint slippages before deadlines fail.", "required": true, "acceptable_evidence": ["Technical keywords: proactive, blocker, resolution, delay.", "Identifies scope creep or technical roadblocks early in the sprint and raises them in standups.", "Negotiates scope descope with Product Owner mid-sprint to protect core deliverables rather than failing silently.", "Collaborates via pair programming or mobbing to swarm on critical blocked tickets."]}, {"id": "KP4", "description": "Continuous Improvement & Blameless Retrospectives: Drives systemic improvements to team processes.", "required": false, "acceptable_evidence": ["Technical keywords: technical debt, PR, API, unclear PR descriptions.", "Uses retrospectives to address root causes of communication gaps (e.g., unclear PR descriptions, missing API specs).", "Advocates for dedicated technical debt and spike tickets to de-risk complex upcoming features.", "Fosters transparent, psychological safety where team members openly share workflow friction."]}], "critical_failures": ["Remains silent when behind schedule, waiting until sprint review to reveal incomplete work.", "Dismisses Agile ceremonies as useless overhead without offering constructive communication mechanisms."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What is your level of experience with time-series forecasting, and how would you approach learning or applying it in a production setting?', '{"key_points": [{"id": "KP1", "description": "Time-Series Properties & Stationarity Analysis: Validates temporal assumptions and feature transformations.", "required": true, "acceptable_evidence": ["Technical keywords: ADF, daily, weekly, annual.", "Identifies core components: trend, seasonality (daily, weekly, annual), cyclicity, and residual noise.", "Tests and achieves stationarity using Augmented Dickey-Fuller (ADF) tests and differencing/log transformations."]}, {"id": "KP2", "description": "Engineers lag features, rolling window statistics, exponential moving averages, and cyclical date/time encodings.", "required": true, "acceptable_evidence": ["Technical keywords: lag features, rolling window statistics, exponential smoothing, Fourier terms, cyclical encodings, Prophet.", "Engineers lag features, rolling window statistics, exponential moving averages, and cyclical date/time encodings.", "Constructs autoregressive lag features (t-1, t-7, t-30), rolling standard deviations, and sinusoidal date encodings (sin/cos of hour and month) to capture seasonality."]}, {"id": "KP3", "description": "Modeling Paradigms & Algorithm Selection: Chooses statistical, tree-based, or deep learning models.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, ARIMA, TFT.", "Statistical models: ARIMA, SARIMAX, Exponential Smoothing, Prophet for interpretable baselines with seasonality.", "Machine Learning & Deep Learning: LightGBM/XGBoost with lag features, Temporal Fusion Transformers (TFT), N-BEATS, or LSTMs.", "Evaluates forecasts using temporal metrics: MAE, RMSE, MAPE, and symmetric MAPE (sMAPE)."]}, {"id": "KP4", "description": "Production Validation & Temporal Leakage Prevention: Enforces walk-forward validation in production.", "required": false, "acceptable_evidence": ["Technical keywords: cross-validation, walk-forward validation, data leakage, TimeSeriesSplit.", "Enforces strict time-based rolling window / expanding window cross-validation (TimeSeriesSplit) to prevent future data leakage.", "Handles real-world inference challenges: updating lag features during multi-step ahead recursive forecasting.", "Monitors forecast error drift in production and schedules automated retraining pipelines."]}], "critical_failures": ["Applies standard random k-fold cross-validation to time-series data, introducing massive future data leakage.", "Cannot explain stationarity or fails to differentiate trend from seasonality in temporal modeling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What is your perspective on AI''s role in the workforce, and how can systems be designed to augment rather than replace human capabilities?', '{"key_points": [{"id": "KP1", "description": "Copilot & Cognitive Augmentation Architecture: Designs assistive workflows that reduce human toil.", "required": true, "acceptable_evidence": ["Technical keywords: AI, augmentation architecture, copilot, cognitive.", "Architects AI as an assistive copilot (e.g. drafting responses, summarizing case history, retrieving relevant policy clauses).", "Reduces cognitive friction by pre-populating fields and highlighting critical anomalies for human operator verification."]}, {"id": "KP2", "description": "Empowers operators with speed while keeping complex moral, legal, or high-stakes decisions under human discretion.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, copilot architecture, human discretion, high-stakes decision boundaries, confidence gating.", "Empowers operators with speed while keeping complex moral, legal, or high-stakes decisions under human discretion.", "Designs copilot interfaces where the model drafts recommendations with transparent citations, reserving final approval and execution for human operators on high-stakes workflows."]}, {"id": "KP3", "description": "Confidence Scoring & Human-in-the-Loop Routing: Automatically routes uncertain cases to human experts.", "required": true, "acceptable_evidence": ["Technical keywords: loop routing, accept, edit, human-in-the-loop.", "Calibrates model confidence thresholds: high-confidence routine tasks automate; ambiguous cases route to human review.", "Implements human-in-the-loop review interfaces (accept, edit, reject buttons with structured feedback logs).", "Integrates graceful fallback mechanisms when the model encounters novel out-of-distribution inputs."]}, {"id": "KP4", "description": "Active Learning & Continuous Feedback Flywheel: Uses human corrections to improve system performance.", "required": false, "acceptable_evidence": ["Technical keywords: active, learning, continuous, feedback.", "Captures human edits and rejections into structured telemetry streams for evaluation and retraining datasets.", "Maintains complete audit trails recording both model recommendations and human final decisions for accountability.", "Monitors user trust, adoption velocity, and workflow turnaround time post-deployment."]}], "critical_failures": ["Advocates fully autonomous black-box AI execution in high-risk domains without any human oversight or confidence routing.", "Fails to capture human feedback or corrections to iteratively improve system accuracy."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What kind of operational and DevOps responsibilities did you handle in your projects?', '{"key_points": [{"id": "KP1", "description": "Containerization & Cloud Orchestration: Packages and deploys resilient microservices.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes, HPA, AWS, ECS.", "Authors multi-stage Dockerfiles optimizing image size, security scanning (Trivy), and non-root execution.", "Manages container deployments on AWS ECS Fargate or Kubernetes (EKS) with horizontal pod autoscaling (HPA).", "Configures Application Load Balancers, health check endpoints, and zero-downtime rolling deployments."]}, {"id": "KP2", "description": "CI/CD Automation & GitOps: Automates build, test, and release lifecycles.", "required": true, "acceptable_evidence": ["Technical keywords: Terraform, Infrastructure as Code, CI/CD, GitHub Actions.", "Configures CI/CD pipelines (GitHub Actions, GitLab CI) running automated unit tests, linters, and integration suites on PRs.", "Implements automated staging and production release gates with semantic version tagging.", "Deploys infrastructure via Infrastructure as Code (Terraform) integrated into CI workflows."]}, {"id": "KP3", "description": "Observability, Secret Management & On-Call Operations: Maintains production system reliability.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, Datadog, CloudWatch.", "Sets up centralized logging (CloudWatch, ELK) and application performance monitoring (Datadog, Prometheus/Grafana).", "Manages credentials securely via AWS Secrets Manager / HashiCorp Vault rather than raw environment files.", "Participates in on-call rotations, responding to PagerDuty alerts and conducting blameless post-mortems."]}], "critical_failures": ["Has never used containers, CI/CD pipelines, or cloud services, deploying code via manual SSH and FTP.", "Hardcodes plaintext credentials in source repositories without secrets management."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What motivates your transition between roles, and how do you evaluate new opportunities in applied AI?', '{"key_points": [{"id": "KP1", "description": "Clear Career Drivers & Progression: Articulates purposeful reasons for changing roles.", "required": true, "acceptable_evidence": ["Technical keywords: AI, clear, career, drivers.", "Articulates positive career aspirations: seeking deeper technical challenges, production scale, or cutting-edge AI architectures.", "Avoids venting or speaking negatively about former employers, framing moves constructively."]}, {"id": "KP2", "description": "Shows a coherent progression of expanding responsibility and technical complexity across roles.", "required": true, "acceptable_evidence": ["Technical keywords: career progression, technical ownership, system scope, platform engineering, applied AI impact.", "Shows a coherent progression of expanding responsibility and technical complexity across roles.", "Articulates a clear technical trajectory progressing from building isolated models to architecting end-to-end distributed AI platforms and production agent systems."]}, {"id": "KP3", "description": "Applied AI Opportunity Evaluation Criteria: Rigorously assesses prospective technical environments.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, AI.", "Evaluates whether prospective roles solve real user pain points versus building superficial AI demos.", "Assesses team engineering maturity: CI/CD, evaluation frameworks, data quality, and testing standards.", "Prioritizes environments where AI systems deploy into production and interface with real users."]}, {"id": "KP4", "description": "Team Culture & Strategic Alignment: Considers leadership quality and personal career trajectory.", "required": false, "acceptable_evidence": ["Technical keywords: strategic alignment, culture, strategic, personal.", "Evaluates leadership competence, collaborative peer culture, and mentorship opportunities.", "Aligns personal growth goals with the company''s business trajectory and mission.", "Demonstrates clear excitement and preparation for the prospective team''s specific problem space."]}], "critical_failures": ["Speaks with bitterness or unprofessionalism about previous employers as the sole motivator for leaving.", "Shows no criteria for evaluating prospective roles beyond compensation and title."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What motivates your transition from an engineering manager role to an individual contributor role, and how do you evaluate that decision?', '{"key_points": [{"id": "KP1", "description": "Passion for Technical Craftsmanship & Deep Work: Articulates desire for hands-on engineering.", "required": true, "acceptable_evidence": ["Technical keywords: designing architecture, passion, craftsmanship, articulates.", "Expresses authentic passion for designing architecture, writing code, and debugging complex technical systems.", "Articulates missing the immediate creative flow and problem-solving fulfillment of hands-on software construction."]}, {"id": "KP2", "description": "Recognizes the fast-moving AI landscape and prioritizes staying technically sharp at the implementation layer.", "required": true, "acceptable_evidence": ["Technical keywords: hands-on engineering, IC career ladder, Staff engineer, architecture design, production implementation, deep technical focus.", "Recognizes the fast-moving AI landscape and prioritizes staying technically sharp at the implementation layer.", "Emphasizes the desire to return to hands-on systems architecture, low-latency implementation, and frontier AI research application without administrative management overhead."]}, {"id": "KP3", "description": "Leveraging Management Experience as a Senior IC: Uses management skills to multiply engineering impact.", "required": true, "acceptable_evidence": ["Technical keywords: IC, leveraging, management, experience.", "Brings strong cross-functional empathy and partnership skills when working with Product, Design, and leadership.", "Mentors junior engineers, conducts thoughtful code reviews, and drives architectural consensus without formal authority.", "Understands business priorities, project timelines, and organizational bottlenecks from a manager''s viewpoint."]}, {"id": "KP4", "description": "Comfort with IC Evaluation & Ego Management: Embraces IC scope without authority conflicts.", "required": false, "acceptable_evidence": ["Technical keywords: EM, comfort, management, IC.", "Demonstrates clear comfort being evaluated on technical deliverables and code output rather than team headcount.", "Shows total willingness to support team leadership without stepping on current engineering manager''s toes.", "Views the EM-to-IC transition as an intentional career choice for sustained technical leadership."]}], "critical_failures": ["Frames the move back to IC as a retreat from managerial failure without any enthusiasm for coding.", "Unable to relinquish management authority, displaying risk of undermining the existing engineering manager."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What role do guardrails play in your system, and how do they ensure security, correctness, and appropriate outputs?', '{"key_points": [{"id": "KP1", "description": "Input Guardrails & Threat Defense: Sanitizes prompts and defends against malicious inputs.", "required": true, "acceptable_evidence": ["Technical keywords: system prompt, prompt injection, jailbreak, input guardrails.", "Detects and blocks prompt injection, jailbreak attempts, and system prompt override payloads.", "Enforces PII redaction (Microsoft Presidio) before prompts reach the LLM or vector database."]}, {"id": "KP2", "description": "Validates input schema and enforces length/character bounds to prevent denial-of-service token bloat.", "required": true, "acceptable_evidence": ["Technical keywords: NeMo Guardrails, Llama Guard, regex bounds, token limit enforcement, denial-of-service prevention, input validation.", "Validates input schema and enforces length/character bounds to prevent denial-of-service token bloat.", "Enforces strict input character limits, Pydantic schema validation, and NeMo/Llama Guard screening to prevent prompt injection and denial-of-service token bloat."]}, {"id": "KP3", "description": "Execution & Action Guardrails: Gates tool executions and policy compliance.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, human-in-the-loop, HITL, action guardrails.", "Validates agent tool parameters against strict Pydantic schemas before invocation.", "Enforces business policy checks (e.g. refund limits, authorization checks) prior to committing tool actions.", "Implements Human-in-the-Loop (HITL) checkpoints for irreversible or high-risk actions."]}, {"id": "KP4", "description": "Output Guardrails & Quality Validation: Validates generated answers before returning to users.", "required": false, "acceptable_evidence": ["Technical keywords: output guardrails, NeMo, factual consistency, nemo guardrails.", "Checks generated output for hallucinations, verifying factual consistency against retrieved context chunks.", "Filters toxic, biased, or inappropriate content using safety classifiers (Llama Guard, NeMo Guardrails).", "Returns safe fallback responses when guardrail violations are detected and logs incidents for security review."]}], "critical_failures": ["Believes system prompt instructions alone provide foolproof guardrails against prompt injection and data leaks.", "Fails to implement any validation on tool execution or output generation before returning responses to users."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What steps would you take to understand and evaluate existing ETL processes and data workflows in a new environment?', '{"key_points": [{"id": "KP1", "description": "Pipeline Discovery & Lineage Mapping: Maps data sources, transformation DAGs, and dependencies.", "required": true, "acceptable_evidence": ["Technical keywords: DBT, S3, DAG, AWS.", "Audits data sources (databases, message queues, external APIs, S3 buckets) and ingestion schedules.", "Maps DAG workflows and dependencies across orchestration engines (Airflow, Prefect, dbt, AWS Step Functions).", "Constructs end-to-end data lineage diagrams from raw bronze landing zones to gold consumption tables."]}, {"id": "KP2", "description": "Data Quality, Schema & SLA Assessment: Audits data integrity and performance benchmarks.", "required": true, "acceptable_evidence": ["Technical keywords: DLQ, SLA, audits schema, data validation.", "Evaluates data freshness, throughput, execution runtimes, and Service Level Agreements (SLAs).", "Audits schema consistency, primary key uniqueness, null ratios, and data validation rules (Great Expectations, dbt tests).", "Inspects error handling, Dead Letter Queue (DLQ) volume, and failure recovery mechanisms."]}, {"id": "KP3", "description": "Infrastructure, Security & Optimization Roadmap: Identifies bottlenecks, costs, and compliance risks.", "required": false, "acceptable_evidence": ["Technical keywords: HIPAA, IAM, PII, IAM roles.", "Assesses cloud infrastructure costs, compute utilization, and inefficient full-table scans.", "Audits access control (IAM roles, service account keys) and compliance with PII/HIPAA data protection rules.", "Synthesizes findings into a prioritized refactoring roadmap balancing quick wins against architectural overhauls."]}], "critical_failures": ["Proposes immediately rewriting entire ETL systems without auditing data lineage, dependencies, or business rules.", "Ignores data quality validation, SLAs, and security compliance when evaluating data workflows."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What strategies did you use to ensure data privacy and implement guardrails when working with internal enterprise documents?', '{"key_points": [{"id": "KP1", "description": "Document Ingestion Sanitization & PII Redaction: Scrubs sensitive data prior to indexing.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, PII, PHI, NER.", "Runs automated PII/PHI detection (Presidio, regex recognizers, NER models) across enterprise documents before indexing.", "Replaces sensitive identifiers (SSN, credit card, patient ID, financial data) with synthetic tokens or redaction markers."]}, {"id": "KP2", "description": "Prevents raw unredacted documents from being embedded into vector stores or sent to external LLMs.", "required": true, "acceptable_evidence": ["Technical keywords: document ACLs, RBAC filtering, pre-embedding redaction, PII sanitization, Milvus partition isolation.", "Prevents raw unredacted documents from being embedded into vector stores or sent to external LLMs.", "Sanitizes confidential internal documents before embedding and enforces user permission ACLs via Milvus metadata filtering to prevent unauthorized cross-department data leakage."]}, {"id": "KP3", "description": "Granular Access Control & Multi-Tenant Isolation: Enforces document ACLs and partition boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, tenant isolation, vector search, ACLs.", "Embeds document-level Access Control Lists (ACLs) and user tenant IDs into vector metadata.", "Enforces pre-filtering during vector search so users can only retrieve chunks from documents they have explicit permissions to view.", "Isolates tenant data physically or logically (separate Milvus collections or strict partition keys)."]}, {"id": "KP4", "description": "Infrastructure Security & LLM Governance: Secures transit, storage, and external API contracts.", "required": false, "acceptable_evidence": ["Technical keywords: Zero Data Retention, ZDR, REST, LLM.", "Encrypts documents and vector indexes with customer-managed KMS keys at rest and TLS in transit.", "Enforces Zero Data Retention (ZDR) enterprise agreements with LLM providers or deploys self-hosted models in private VPCs.", "Maintains immutable audit logs of all document queries and LLM prompt/response pairs for compliance reviews."]}], "critical_failures": ["Indexes unredacted enterprise documents into a shared vector store accessible to unauthorized users.", "Relies on prompt instructions (''do not mention confidential data'') instead of deterministic access control and redaction."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What tools and frameworks did you use for building and evaluating your system, and why did you choose them?', '{"key_points": [{"id": "KP1", "description": "Orchestration & Serving Framework Justification: Justifies framework choices for state and API layers.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, human-in-the-loop, FastAPI.", "Chooses LangGraph for orchestration: provides stateful graph execution, cyclic loops, human-in-the-loop checkpoints, and explicit multi-agent coordination.", "Chooses FastAPI for serving: native async support, high throughput, automatic OpenAPI documentation, and Pydantic validation."]}, {"id": "KP2", "description": "Explain trade-offs against alternatives (e.g. raw LangChain chains, autogen, CrewAI).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, LCEL, CrewAI, AutoGen, cyclic graph, state machine, checkpointing, framework trade-offs.", "Explains trade-offs against alternatives (e.g. raw LangChain chains, autogen, CrewAI).", "Contrasts LangGraph''s deterministic cyclic state machine and time-travel checkpointing against CrewAI or basic LCEL chains for complex multi-step enterprise workflows."]}, {"id": "KP3", "description": "Retrieval & Vector Storage Selection: Justifies vector database and embedding stack.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, Milvus, precision, recall.", "Chooses Milvus for vector database: distributed HNSW indexing, high recall at enterprise scale, robust boolean metadata filtering, and VPC self-hosting.", "Selects BAAI/bge-large-en or text-embedding-3 for embeddings and BGE Cross-Encoder for precision reranking.", "Employs Docling or PyMuPDF for structural document parsing over naive text loaders."]}, {"id": "KP4", "description": "Evaluation & Observability Frameworks: Justifies tooling for measuring and monitoring quality.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, DeepEval, AWS, CloudWatch.", "Chooses DeepEval / Ragas for automated offline evaluation (G-Eval, Faithfulness, Answer Relevancy, Hallucination).", "Chooses Langfuse or AWS CloudWatch for real-time production tracing, token usage tracking, and latency profiling.", "Establishes a continuous CI/CD evaluation gate to prevent regression when prompts or models update."]}], "critical_failures": ["Lists tools randomly without providing any technical justification or comparison against alternatives.", "Omits evaluation frameworks entirely, showing no methodology for measuring system accuracy."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What trade-offs did you encounter when working in small teams versus larger teams, particularly in AI/ML projects?', '{"key_points": [{"id": "KP1", "description": "Small Team Dynamics & Trade-offs: Analyzes high velocity, broad scope, and resource constraints.", "required": true, "acceptable_evidence": ["Technical keywords: ML, devops, frontend.", "Small team benefits: minimal bureaucracy, rapid decision making, end-to-end technical ownership from ingestion to deployment.", "Small team challenges: individual engineers wear multiple hats (devops, ML, frontend), higher on-call burden, limited specialized tooling."]}, {"id": "KP2", "description": "Risk of technical debt accumulation due to pressure to ship fast without dedicated platform teams.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, shipping velocity, platform ownership, code review standards, refactoring cadence.", "Risk of technical debt accumulation due to pressure to ship fast without dedicated platform teams.", "Balances the rapid iteration of small teams with the risk of accumulating technical debt, establishing lightweight code review standards and scheduled tech-debt sprints."]}, {"id": "KP3", "description": "Large Team Dynamics & Trade-offs: Analyzes specialization, scale, and coordination overhead.", "required": true, "acceptable_evidence": ["Technical keywords: MLOps, platform, dynamics, trade.", "Large team benefits: dedicated specialized teams (MLOps, platform, evaluation, security), massive infrastructure resources, deep domain expertise.", "Large team challenges: communication overhead, slower consensus, cross-team dependency blocking, narrower individual scope.", "Need for formal architectural review boards and standardized interfaces to prevent divergence."]}, {"id": "KP4", "description": "Adaptability & Team Optimization: Adapts personal engineering style to team size.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, documentation.", "Demonstrates ability to thrive in both small scrappy squads and well-structured enterprise teams.", "Applies best practices from large teams (testing, CI/CD, documentation) to keep small teams resilient.", "Brings startup pragmatism to large teams to cut through bureaucratic paralysis."]}], "critical_failures": ["Demonstrates rigid dogmatism, claiming only one team size is valid while completely disparaging the other.", "Fails to identify the coordination and specialization trade-offs inherent in team scaling."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'What trade-offs have you encountered when working in large organizations versus startup environments, and how do you approach decision-making in each?', '{"key_points": [{"id": "KP1", "description": "Decision-Making in Startups (Speed & Reversibility): Employs type-1 vs type-2 decision frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: Speed & Reversibility, reversible, 70% certainty rule.", "Identifies two-way door (reversible) decisions and makes them with speed and imperfect information (70% certainty rule).", "Prioritizes fast customer feedback and shipping MVPs over exhaustive consensus."]}, {"id": "KP2", "description": "Tolerates calculated technical debt in non-critical components to validate business hypotheses.", "required": true, "acceptable_evidence": ["Technical keywords: calculated technical debt, MVP validation, release velocity, product-market fit, risk budget.", "Tolerates calculated technical debt in non-critical components to validate business hypotheses.", "Accepts modular technical debt in non-core prototype modules to validate product-market fit quickly, planning intentional refactoring milestones upon hypothesis validation."]}, {"id": "KP3", "description": "Decision-Making in Large Enterprises (Scale & Risk Governance): Navigates risk, compliance, and alignment.", "required": true, "acceptable_evidence": ["Technical keywords: risk governance, authors architecture, stakeholder alignment, irreversible.", "Applies rigorous risk management for one-way door (irreversible) decisions impacting millions of users or regulatory compliance.", "Authors Architecture Decision Records (ADRs) and Request for Comments (RFCs) to build cross-functional stakeholder alignment."]}, {"id": "KP4", "description": "Coordinates across security, legal, infrastructure, and compliance gatekeepers before major rollouts.", "required": false, "acceptable_evidence": ["Technical keywords: enterprise compliance, InfoSec review, CAB approval, SOC2, HIPAA, stakeholder coordination.", "Coordinates across security, legal, infrastructure, and compliance gatekeepers before major rollouts.", "Navigates enterprise governance by preparing security questionnaires, SOC2/HIPAA compliance documentation, and staging demos for change approval boards (CAB)."]}, {"id": "KP5", "description": "Contextual Judgment & Situational Leadership: Chooses the right decision mode for the problem.", "required": false, "acceptable_evidence": ["Technical keywords: contextual, situational, chooses, right.", "Avoids applying heavy corporate processes to early-stage experimental projects.", "Avoids applying sloppy startup shortcuts to mission-critical security and core financial data systems.", "Articulates personal comfort operating under both high-velocity ambiguity and high-governance scale."]}], "critical_failures": ["Applies identical decision-making rules regardless of whether working in a seed startup or a Fortune 50 enterprise.", "Fails to understand reversible vs irreversible decision-making frameworks."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What trade-offs would you consider when balancing speed of development versus system robustness in an early-stage startup?', '{"key_points": [{"id": "KP1", "description": "Pragmatic Architecture & Modular Seams: Builds simple architectures with clean abstraction seams.", "required": true, "acceptable_evidence": ["Technical keywords: pragmatic architecture, interfaces, repositories.", "Chooses simple monolithic or lightweight modular architectures over premature microservice sprawl.", "Creates clean abstraction boundaries (interfaces, repositories) so rapid implementations can be swapped out later."]}, {"id": "KP2", "description": "Leverages managed services (AWS Bedrock, Supabase, Auth0) to avoid spending engineering time reinventing commoditized wheels.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, Supabase, Auth0, managed services, build vs buy, time-to-market, architectural decoupling.", "Leverages managed services (AWS Bedrock, Supabase, Auth0) to avoid spending engineering time reinventing commoditized wheels.", "Adopts managed backend primitives (AWS Bedrock, Supabase, Auth0) to achieve fast time-to-market while maintaining clean interface abstractions for future migration."]}, {"id": "KP3", "description": "Non-Negotiable Robustness Safeguards: Preserves critical foundational safeguards even under time pressure.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, data isolation.", "Maintains non-negotiable baselines: automated unit/integration tests for critical business paths, basic CI/CD, database backups.", "Enforces security and data integrity: no plaintext credentials, parameterized queries, tenant data isolation.", "Implements centralized logging and basic alerting so production failures are discovered immediately."]}, {"id": "KP4", "description": "Deliberate Technical Debt Management: Codifies and remediates debt systematically.", "required": false, "acceptable_evidence": ["Technical keywords: technical debt, market validation, 20%.", "Treats technical debt as a conscious financial loan: take it to hit critical market milestones, but document and budget time to pay it down.", "Maintains a debt backlog and dedicates a percentage of sprint bandwidth (e.g., 20%) to refactoring validated features.", "Refactors only code that survives market validation, avoiding polishing features that may get discarded."]}], "critical_failures": ["Over-engineers an overly complex distributed microservices architecture for an unvalidated startup product.", "Cuts vital security and data integrity corners, resulting in catastrophic data loss or compliance violations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What was the nature of the complex inquiries and manual workflows that the AI solution was designed to automate at your prior company?', '{"key_points": [{"id": "KP1", "description": "Domain Inquiry Complexity & Bottlenecks: Details legacy manual workflows and pain points.", "required": true, "acceptable_evidence": ["Technical keywords: prior authorization, keyword search, domain, inquiry.", "Identifies specific manual workflows (e.g., call center agent handling Medicaid eligibility and prior authorization lookups; recruiter screening 500+ resumes against complex JDs).", "Highlights inquiry complexity: fragmented document sources, conflicting policy versions, lengthy manual handle times (e.g., 30-45 minutes per inquiry).", "Explains how legacy keyword search and manual portal navigation caused human fatigue and error rates."]}, {"id": "KP2", "description": "AI Solution Architecture & Automation Flow: Explains how the AI system parsed and resolved inquiries.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, BM25, Milvus, AI.", "Employs multi-agent routing (Triage Agent -> Knowledge/Troubleshooting Agent -> Policy/Escalation Agent) to classify customer intent.", "Retrieves grounded policy documentation and customer context via hybrid RAG (Milvus + BM25).", "Executes transactional workflows via tool integrations (e.g., checking claim status, generating candidate scorecards) automatically."]}, {"id": "KP3", "description": "Operational Outcomes & Human-in-the-Loop Safeguards: Validates business impact and safety.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, outcomes, human, safeguards.", "Maintains human-in-the-loop escalation triggers when inquiry confidence falls below threshold or involves financial/health denials.", "Achieves measurable reduction in resolution time (e.g., handle time cut by 65%, first-contact resolution increased to 88%).", "Provides explainable responses with citations to give human operators confidence in automated conclusions."]}], "critical_failures": ["Speaks in abstract generalities without describing the actual nature or domain of the automated inquiries.", "Cannot explain how the automated solution handled edge cases or complex multi-step inquiries."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'When would you use messaging systems like Kafka versus RabbitMQ, and how would you justify your choice to a client?', '{"key_points": [{"id": "KP1", "description": "Architectural Paradigms: Differentiates distributed commit log from traditional message broker.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, RabbitMQ, AMQP, topic.", "Explains Kafka as an append-only distributed commit log with partition-based storage and sequential disk writes.", "Explains RabbitMQ as an AMQP message broker with exchanges (direct, topic, fanout), bindings, and in-memory queues."]}, {"id": "KP2", "description": "Contrasts consumer-pull model with offset tracking (Kafka) vs broker-push model with message acknowledgments (RabbitMQ).", "required": true, "acceptable_evidence": ["Technical keywords: Apache Kafka, RabbitMQ, consumer-managed offsets, AMQP protocol, message acknowledgment, event replay, partitioned log.", "Contrasts consumer-pull model with offset tracking (Kafka) vs broker-push model with message acknowledgments (RabbitMQ).", "Contrasts Kafka''s partitioned log with consumer-managed offsets against RabbitMQ''s AMQP queue model with broker-tracked message acknowledgments, highlighting replayability."]}, {"id": "KP3", "description": "Message Retention, Ordering & Scaling: Compares replayability, ordering, and horizontal scaling.", "required": true, "acceptable_evidence": ["Technical keywords: complex routing, days, months, Kafka.", "Kafka retains messages for configurable retention windows (days/months), enabling multiple consumer groups to replay historical streams.", "RabbitMQ deletes messages upon consumer acknowledgment, optimized for transient queue processing.", "Kafka guarantees strict ordering within a partition; RabbitMQ handles granular message priority and complex routing."]}, {"id": "KP4", "description": "Use Case Selection & Client Justification: Recommends the appropriate system based on workload requirements.", "required": false, "acceptable_evidence": ["Technical keywords: RPC, ZooKeeper, kafka cluster, erlang cluster.", "Recommends Kafka for high-throughput event streaming, real-time analytics, event sourcing, and large telemetry pipelines (millions of msgs/sec).", "Recommends RabbitMQ for complex routing, task queues (Celery/BullMQ), granular acking, and microservice RPC with low throughput overhead.", "Addresses operational complexity: Kafka cluster/ZooKeeper/KRaft overhead vs RabbitMQ Erlang cluster management."]}], "critical_failures": ["Claims Kafka and RabbitMQ have identical architectures or treat message retention the same way.", "Recommends Kafka for simple task queue routing or RabbitMQ for high-throughput distributed event replay."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Which programming languages, tools, and frameworks do you use regularly, and how do you choose them based on business requirements?', '{"key_points": [{"id": "KP1", "description": "Core Technology Stack Profile: Details proficiency across modern programming languages and frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, PyTorch, FastAPI, Docker.", "Articulates core languages: Python (AI/ML ecosystem, FastAPI, LangGraph), TypeScript/JavaScript (modern web/Node.js), SQL (relational engines).", "Details key frameworks: FastAPI/Django, PyTorch/Scikit-learn, LangGraph, Docker, Kubernetes, Terraform."]}, {"id": "KP2", "description": "Explain how proficiency across these tools enables full-stack and systems engineering delivery.", "required": true, "acceptable_evidence": ["Technical keywords: Python, FastAPI, TypeScript, React, Docker, Kubernetes, PostgreSQL, Redis, full-stack delivery.", "Explains how proficiency across these tools enables full-stack and systems engineering delivery.", "Combines Python (FastAPI/PyTorch) for backend AI pipelines with TypeScript/React for UI and Docker/Kubernetes for cloud deployment to deliver end-to-end full-stack systems."]}, {"id": "KP3", "description": "Business-Driven Selection Methodology: Evaluates technical choices against performance, cost, and developer velocity.", "required": true, "acceptable_evidence": ["Technical keywords: AI, ML, millisecond latency, extreme concurrency.", "Chooses Python when prioritizing rich AI/ML libraries, rapid prototyping, and ecosystem integration.", "Chooses compiled languages (Go/Rust/C++) when sub-millisecond latency, extreme concurrency, and low memory footprints are strict business constraints.", "Weighs developer ecosystem maturity, hiring availability, and community support against bleeding-edge technology risks."]}, {"id": "KP4", "description": "Pragmatism & Technology Lifecycle Management: Manages legacy stacks and avoids unnecessary rewrites.", "required": false, "acceptable_evidence": ["Technical keywords: Total Cost of Ownership, TCO, pragmatism, technology.", "Prioritizes solving user and business problems over resume-driven development and shiny object syndrome.", "Evaluates total cost of ownership (TCO), cloud hosting expenses, and maintenance burden before introducing new technologies.", "Encapsulates external libraries behind clean interfaces to minimize migration friction if tools become obsolete."]}], "critical_failures": ["Selects tools solely based on personal novelty without considering business requirements, cost, or ecosystem support.", "Cannot explain the trade-offs or performance characteristics of the programming languages they use."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Could you tell me a bit about the products that you have built using these technologies or just like your experience within the current company that you''re working with and how you''re implementing or building some of the products that you''re building there.', '{"key_points": [{"id": "KP1", "description": "System Architecture & Component Integration: Details the high-level design of deployed products.", "required": true, "acceptable_evidence": ["Technical keywords: REST, gRPC, WebSockets, API.", "Walks through the high-level architecture: frontend client, API Gateway, microservice backends, database layers, and AI components.", "Explains inter-service communication protocols (REST, WebSockets, gRPC, event-driven message queues).", "Details the data lifecycle: ingestion, transformation, storage, retrieval, and presentation to end users."]}, {"id": "KP2", "description": "AI & Technical Implementation Mechanics: Explains how core technical capabilities were built.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, Milvus, PostgreSQL.", "Details AI integration: RAG pipelines, agentic orchestration (LangGraph), vector embeddings (Milvus), and LLM prompting.", "Explains state management, session handling, and database schemas (PostgreSQL, Redis caching).", "Articulates specific personal engineering contributions in developing and refining the codebase."]}, {"id": "KP3", "description": "Production Deployment, Observability & Business Outcomes: Details production operations and results.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, Docker, CI/CD, AWS.", "Details deployment on cloud infrastructure (AWS ECS, Docker, EKS) with automated CI/CD pipelines.", "Monitors production telemetry (CloudWatch, Langfuse, Prometheus) for latency, errors, and system health.", "Cites concrete business and operational outcomes delivered by the product post-launch."]}], "critical_failures": ["Provides a superficial description of a product without understanding any of the underlying backend or architectural mechanics.", "Cannot explain how components interact or what their individual technical responsibility was in the project."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you design role-based access control and data segmentation in your system when introducing multiple user personas?', '{"key_points": [{"id": "KP1", "description": "Role Model & Permission Architecture: Defines clear permission boundaries across user personas.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, ABAC, permission architecture, Recruiters.", "Defines distinct user personas (e.g., Recruiters, Hiring Managers, Candidates, System Admins) with explicit permission matrices.", "Implements role-based access control (RBAC) or attribute-based access control (ABAC) in the authentication/authorization layer."]}, {"id": "KP2", "description": "Extracts authenticated roles and tenant claims securely from validated JWT tokens.", "required": true, "acceptable_evidence": ["Technical keywords: JWT claims, tenant_id, role extraction, cryptographic signature, RS256, OAuth2 Bearer.", "Extracts authenticated roles and tenant claims securely from validated JWT tokens.", "Decodes and validates cryptographically signed JWT tokens (RS256) on incoming requests, extracting user roles and tenant_id claims into request state for downstream authorization."]}, {"id": "KP3", "description": "Data Segmentation & Query Pre-Filtering: Enforces data isolation at database and vector search layers.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, PostgreSQL, allowed_roles, tenant_id.", "Attaches security metadata (allowed_roles, department, tenant_id) to all relational records and vector chunks.", "Enforces mandatory boolean pre-filtering in vector searches (e.g., Milvus expression `tenant_id == ''xyz'' && role in [''admin'', ''recruiter'']`).", "Implements Row-Level Security (RLS) in PostgreSQL to ensure queries cannot leak cross-persona records."]}, {"id": "KP4", "description": "Persona-Specific Response Shaping & Audit Logging: Tailors outputs safely and audits all accesses.", "required": false, "acceptable_evidence": ["Technical keywords: AI, ID, output schemas, session memory.", "Sanitizes generative AI prompts and output schemas to prevent indirect role data leaks (e.g., hiding candidate salary from hiring manager).", "Separates user session memory by user ID and role to avoid cross-session context contamination.", "Maintains immutable audit logs of all privileged access attempts and security filter evaluations."]}], "critical_failures": ["Relies on client-side UI hiding or prompt instructions alone to enforce role-based security without server/database enforcement.", "Fails to implement metadata pre-filtering on vector or relational database queries."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'What are the limitations of using mechanisms like setInterval for queue processing, and how would you design a more reliable worker system?', '{"key_points": [{"id": "KP1", "description": "Limitations of setInterval Queue Polling: Identifies failure modes of naive timer polling.", "required": true, "acceptable_evidence": ["Technical keywords: timer drift, queued state, setinterval, queue.", "Timer drift and overlapping executions: slow async jobs cause subsequent ticks to fire concurrently, leading to race conditions.", "Process crash data loss: in-memory timers lose all queued state when the Node/Python process restarts or crashes.", "Lack of distributed coordination: running multiple application instances causes duplicate polling, lock contention, or database thrashing."]}, {"id": "KP2", "description": "Event loop starvation: heavy timer callbacks block the single-threaded event loop from serving HTTP traffic.", "required": true, "acceptable_evidence": ["Technical keywords: Node.js event loop starvation, BullMQ, Celery, Redis queue, worker concurrency, P99 latency.", "Event loop starvation: heavy timer callbacks block the single-threaded event loop from serving HTTP traffic.", "Explains how long-running setInterval callbacks block Node.js event loop turns from processing I/O, replacing them with BullMQ worker pools using Redis-backed job acknowledgments."]}, {"id": "KP3", "description": "Distributed Worker Architecture: Designs reliable queue processing with persistence and acknowledgments.", "required": true, "acceptable_evidence": ["Technical keywords: RabbitMQ, Redis, AWS, SQS.", "Replaces timers with dedicated distributed message queues (Redis BullMQ, Celery with RabbitMQ, AWS SQS).", "Implements explicit delivery semantics: consumer pulls job, processes it, and sends ACK; unacknowledged jobs return to queue after visibility timeout.", "Enforces job idempotency using unique idempotency keys to ensure safe duplicate execution without side effects."]}, {"id": "KP4", "description": "Failure Handling, Retries & Scalability: Manages backoff, dead letter queues, and horizontal scaling.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, DLQ, lag metrics.", "Implements exponential backoff with jitter for transient job failures and routes poisoned messages to a Dead Letter Queue (DLQ).", "Scales worker processes horizontally based on queue depth / backlog lag metrics.", "Provides observability dashboards for queue latency, throughput, failure rates, and active worker counts."]}], "critical_failures": ["Believes setInterval is acceptable for production background queues and cannot identify any limitations.", "Designs a replacement worker system without message acknowledgments, idempotency, or crash recovery."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What is the use case that you have developed and tell me how you have designed and implemented that one?', '{"key_points": [{"id": "KP1", "description": "Business Problem & Solution Architecture: Structures system design around core operational requirements.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Milvus, FastAPI, solution architecture.", "Clearly defines the business problem (e.g. automating candidate technical screening or healthcare claims resolution).", "Presents the architectural blueprint: ingestion pipeline, vector index (Milvus), LangGraph agent orchestrator, and FastAPI gateway."]}, {"id": "KP2", "description": "Explain how technical design choices directly addressed domain-specific requirements.", "required": true, "acceptable_evidence": ["Technical keywords: architecture justification, SLA requirements, FastAPI async, Milvus vector store, Redis caching, trade-off matrix.", "Explains how technical design choices directly addressed domain-specific requirements.", "Demonstrates architectural alignment such as choosing FastAPI for async streaming, Milvus for high-dimension vector search, and Redis for sub-millisecond session state based on specific SLAs."]}, {"id": "KP3", "description": "Technical Implementation Mechanics: Details workflow orchestration, retrieval, and guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, StateGraph, human-in-the-loop, cross-encoder reranking.", "Explains orchestration: StateGraph with typed schemas, conditional routing, and specialized agents.", "Details retrieval: hybrid dense/sparse search, cross-encoder reranking, and dynamic context engineering.", "Implements safety controls: Presidio PII masking, confidence-based Human-in-the-Loop escalation, and structured Pydantic outputs."]}, {"id": "KP4", "description": "Production Deployment & Measurable Impact: Demonstrates real-world validation and operational outcomes.", "required": false, "acceptable_evidence": ["Technical keywords: MRR, CI/CD, AWS, ECS.", "Deploys containerized services on AWS ECS/EKS with automated CI/CD and CloudWatch/Langfuse telemetry.", "Validates quality using automated evaluation datasets (Hit Rate >90%, MRR, hallucination checks via DeepEval).", "Delivers concrete business outcomes (e.g., screening turnaround reduced by 70%, support handle time cut by 50%)."]}], "critical_failures": ["Describes an abstract tutorial or toy project without real architectural components, ingestion pipelines, or deployment.", "Cannot explain how their system was tested, evaluated, or monitored in production."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Are these clients already on the AWS ecosystem, or are they agnostic of one single platform?', '{"key_points": [{"id": "KP1", "description": "Client Cloud Footprint Assessment: Audits existing enterprise cloud constraints.", "required": true, "acceptable_evidence": ["Technical keywords: S3, VPC, IAM, AWS.", "Assesses whether clients have mandated cloud commitments, committed spend discounts, and strict VPC peering rules on AWS.", "Identifies client-native AWS dependencies: IAM identities, S3 data lakes, KMS encryption keys, and CloudWatch log groups.", "Recognizes enterprise clients requiring multi-cloud flexibility or private on-premise cloud deployments."]}, {"id": "KP2", "description": "Platform-Agnostic Core Architecture: Encapsulates cloud dependencies behind portable abstractions.", "required": true, "acceptable_evidence": ["Technical keywords: Qdrant, Milvus, Docker, Kubernetes.", "Packages application logic into standard Docker containers managed via Kubernetes/Helm or portable compose manifests.", "Abstracts cloud storage and database APIs behind standardized interfaces (e.g., S3-compatible APIs for MinIO/GCS/Azure Blob).", "Uses open-source vector databases (Milvus, Qdrant) and models that can deploy across AWS, GCP, or Azure."]}, {"id": "KP3", "description": "Strategic Trade-offs: Managed Services vs Portability: Analyzes TCO, speed, and lock-in.", "required": false, "acceptable_evidence": ["Technical keywords: Terraform, Infrastructure as Code, TCO, AWS.", "Balances the speed of using AWS managed services (Bedrock, SageMaker, DynamoDB) against vendor lock-in risks.", "Utilizes Infrastructure as Code (Terraform) with cloud-specific provider modules cleanly separated from core business logic.", "Presents clear architectural recommendations to clients based on their internal DevOps maturity and budget."]}], "critical_failures": ["Forces clients to migrate all cloud systems without assessing their existing infrastructure agreements and constraints.", "Binds application business logic directly to proprietary cloud-specific APIs without any abstraction layers."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Have you programmed in an Azure framework?', '{"key_points": [{"id": "KP1", "description": "Azure Core Infrastructure & SDK Programming: Demonstrates proficiency with Azure developer frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes, SDK, DefaultAzureCredential, AKS.", "Programs with Azure Python SDK (`azure-identity`, `azure-storage-blob`, `azure-cosmos`) using DefaultAzureCredential.", "Deploys containerized microservices on Azure App Services, Azure Container Apps, or Azure Kubernetes Service (AKS).", "Configures Azure Virtual Networks (VNet), Private Endpoints, and Network Security Groups (NSGs)."]}, {"id": "KP2", "description": "Azure AI Ecosystem Integration: Integrates Azure OpenAI and Cognitive Search.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, hybrid search, jailbreak, AI.", "Integrates Azure OpenAI Service (GPT-4o, embeddings) with enterprise data privacy and managed identity authentication.", "Implements Azure AI Search (formerly Cognitive Search) with hybrid search (vector + BM25) and semantic reranking.", "Utilizes Azure AI Content Safety guardrails for automated toxicity and jailbreak detection."]}, {"id": "KP3", "description": "Security, Governance & DevOps in Azure: Manages Entra ID, Key Vault, and pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, Terraform, GitHub Actions, DevOps.", "Manages secrets and certificates securely using Azure Key Vault with role-based access control.", "Enforces security policies via Microsoft Entra ID (Azure AD), Managed Identities, and Azure RBAC.", "Automates deployment using Bicep, ARM templates, or Terraform with Azure DevOps / GitHub Actions."]}], "critical_failures": ["Has never programmed in Azure or cannot name basic Azure services, confusing them with AWS/GCP equivalents.", "Hardcodes plaintext credentials in code rather than using Azure Managed Identities and Key Vault."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How are you exposing the endpoint in AWS for your model?', '{"key_points": [{"id": "KP1", "description": "Compute & Serving Infrastructure Selection: Chooses and configures compute hosting on AWS.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, FastAPI, AWS, SageMaker.", "Exposes endpoints via Amazon SageMaker Real-Time / Serverless Inference endpoints for dedicated ML model serving.", "Deploys containerized inference engines (FastAPI + vLLM/TorchServe) on AWS ECS Fargate or EKS with GPU node groups.", "Utilizes AWS Lambda with Function URLs or API Gateway for lightweight, bursty, serverless model inference."]}, {"id": "KP2", "description": "API Gateway, Load Balancing & Routing: Manages networking, traffic routing, and security.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, load balancer, IAM, API.", "Places endpoints behind Amazon API Gateway or Application Load Balancer (ALB) with SSL/TLS termination.", "Implements token-bucket rate limiting and throttling policies to prevent endpoint denial-of-service.", "Enforces authentication and authorization using AWS IAM SigV4, Amazon Cognito, or custom Lambda authorizers."]}, {"id": "KP3", "description": "Scaling, Cold Starts & Production Observability: Optimizes latency, cost, and health telemetry.", "required": false, "acceptable_evidence": ["Technical keywords: p95, p99, CloudWatch, ModelLatency.", "Configures Auto Scaling policies driven by CloudWatch metrics (ModelLatency, InvocationsPerInstance, target tracking).", "Mitigates cold start latency using Provisioned Concurrency (Lambda) or pre-warmed instances (SageMaker).", "Tracks endpoint telemetry: p95/p99 latency, HTTP 4xx/5xx error rates, GPU memory utilization, and token throughput."]}], "critical_failures": ["Exposes an unprotected EC2 instance port directly to the public internet without an API Gateway, ALB, or SSL.", "Fails to address autoscaling, concurrency limits, or authentication when exposing model endpoints."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How can we exemplify the data migration process from Teradata to AWS?', '{"key_points": [{"id": "KP1", "description": "Migration Strategy & Schema Conversion: Assesses legacy EDW and converts DDL/stored procedures.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, Amazon Redshift, EDW, DDL.", "Audits Teradata schemas, primary indexes (PI/UPI/NUPI), partitioning (PPI), views, and BTEQ/FastLoad scripts.", "Uses AWS Schema Conversion Tool (SCT) to translate Teradata DDL and stored procedures to Amazon Redshift or PostgreSQL.", "Plans migration phases: historical bulk historical data cutover followed by incremental Change Data Capture (CDC)."]}, {"id": "KP2", "description": "Data Extraction & Bulk Transfer Pipeline: Executes high-throughput data movement to AWS S3.", "required": true, "acceptable_evidence": ["Technical keywords: parquet, S3, AWS, ORC.", "Extracts bulk tables from Teradata into optimized compressed formats (Parquet/ORC) using FastExport or TPT (Teradata Parallel Transporter).", "Transfers large datasets securely to AWS S3 staging buckets via AWS Direct Connect, AWS Snowball, or AWS DataSync.", "Implements incremental CDC replication using AWS Database Migration Service (DMS) or Qlik Replicate."]}, {"id": "KP3", "description": "Validation, Dual-Running & Production Cutover: Ensures zero data loss and data consistency.", "required": false, "acceptable_evidence": ["Technical keywords: AWS, BI, AI, data consistency.", "Executes automated reconciliation scripts comparing row counts, checksums, and aggregate financial totals across Teradata and AWS.", "Runs dual-running / shadow pipelines where reports run concurrently on both systems to validate identical business outputs.", "Executes seamless cutover of downstream BI dashboards and AI pipelines, followed by decommissioning legacy hardware."]}], "critical_failures": ["Proposes doing single-threaded JDBC query extraction across billions of rows over the public internet.", "Fails to validate data consistency, row counts, or checksums between legacy Teradata and AWS target tables."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you secure sensitive documents in your current project in Amazon?', '{"key_points": [{"id": "KP1", "description": "S3 Encryption & Access Control: Secures document storage using KMS and least-privilege IAM.", "required": true, "acceptable_evidence": ["Technical keywords: S3, IAM, KMS, AWS.", "Enforces S3 Server-Side Encryption with AWS KMS customer managed keys (SSE-KMS) with automatic key rotation.", "Applies S3 Bucket Policies blocking public access (`BlockPublicAcls`, `IgnorePublicAcls`, `BlockPublicPolicy`, `RestrictPublicBuckets`).", "Restricts document access to authorized IAM roles using strict condition keys (e.g. `aws:PrincipalArn`, `aws:SourceVpce`)."]}, {"id": "KP2", "description": "Network Isolation & Secure Access Links: Restricts network transit and enforces time-limited access.", "required": true, "acceptable_evidence": ["Technical keywords: TLS 1.3, VPC, AWS, TLS.", "Restricts S3 traffic exclusively through AWS VPC Endpoints (Gateway/Interface Endpoints) preventing public internet exposure.", "Generates short-lived Pre-Signed URLs (with 5-15 minute expiration) for authorized client document downloads.", "Enforces TLS 1.3 in transit using bucket policy denying non-HTTPS requests (`aws:SecureTransport: false`)."]}, {"id": "KP3", "description": "Data Sanitization & Compliance Auditing: Pre-screens documents and audits access events.", "required": false, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, PII, PHI, AWS.", "Executes automated PII/PHI redaction (Microsoft Presidio or AWS Comprehend) prior to vector indexing.", "Enables S3 Object-Level Access Logging and AWS CloudTrail data events integrated with SIEM for audit trails.", "Applies S3 Object Lock and lifecycle retention rules for regulatory compliance."]}], "critical_failures": ["Allows public read access on S3 document buckets or stores sensitive enterprise files unencrypted.", "Distributes raw, long-lived AWS credentials to client applications to access document storage."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'BROAD', 150, 'How have you worked across different cloud platforms like AWS and GCP, and what factors influenced your choice of platform for different projects?', '{"key_points": [{"id": "KP1", "description": "Comparative Service Mapping: Maps core primitives across AWS and GCP ecosystems.", "required": true, "acceptable_evidence": ["Technical keywords: BigQuery, S3, AWS, GCP.", "Maps compute: AWS ECS/EKS/Lambda to GCP Cloud Run/GKE/Cloud Functions.", "Maps data: AWS S3/RDS/DynamoDB/Redshift to GCP Google Cloud Storage/Cloud SQL/Spanner/BigQuery."]}, {"id": "KP2", "description": "Maps networking: AWS VPC/DirectConnect/Security Groups to GCP VPC Network/Cloud Interconnect/Firewall Rules.", "required": true, "acceptable_evidence": ["Technical keywords: AWS VPC, GCP VPC Network, Security Groups, Cloud Firewall, DirectConnect, Cloud Interconnect, VPC peering.", "Maps networking: AWS VPC/DirectConnect/Security Groups to GCP VPC Network/Cloud Interconnect/Firewall Rules.", "Maps networking primitives across clouds, pairing AWS VPC Security Groups with GCP Firewall Rules and AWS DirectConnect with GCP Cloud Interconnect for hybrid networking."]}, {"id": "KP3", "description": "AI & Data Analytics Comparison: Evaluates Vertex AI vs Bedrock/SageMaker and data warehouse engines.", "required": true, "acceptable_evidence": ["Technical keywords: AI, SageMaker, GCP, ML.", "Contrasts AI capabilities: GCP Vertex AI (native Gemini integration, unified ML pipeline) vs AWS Bedrock/SageMaker (multi-model choice, fine-grained VPC controls).", "Evaluates data warehousing: GCP BigQuery''s serverless analytics speed vs AWS Redshift''s provisioned cluster management.", "Compares developer velocity: GCP Cloud Run simplicity vs AWS ECS/EKS infrastructure customization."]}, {"id": "KP4", "description": "Selection Factors & Enterprise Decision Making: Evaluates corporate constraints, pricing, and compliance.", "required": false, "acceptable_evidence": ["Technical keywords: HIPAA, EDP, vendor lock, EDP on AWS.", "Factors in enterprise commitments (EDP on AWS vs Google Cloud commitments) and egress networking costs.", "Evaluates compliance certifications (HIPAA, FedRAMP) and geographical region availability.", "Designs portable containerized workloads to mitigate vendor lock-in across multi-cloud environments."]}], "critical_failures": ["Claims AWS and GCP are identical without articulating any differences in their managed services or AI offerings.", "Cannot map corresponding core compute, storage, or AI services between AWS and GCP."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How many concurrent users was your application handling on AWS?', '{"key_points": [{"id": "KP1", "description": "Quantified Concurrency & Load Profile: States user volume and load characteristics.", "required": true, "acceptable_evidence": ["Technical keywords: WebSocket, quantified concurrency, response throughput, Locust.", "States specific concurrency metrics (e.g. 500 to 2,000 peak concurrent active sessions; 10,000+ daily active users).", "Characterizes traffic patterns: request-response throughput (requests per second), burst spikes, or streaming WebSocket connections.", "Explains how concurrency was load-tested using benchmarking tools (Locust, k6, Apache JMeter)."]}, {"id": "KP2", "description": "Compute & Database Scaling Configuration: Details autoscaling policies and resource pooling.", "required": true, "acceptable_evidence": ["Technical keywords: Redis, AWS, ECS, ALB.", "Configures AWS ECS Fargate autoscaling using target tracking policies based on CPU/Memory or ALB RequestCountPerTarget.", "Implements database connection pooling (AWS RDS Proxy, PgBouncer) to prevent database connection exhaustion under peak user loads.", "Offloads shared session state to ElastiCache Redis clusters to keep application containers stateless."]}, {"id": "KP3", "description": "Bottleneck Identification & Latency SLA Preservation: Maintains latency budgets under stress.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, SLA, p95, LLM.", "Identifies and resolves concurrency bottlenecks (e.g., vector index lock contention, external LLM rate limits, cold starts).", "Enforces rate limiting at API Gateway / ALB to protect downstream services from cascading overload.", "Maintains response time SLAs (e.g. p95 latency <500ms) during peak concurrent traffic surges."]}], "critical_failures": ["Cannot cite any concurrency numbers or load profile for their deployed AWS system.", "Maintains a single static container instance without load balancers, caching, or autoscaling under high concurrent traffic."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'I want to look at the status of each node, what tools were called, and the success of each state. How would I do that within the AWS ecosystem?', '{"key_points": [{"id": "KP1", "description": "Distributed Tracing & Step Instrumentation: Instruments agent state graph hops in AWS.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, AWS.", "Employs AWS X-Ray or OpenTelemetry distributed tracing to trace each node execution as a distinct subsegment.", "Emits structured trace spans recording node name, state transitions (inputs -> outputs), and execution duration."]}, {"id": "KP2", "description": "Correlates traces using a unified `execution_id` or `trace_id` propagated across all agent steps.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry SDK, AWS X-Ray, CloudWatch Logs, execution_id, trace_id, span propagation, W3C traceparent.", "Correlates traces using a unified `execution_id` or `trace_id` propagated across all agent steps.", "Instruments agent nodes with OpenTelemetry SDK to emit span events (node_name, tool_call, execution_status) to AWS CloudWatch and X-Ray with a shared execution_id."]}, {"id": "KP3", "description": "Tool Execution Logging & Custom Metrics: Captures tool calls, parameters, and success states.", "required": true, "acceptable_evidence": ["Technical keywords: tool_name, latency_ms, JSON, CloudWatch.", "Emits structured JSON logs to Amazon CloudWatch Logs with tool metadata: `tool_name`, `args`, `status: SUCCESS/FAILURE`, `latency_ms`.", "Publishes custom CloudWatch Embedded Metric Format (EMF) metrics tracking tool error rates and invocation counts.", "Sanitizes tool input/output logs to prevent sensitive PII or credentials from leaking into log streams."]}, {"id": "KP4", "description": "State Checkpointing & Visual Dashboards: Stores durable graph history and provides UI inspection.", "required": false, "acceptable_evidence": ["Technical keywords: LangGraph, checkpointing, UI, RDS.", "Persists node state snapshots to Amazon DynamoDB or Amazon RDS using LangGraph checkpointers for point-in-time replay.", "Builds Amazon CloudWatch Dashboards or integrates with Langfuse/OpenSearch Dashboards for visual DAG inspection.", "Configures CloudWatch Metric Alarms to trigger alerts on node execution failures or unexpected agent loops."]}], "critical_failures": ["Has no mechanism to observe agent node transitions, claiming that agent internal state cannot be monitored in AWS.", "Fails to record tool execution success/failure or tool arguments in logging and telemetry."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'In AWS there''s a guardrailing. Have you used that?', '{"key_points": [{"id": "KP1", "description": "Bedrock Guardrails Policy Capabilities: Details the policy dimensions configurable in Bedrock.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, PII, SSN, bedrock guardrails.", "Configures Denied Topics: natural language descriptions of off-limit subjects with custom user responses.", "Configures Content Filters: threshold-based filtering for hate speech, insults, sexual content, and violence across prompts and completions.", "Configures Sensitive Information Filters: automated PII redaction and regex recognizers (SSN, credit card, phone)."]}, {"id": "KP2", "description": "API Integration & Inference Interception: Integrates guardrails into the inference lifecycle.", "required": true, "acceptable_evidence": ["Technical keywords: API, InvokeModel, ApplyGuardrail, request payloads.", "Applies guardrail IDs and versions directly in Bedrock `InvokeModel` or `Converse` API request payloads.", "Uses the standalone `ApplyGuardrail` API to validate inputs and outputs independently of Bedrock foundation models.", "Inspects API response guardrail assessment metadata (`action: INTERVENED`, `blocked: true`, specific policy triggered)."]}, {"id": "KP3", "description": "Production Trade-offs & CloudWatch Telemetry: Evaluates latency, cost, and observability.", "required": false, "acceptable_evidence": ["Technical keywords: CloudWatch, LLM, NeMo, cloudwatch telemetry.", "Monitors Guardrails intervention logs and metrics in Amazon CloudWatch.", "Evaluates the latency overhead of guardrail evaluation on real-time streaming LLM responses.", "Compares Bedrock Guardrails with open-source alternatives (NeMo Guardrails, Presidio, Llama Guard)."]}], "critical_failures": ["Does not know what AWS Bedrock Guardrails is or confuses it with standard AWS WAF / security groups.", "Cannot explain any of the core policies (denied topics, PII filters, contextual grounding, content filters)."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'What are the limitations of using AWS Lambda for data processing tasks?', '{"key_points": [{"id": "KP1", "description": "Execution Time, Memory & Storage Bounds: Identifies hard infrastructure limits of Lambda.", "required": true, "acceptable_evidence": ["Technical keywords: ETL, EFS, tmp`.", "15-minute execution timeout: cannot perform long-running bulk ETL or training jobs without interruption.", "Memory and CPU constraints: maximum 10GB RAM and 6 vCPUs limits heavy in-memory data processing.", "Ephemeral disk limit: default 512MB (expandable up to 10GB `/tmp`), insufficient for massive dataset staging without EFS."]}, {"id": "KP2", "description": "Cold Starts, Networking & Concurrency Throttling: Analyzes operational bottlenecks.", "required": true, "acceptable_evidence": ["Technical keywords: Pandas, PyTorch, ML, NumPy.", "Cold start latency: container images with large ML/data libraries (NumPy, PyTorch, Pandas) suffer multi-second initialization delays.", "Account concurrency quotas: unreserved bursts can exhaust account-level concurrency (default 1,000), throttling other critical lambdas.", "Connection exhaustion: transient short-lived executions easily overwhelm downstream relational databases without RDS Proxy."]}, {"id": "KP3", "description": "Architectural Alternatives for Heavy Processing: Proposes suitable cloud alternatives.", "required": false, "acceptable_evidence": ["Technical keywords: AWS, EMR, ECS, Spark.", "Recommends AWS Glue (Spark) or EMR for large-scale distributed ETL and batch data transformations.", "Recommends AWS ECS Fargate or AWS Batch for containerized long-running batch processing (>15 mins).", "Recommends Step Functions for orchestrating distributed Map-state parallel Lambda workflows when serverless is mandatory."]}], "critical_failures": ["Claims AWS Lambda has infinite execution time or can handle arbitrary multi-hour big data processing jobs.", "Fails to identify the 15-minute timeout, cold starts, or database connection limits."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'BROAD', 150, 'What experience do you have with cloud platforms such as AWS or Azure?', '{"key_points": [{"id": "KP1", "description": "Core Infrastructure Comparison: Maps compute, storage, and networking across AWS and Azure.", "required": true, "acceptable_evidence": ["Technical keywords: S3, VPC, AWS, ECS.", "Compute: AWS EC2/ECS/Lambda vs Azure Virtual Machines / Container Apps / Azure Functions.", "Storage: AWS S3 / DynamoDB / RDS vs Azure Blob Storage / Cosmos DB / Azure SQL Database.", "Networking: AWS VPC / Security Groups vs Azure Virtual Network (VNet) / Network Security Groups (NSGs)."]}, {"id": "KP2", "description": "Identity, Security & AI Services: Compares identity management and AI ecosystems.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, IAM, AI, AWS.", "Identity: AWS IAM (Roles, Policies, STS) vs Microsoft Entra ID (Azure AD, Managed Identities, RBAC).", "AI Ecosystem: AWS Bedrock & SageMaker vs Azure OpenAI Service & Azure AI Search.", "Secret Management: AWS Secrets Manager / KMS vs Azure Key Vault."]}, {"id": "KP3", "description": "Practical Implementation & Multi-Cloud Experience: Details hands-on project execution.", "required": false, "acceptable_evidence": ["Technical keywords: Terraform, AWS, OpenTofu.", "Shares concrete project experience deploying production systems on both AWS and Azure.", "Manages deployment via Terraform / OpenTofu with cloud-specific provider configurations.", "Evaluates enterprise compliance, commercial discounting, and existing enterprise software integrations."]}], "critical_failures": ["Cannot compare corresponding AWS and Azure services or shows zero knowledge of one of the platforms.", "Conflates AWS IAM with Azure Entra ID or misunderstands managed identity mechanisms."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'What is your experience across cloud platforms like AWS, Azure, and GCP, and how have you used them in your projects?', '{"key_points": [{"id": "KP1", "description": "Tri-Cloud Architectural Mapping: Maps primitives across AWS, Azure, and GCP.", "required": true, "acceptable_evidence": ["Technical keywords: BigQuery, S3, AWS, GCP.", "Compute: AWS ECS/EKS vs Azure AKS/Container Apps vs GCP Cloud Run/GKE.", "Storage & Lakehouse: AWS S3/Redshift vs Azure Blob/Synapse vs GCP GCS/BigQuery."]}, {"id": "KP2", "description": "AI Platforms: AWS Bedrock/SageMaker vs Azure OpenAI/AI Search vs GCP Vertex AI/Gemini.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, Amazon SageMaker, Azure OpenAI, Azure AI Search, GCP Vertex AI, Gemini 1.5, Claude 3.5 Sonnet.", "AI Platforms: AWS Bedrock/SageMaker vs Azure OpenAI/AI Search vs GCP Vertex AI/Gemini.", "Compares managed AI platforms: AWS Bedrock for Anthropic Claude integration, Azure OpenAI for GPT enterprise instances, and GCP Vertex AI for Gemini multimodal pipelines."]}, {"id": "KP3", "description": "Distinct Ecosystem Strengths & Differentiators: Analyzes standout capabilities of each provider.", "required": true, "acceptable_evidence": ["Technical keywords: VPC, IAM, ID, GCP.", "AWS: dominant market share, granular IAM policies, broadest service ecosystem, strong enterprise VPC isolation.", "Azure: seamless Microsoft 365/Entra ID integration, direct enterprise OpenAI models, strong hybrid cloud with Azure Arc.", "GCP: superior developer ergonomics (Cloud Run), market-leading analytics with BigQuery, cutting-edge TPU hardware."]}, {"id": "KP4", "description": "Portability Strategy & Vendor Decoupling: Designs cloud-agnostic architectures.", "required": false, "acceptable_evidence": ["Technical keywords: OIDC, Docker, Kubernetes, Helm.", "Packages services in Docker containers orchestrated via Kubernetes (EKS/AKS/GKE) with Helm charts.", "Implements standard IaC (Terraform) across providers to ensure repeatable multi-cloud infrastructure definitions.", "Manages multi-cloud data synchronization, egress costs, and cross-cloud identity federation (OIDC)."]}], "critical_failures": ["Shows superficial familiarity with only one cloud while making baseless assumptions about the other two.", "Fails to identify the defining strengths of each major cloud provider (e.g. BigQuery for GCP, Entra/OpenAI for Azure, scale/breadth for AWS)."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What other AWS services did you use for the backend?', '{"key_points": [{"id": "KP1", "description": "API Gateway, Load Balancing & Networking: Details edge routing and traffic management.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, load balancer, API, ALB.", "Configures Amazon API Gateway for RESTful routing, rate limiting, and API key management.", "Deploys Application Load Balancer (ALB) for SSL termination and path-based routing to backend container targets.", "Configures AWS Route 53 for DNS routing and AWS WAF for web application security rules."]}, {"id": "KP2", "description": "Data, Caching & Asynchronous Messaging: Details backend persistence and message brokering.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, Redis, RDS, ElastiCache.", "Amazon RDS PostgreSQL (or Aurora) for relational transactional data and conversation state.", "Amazon ElastiCache Redis for fast in-memory session caching and rate limit counters.", "Amazon SQS and Amazon SNS for asynchronous decoupling, event distribution, and background worker queues."]}, {"id": "KP3", "description": "Security, Secrets & Observability Services: Implements governance and monitoring.", "required": false, "acceptable_evidence": ["Technical keywords: distributed tracing, S3, IAM, AWS.", "AWS Secrets Manager and Systems Manager (SSM) Parameter Store for dynamic credential rotation.", "Amazon CloudWatch (Logs, Alarms, Metrics) and AWS X-Ray for distributed tracing and performance telemetry.", "AWS IAM for least-privilege execution roles and Amazon S3 for durable blob/document storage."]}], "critical_failures": ["Only mentions raw EC2 without any supporting AWS backend services (databases, load balancers, messaging, secrets).", "Cannot explain how complementary AWS services interact to support backend APIs."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you integrated it with AWS and what metrics you tracked?', '{"key_points": [{"id": "KP1", "description": "AWS Integration Architecture: Connects application services into AWS infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: S3, VPC, IAM, AWS.", "Integrates application with AWS SDK (Boto3 in Python) using IAM role-based authentication (instance profiles/ECS task roles).", "Connects containerized microservices running on ECS/EKS to managed services (RDS, ElastiCache, S3) inside private VPC subnets."]}, {"id": "KP2", "description": "Configures EventBridge and SNS for automated event-driven triggers and webhook alerts.", "required": true, "acceptable_evidence": ["Technical keywords: AWS EventBridge, Amazon SNS, CloudWatch Alarms, AWS Lambda, custom metrics, P95 latency, queue depth.", "Configures EventBridge and SNS for automated event-driven triggers and webhook alerts.", "Configures EventBridge rules and SNS topics to trigger automated Lambda remediation workflows when CloudWatch alarm thresholds for P95 latency or error rates are breached."]}, {"id": "KP3", "description": "Core Operational & Performance Metrics Tracked: Monitors system health and SLA compliance.", "required": true, "acceptable_evidence": ["Technical keywords: SLA, p95, p99, ALB.", "Tracks latency distributions: p50, p90, p95, p99 request latency at ALB and API Gateway.", "Tracks error rates: HTTP 4xx client errors, 5xx server errors, and database connection pool timeouts.", "Tracks compute utilization: CPU utilization, Memory utilization, GPU memory usage, and ECS task restart counts."]}, {"id": "KP4", "description": "AI-Specific Telemetry & CloudWatch Alarms: Tracks model metrics and automated alerting.", "required": false, "acceptable_evidence": ["Technical keywords: AI, CloudWatch, EMF, LLM.", "Publishes custom CloudWatch EMF metrics: LLM token usage (prompt vs completion), inference latency, and tool error rates.", "Configures CloudWatch Alarms tied to PagerDuty/SNS to alert on SLA violations and error budget burn.", "Aggregates metrics onto centralized operational dashboards for real-time executive and engineering visibility."]}], "critical_failures": ["Cannot name any specific metrics tracked, or only tracks high-level uptime without latency, error, or utilization data.", "Integrates with AWS using hardcoded access keys instead of IAM task execution roles."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How would you adapt an AWS-based GenAI solution to a GCP-based environment?', '{"key_points": [{"id": "KP1", "description": "AI & Vector Search Service Translation: Maps model serving and retrieval layers.", "required": true, "acceptable_evidence": ["Technical keywords: pgvector, Milvus, AI, AWS.", "Replaces AWS Bedrock foundation models with GCP Vertex AI (Gemini 1.5 Pro/Flash, PaLM) or Vertex Model Garden.", "Maps vector search: AWS OpenSearch / self-hosted Milvus on ECS to Vertex AI Vector Search or Cloud SQL with pgvector.", "Adapts embedding pipelines to Vertex AI text-embedding models (Gecko) or Hugging Face models on Cloud Run."]}, {"id": "KP2", "description": "Compute, Storage & Ingestion Adaptation: Translates compute and lakehouse primitives.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes, S3, IAM, AWS.", "Replaces AWS ECS Fargate with GCP Cloud Run (for serverless containers) or Google Kubernetes Engine (GKE).", "Replaces Amazon S3 with Google Cloud Storage (GCS) buckets, configuring IAM and lifecycle rules.", "Replaces Amazon SQS/SNS with Google Cloud Pub/Sub for event-driven message distribution."]}, {"id": "KP3", "description": "Identity, Security & CI/CD Migration: Migrates IAM, secrets, and deployment pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: Terraform, CI/CD, IAM, CI.", "Maps AWS IAM roles to GCP Service Accounts with Workload Identity Federation for keyless authentication.", "Replaces AWS Secrets Manager with GCP Secret Manager and KMS with Cloud KMS.", "Adapts Terraform provider scripts from `aws` to `google` provider modules to provision GCP infrastructure."]}], "critical_failures": ["Proposes rewriting entire application business logic rather than migrating cloud infrastructure primitives.", "Cannot identify equivalent GCP services for core AWS GenAI components (e.g. unaware of Vertex AI, Cloud Run, GCS)."]}', 1),
('SYSTEM_DESIGN', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'BROAD', 210, 'How would you design a real-time GenAI-powered L1 and L2 incident response system on AWS, including detection, triaging, and resolution?', '{"key_points": [{"id": "KP1", "description": "Event Detection & Ingestion Architecture: Ingests telemetry and triggers incident workflows.", "required": true, "acceptable_evidence": ["Technical keywords: Datadog, CloudWatch, AWS, EventBridge.", "Captures alerts from Amazon CloudWatch Alarms, Datadog webhooks, and AWS EventBridge into an Amazon SQS FIFO queue.", "Normalizes disparate alert payloads (metric anomalies, error log spikes, container crash loops) into a canonical incident schema."]}, {"id": "KP2", "description": "Filters out alarm noise and deduplicates alerts using Redis sliding window hashing.", "required": true, "acceptable_evidence": ["Technical keywords: Redis sliding window, SHA-256 alert fingerprint, alarm deduplication, event throttling, incident storm mitigation.", "Filters out alarm noise and deduplicates alerts using Redis sliding window hashing.", "Computes SHA-256 fingerprints of incoming alert payloads and uses Redis sliding window counters to suppress duplicate notifications within a 5-minute incident storm."]}, {"id": "KP3", "description": "AI Agent Triaging & Runbook Retrieval (L1): Orchestrates root-cause investigation.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, BM25, Milvus.", "Deploys a LangGraph Triage Agent on AWS ECS Fargate executing a Think-Validate-Act-Reflect cycle.", "Retrieves incident runbooks and historical post-mortems via hybrid RAG (Milvus on AWS + BM25) from Amazon S3."]}, {"id": "KP4", "description": "Queries CloudWatch Logs Insights and AWS X-Ray traces dynamically via MCP tool calls to isolate root causes.", "required": false, "acceptable_evidence": ["Technical keywords: CloudWatch Logs Insights, AWS X-Ray, MCP tool protocol, structured log filtering, root-cause analysis.", "Queries CloudWatch Logs Insights and AWS X-Ray traces dynamically via MCP tool calls to isolate root causes.", "Executes structured CloudWatch Logs Insights queries (@timestamp, @message | filter @message like /Exception/) via automated MCP tool calls to isolate root-cause stack traces."]}, {"id": "KP5", "description": "Automated Remediation & Human-in-the-Loop Escalation (L2): Executes safe remediation and escalation.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, SSM, PagerDuty, policy guardrails.", "Executes low-risk L1 auto-remediation (restarting tasks, clearing caches, rolling back canary) via AWS Systems Manager (SSM) Automation.", "Enforces strict policy guardrails and gates irreversible actions behind Human-in-the-Loop approval via Slack/PagerDuty buttons.", "Generates concise incident summaries, timeline reconstructions, and drafts post-mortem reports for engineering review."]}], "critical_failures": ["Allows an unconstrained LLM to execute arbitrary destructive shell commands or infrastructure deletions without human review or policy gates.", "Designs a static alerting pipeline without automated runbook retrieval, telemetry querying, or root-cause analysis."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs did you consider when choosing open-source tools versus managed cloud services in your system?', '{"key_points": [{"id": "KP1", "description": "Control, Customization & Data Privacy: Analyzes advantages of open-source architectures.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, Milvus, speculative decoding, vLLM.", "Deep technical control: ability to fine-tune vector index configurations (Milvus HNSW M/efConstruction) or model inference runtimes (vLLM speculative decoding).", "Strict data sovereignty: keeping sensitive enterprise data within private VPC clusters without egressing to third-party SaaS APIs."]}, {"id": "KP2", "description": "Avoiding vendor lock-in: maintaining architectural portability across clouds and on-premise environments.", "required": true, "acceptable_evidence": ["Technical keywords: vendor lock-in, architectural portability, Kubernetes, Helm, managed services, total cost of ownership, operational overhead.", "Avoiding vendor lock-in: maintaining architectural portability across clouds and on-premise environments.", "Avoids vendor lock-in by packaging services in standard OCI containers and Helm charts that run interchangeably on self-hosted Kubernetes or managed EKS/GKE."]}, {"id": "KP3", "description": "Operational Overhead & Total Cost of Ownership: Evaluates engineering maintenance burden.", "required": true, "acceptable_evidence": ["Technical keywords: Total Cost of Ownership, TCO, DevOps, AWS.", "Maintenance tax: self-hosted systems require dedicated DevOps for cluster patching, upgrades, high-availability, backups, and 24/7 on-call.", "Managed service velocity: AWS Bedrock/RDS provides instant SLAs, automated scaling, zero-effort failover, and reduced time-to-market.", "TCO analysis: compares compute/GPU hosting and engineering salaries against API token usage and managed SaaS subscription pricing."]}, {"id": "KP4", "description": "Strategic Hybrid Decision Framework: Formulates balanced enterprise adoption criteria.", "required": false, "acceptable_evidence": ["Technical keywords: RDS, IP, MVP, OSS.", "Adopts pragmatic hybrid approach: use managed cloud services for commoditized layers (RDS, Bedrock) while self-hosting core differentiated IP.", "Starts with managed services during MVP phase to maximize shipping speed, transitioning to self-hosted open-source at massive scale.", "Encapsulates cloud/OSS dependencies behind clean interfaces to enable seamless swapping when economics shift."]}], "critical_failures": ["Ignores operational overhead, claiming self-hosted open-source software is completely free without engineering maintenance costs.", "Fails to recognize data privacy, latency, or customization limitations of proprietary third-party cloud services."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'When would you use Amazon S3, and what are its limitations?', '{"key_points": [{"id": "KP1", "description": "Ideal Use Cases & Architectural Strengths: Identifies scenarios where S3 is the optimal choice.", "required": true, "acceptable_evidence": ["Technical keywords: parquet, S3, ideal, cases.", "Unstructured object storage: storing raw PDFs, audio recordings, images, model checkpoints, and Parquet data lake files.", "Extreme durability (99.999999999% - 11 9s) and high availability across multiple Availability Zones."]}, {"id": "KP2", "description": "Cost-effective tiered storage: S3 Standard, S3 Intelligent-Tiering, S3 Glacier for long-term compliance archives.", "required": true, "acceptable_evidence": ["Technical keywords: S3 Standard, S3 Intelligent-Tiering, S3 Glacier Deep Archive, S3 Lifecycle rules, object immutability, PUT latency.", "Cost-effective tiered storage: S3 Standard, S3 Intelligent-Tiering, S3 Glacier for long-term compliance archives.", "Leverages automated S3 Lifecycle policies to transition objects from S3 Standard to S3 Intelligent-Tiering and Glacier Deep Archive for cost-effective retention."]}, {"id": "KP3", "description": "Architectural Limitations & Anti-Patterns: Explains where S3 is unsuitable.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, Redis, OLTP, PUT.", "High latency: sub-optimal for millisecond OLTP lookups (typical S3 GET/PUT latency is 50-200ms vs <5ms in Redis/PostgreSQL).", "No random partial updates: modifying an object requires rewriting the entire file (anti-pattern for transactional state management).", "Request rate limits: 3,500 PUT/POST/DELETE and 5,500 GET requests per second per prefix require thoughtful partition hashing at extreme scale."]}, {"id": "KP4", "description": "Complementary Storage Pairing: Pairs S3 with appropriate transactional and vector stores.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, RDS, OpenSearch, SQL.", "Pairs S3 for blob storage with Amazon RDS / DynamoDB for fast transactional metadata indexing and query filtering.", "Pairs S3 with Milvus or OpenSearch for vector search over chunked embeddings.", "Leverages S3 Select or Amazon Athena for serverless SQL querying over partitioned Parquet files."]}], "critical_failures": ["Recommends using Amazon S3 as a high-frequency transactional database for real-time row-level updates.", "Fails to identify S3 request latency or rate limit constraints when dealing with high-throughput applications."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Which models and cloud services would you choose for handling text, image, and audio processing, and how would they interact?', '{"key_points": [{"id": "KP1", "description": "Modality-Specific Model Selection: Selects appropriate specialized models for each data type.", "required": true, "acceptable_evidence": ["Technical keywords: AWS, VAD, GPT, CLIP.", "Audio: OpenAI Whisper or AWS Transcribe for speech-to-text; voice activity detection (VAD) for audio chunking.", "Image: Vision-language models (Claude 3.5 Sonnet, GPT-4o, AWS Rekognition) or CLIP/SigLIP for multimodal embeddings."]}, {"id": "KP2", "description": "Text: High-performance LLMs (Bedrock Claude/Llama 3) for reasoning and BGE/Text-Embedding-3 for semantic text retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon Bedrock, Claude 3.5 Sonnet, BGE embeddings, text-embedding-3, Whisper, Amazon Transcribe, multimodal pipeline.", "Text: High-performance LLMs (Bedrock Claude/Llama 3) for reasoning and BGE/Text-Embedding-3 for semantic text retrieval.", "Deploys Amazon Bedrock Claude 3.5 Sonnet for text reasoning, BAAI/BGE or OpenAI text-embedding-3 for vector search, and Amazon Transcribe for audio-to-text pipeline conversion."]}, {"id": "KP3", "description": "Cloud Service Topology & Storage: Orchestrates multimodal assets across cloud services.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, S3, PNG, EventBridge.", "Stages raw media files (audio MP3, high-res PNG) in Amazon S3 with short-lived pre-signed URLs.", "Uses Amazon EventBridge and SQS to trigger asynchronous preprocessing worker pipelines upon S3 upload.", "Stores multimodal vector embeddings in Milvus or OpenSearch with cross-modal metadata linking text and media IDs."]}, {"id": "KP4", "description": "Inter-Modality Fusion & Pipeline Coordination: Fuses outputs into cohesive user responses.", "required": false, "acceptable_evidence": ["Technical keywords: OCR, inter, modality, fusion.", "Implements multi-stage processing: transcribe audio -> extract visual entities/OCR -> fuse with text query -> generate grounded synthesis.", "Optimizes latency via parallel asynchronous processing of audio and image streams.", "Maintains end-to-end traceability linking final response claims to specific audio timestamps and image bounding boxes."]}], "critical_failures": ["Attempts to process raw audio or binary video directly through basic text-only LLM completion endpoints.", "Fails to describe how audio transcription, visual parsing, and text generation interact in a unified pipeline."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a cloud-based inference system to handle bursty traffic patterns?', '{"key_points": [{"id": "KP1", "description": "Asynchronous Decoupling & Queue Buffering: Protects inference compute from burst overload.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, SLA, Kafka, SQS.", "Decouples incoming traffic from inference workers using Amazon SQS or Kafka event streaming.", "Buffers burst spikes in durable queues, allowing worker pools to process requests at sustained optimal throughput.", "Implements token-bucket rate limiting at API Gateway to reject traffic exceeding hard SLA degradation boundaries."]}, {"id": "KP2", "description": "Autoscaling & Capacity Provisioning: Rapidly scales compute resources during surges.", "required": true, "acceptable_evidence": ["Technical keywords: SQS, ApproximateNumberOfMessagesVisible, provisioned concurrency.", "Configures autoscaling driven by queue backlog (e.g. SQS `ApproximateNumberOfMessagesVisible`) rather than lagging CPU metrics.", "Maintains a warm baseline pool with Provisioned Concurrency / pre-warmed GPU instances to eliminate cold start delays.", "Blends On-Demand instances for baseline capacity with Spot GPU instances for cost-effective burst scaling."]}, {"id": "KP3", "description": "Caching & Fast Fallback Routing: Mitigates redundant compute and manages degradation.", "required": false, "acceptable_evidence": ["Technical keywords: SSE, Redis, ElastiCache, polling webhooks.", "Caches frequent query embeddings and deterministic model outputs in ElastiCache Redis using semantic similarity hashing.", "Routes low-priority queries to smaller, faster distilled models (SLMs) when primary GPU queues are saturated.", "Provides client-side streaming (SSE) and asynchronous polling webhooks so users receive immediate feedback."]}], "critical_failures": ["Allows burst traffic to hit GPU inference workers synchronously without any queue buffering or load balancing.", "Relies solely on reactive CPU autoscaling which takes 5-10 minutes to initialize GPU nodes during a sudden traffic spike."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What were the reasons for choosing S3 for storing metadata, and what trade-offs did you consider compared to other data stores?', '{"key_points": [{"id": "KP1", "description": "S3 Metadata Storage Rationale & Strengths: Explains valid reasons for S3 object metadata.", "required": true, "acceptable_evidence": ["Technical keywords: S3, JSON, OCR, `x-amz-meta-*`.", "Co-locating object metadata directly with raw files using S3 user-defined metadata headers (`x-amz-meta-*`).", "Storing large metadata sidecar files (JSON manifests, OCR layout trees) alongside original PDFs."]}, {"id": "KP2", "description": "Leveraging S3''s low storage cost, high durability, and automatic lifecycle transitions to Glacier.", "required": true, "acceptable_evidence": ["Technical keywords: S3 11-nines durability, JSON blob storage, DynamoDB, PostgreSQL, secondary indexing, object fetch latency.", "Leveraging S3''s low storage cost, high durability, and automatic lifecycle transitions to Glacier.", "Leverages S3''s eleven-nines durability (99.999999999%) and low per-gigabyte cost for storing large immutable metadata dumps, while using PostgreSQL for indexed transactional queries."]}, {"id": "KP3", "description": "Query Limitations & Trade-offs vs Databases: Explains why S3 fails for fast querying.", "required": true, "acceptable_evidence": ["Technical keywords: ACID transactions, O(n), ACID, secondary index.", "Lack of indexing: querying S3 metadata requires slow, costly prefix listing or full-bucket scans (O(N) operations).", "No complex filtering: cannot perform multi-field range queries, joins, or secondary index lookups natively.", "No ACID transactions: lacks atomic multi-row updates, making consistent concurrent metadata updates impossible."]}, {"id": "KP4", "description": "Hybrid Architecture & Dedicated Metadata Stores: Proposes the optimal combined design.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, PostgreSQL, ObjectCreated, S3.", "Stores heavy raw documents and archival manifests in S3 while indexing searchable metadata in PostgreSQL or DynamoDB.", "Syncs S3 event notifications (ObjectCreated) via Lambda to automatically populate relational metadata tables.", "Enables sub-10ms metadata filtering and RBAC checks in the database before generating S3 pre-signed fetch URLs."]}], "critical_failures": ["Claims S3 is superior to relational databases for complex multi-attribute filtering and relational queries.", "Fails to identify the performance penalty of listing and searching metadata across millions of S3 objects."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Are there any specific tools that you like better than others, and would you use Cursor again?', '{"key_points": [{"id": "KP1", "description": "Tool Evaluation & Productivity Multipliers: Explains concrete developer efficiency improvements.", "required": true, "acceptable_evidence": ["Technical keywords: precision, codebase indexing, @codebase, Composer.", "Leverages Cursor''s codebase indexing (@codebase) and semantic retrieval across repositories for fast contextual understanding.", "Accelerates boilerplate generation, unit test scaffolding, docstring generation, and multi-file refactoring (Composer).", "Uses inline diff generation to review and accept code modifications with surgical precision."]}, {"id": "KP2", "description": "Technical Limitations & Failure Modes: Analyzes hallucinations, context limits, and security.", "required": true, "acceptable_evidence": ["Technical keywords: context window, Zero Data Retention, modes, hallucinations.", "Identifies hallucinated imports, obsolete package APIs, or subtle logic bugs introduced by generative code completion.", "Addresses security concerns: ensuring enterprise code is not used for model training (privacy mode / zero data retention).", "Recognizes context window degradation in massive repositories where the model loses track of global architectural patterns."]}, {"id": "KP3", "description": "Developer Discipline & Future Adoption: Explains how to maintain craftsmanship with AI tools.", "required": false, "acceptable_evidence": ["Technical keywords: AI, critical authentication, developer, discipline.", "Treats AI code suggestions as draft PRs: insists on personal line-by-line verification, linting, and automated test execution.", "Explains when to turn AI tools off (deep novel algorithm design, security-critical authentication logic, fine profiling).", "Articulates why they would use Cursor again while establishing team coding standards around AI-generated code."]}], "critical_failures": ["Blindly copies and pastes AI-generated code into production without understanding what it does or testing it.", "Rejects all modern developer tooling dogmatically or claims AI coding tools have zero flaws or security implications."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Are you familiar with DBT (Data Build Tool)? Have you used DBT before?', '{"key_points": [{"id": "KP1", "description": "DBT Paradigm & Modular SQL Models: Explains the Transform in ELT and model structure.", "required": true, "acceptable_evidence": ["Technical keywords: DBT, SQL, ELT, DAG.", "Explains DBT''s role in analytics engineering: handles the ''T'' (Transformation) in ELT inside the data warehouse.", "Organizes models into structured layers: Staging (cleaning/casting raw tables), Intermediate (business logic), Marts (consumption schemas).", "Uses the `ref()` function to dynamically resolve dependencies and build an automated DAG execution lineage."]}, {"id": "KP2", "description": "Materializations, Jinja & Incremental Models: Optimizes compute and execution speed.", "required": true, "acceptable_evidence": ["Technical keywords: is_incremental, DRY, aware schemas, SQL.", "Configures materializations: `view`, `table`, `ephemeral`, and `incremental`.", "Implements incremental models with `is_incremental()` macro to process only new/updated rows, saving compute costs.", "Uses Jinja templating and macros for DRY SQL code, dynamic pivot tables, and environment-aware schemas."]}, {"id": "KP3", "description": "Testing, Documentation & CI/CD Deployment: Enforces data quality and documentation.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, not_null, accepted_values, CI.", "Applies out-of-the-box generic tests (`unique`, `not_null`, `accepted_values`, `relationships`) in YAML schema definitions.", "Integrates with packages (dbt-expectations) for advanced statistical validation tests.", "Generates automated data catalog documentation (`dbt docs generate`) and runs DBT in CI/CD pipelines (dbt Cloud / Airflow)."]}], "critical_failures": ["Does not know what DBT is or confuses it with an ingestion tool like Fivetran/Airbyte.", "Cannot explain the `ref()` function or does not understand how incremental models work."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'BROAD', 150, 'Are you familiar with any open source models? Have you used the Hugging Face library?', '{"key_points": [{"id": "KP1", "description": "Open-Source Model Landscape & Selection: Details familiarity with leading open-source models.", "required": true, "acceptable_evidence": ["Technical keywords: BAAI, source trade-offs, 70B.", "Identifies leading open-weights LLMs: Meta Llama 3/3.1 (8B, 70B), Mistral/Mixtral 8x7B, Qwen 2.5, Phi-3.", "Identifies leading embedding and reranker models: BAAI/bge-large-en, bge-reranker-large, sentence-transformers.", "Evaluates open-source trade-offs: full data privacy, customizable weights, lower long-term inference cost vs GPU hosting overhead."]}, {"id": "KP2", "description": "Hugging Face Ecosystem & Programming: Demonstrates hands-on coding with Hugging Face libraries.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, QLoRA, quantization, device_map.", "Uses core abstractions: `AutoTokenizer`, `AutoModelForCausalLM`, `pipeline`, and `datasets`.", "Handles tokenization mechanics: padding tokens, truncation, attention masks, and special tokens.", "Loads models efficiently using quantization techniques: bitsandbytes (4-bit/8-bit QLoRA) and device mapping (`device_map=''auto''`)."]}, {"id": "KP3", "description": "Fine-Tuning & Production Serving Runtimes: Explains optimization and deployment.", "required": false, "acceptable_evidence": ["Technical keywords: vLLM, PagedAttention, fine-tuning, LoRA.", "Applies parameter-efficient fine-tuning (PEFT/LoRA) using the Hugging Face `peft` and `trl` libraries.", "Deploys open-source models using high-throughput serving engines (vLLM, TGI, Ollama) featuring PagedAttention.", "Manages Hugging Face Hub operations: model cards, repository tokens, and private enterprise model registries."]}], "critical_failures": ["Only knows proprietary SaaS APIs (OpenAI) and has zero awareness of open-source models or Hugging Face.", "Cannot explain how to instantiate a model and tokenizer in Python using Hugging Face Transformers."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain what decorators are?', '{"key_points": [{"id": "KP1", "description": "Decorator Mechanics & First-Class Functions: Explains higher-order functions and syntax.", "required": true, "acceptable_evidence": ["Technical keywords: func, *args, **kwargs.", "Explains that functions in Python are first-class citizens that can be passed as arguments, nested, and returned.", "Explains decorator syntactic sugar (`@decorator` is equivalent to `func = decorator(func)`).", "Demonstrates standard decorator structure: an outer function taking `func`, defining an inner `wrapper(*args, **kwargs)`, and returning `wrapper`."]}, {"id": "KP2", "description": "Metadata Preservation with functools.wraps: Explains introspection and closure state.", "required": true, "acceptable_evidence": ["Technical keywords: functools.wraps, decorators, __name__, __doc__.", "Explains why `@functools.wraps(func)` is crucial: preserves original function metadata (`__name__`, `__doc__`, annotations) for debugging and documentation.", "Explains closure mechanics: how the inner wrapper function retains access to the outer function''s scope.", "Explains decorators that take arguments (requiring a 3-level nested function structure)."]}, {"id": "KP3", "description": "Real-World Production Applications: Shares concrete engineering use cases.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, rate limiting, FastAPI, memoization.", "Authentication & Authorization checks (e.g. `@require_auth`, `@admin_only` in FastAPI/Flask).", "Execution timing, logging, and metrics collection (e.g. `@time_execution`, `@log_inputs`).", "Rate limiting, caching/memoization (`@functools.lru_cache`), and retry logic with exponential backoff (`@retry`)."]}], "critical_failures": ["Does not know what a decorator is or cannot explain how it modifies function execution.", "Fails to mention wrapper functions or why `functools.wraps` is needed to preserve function metadata."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Can you explain your approach to A/B testing in ML systems and how it influenced your model improvements?', '{"key_points": [{"id": "KP1", "description": "Experiment Design & Traffic Allocation: Deploys champion-challenger or canary routing.", "required": true, "acceptable_evidence": ["Technical keywords: canary routing, Champion, Challenger.", "Architects champion-challenger setup: existing production model (Champion) serves majority traffic while new model (Challenger) receives test percentage.", "Implements shadow deployment prior to live traffic to validate latency, memory, and output distributions without user risk."]}, {"id": "KP2", "description": "Use consistent user hashing to route traffic deterministically between control and variant groups.", "required": true, "acceptable_evidence": ["Technical keywords: consistent hashing, MurmurHash3, traffic split, A/B testing, statistical significance, p-value, RAGAS faithfulness.", "Uses consistent user hashing to route traffic deterministically between control and variant groups.", "Applies consistent hashing (e.g. MurmurHash3 on user_id) to allocate traffic deterministically into 50/50 control and variant cohorts without state leakage."]}, {"id": "KP3", "description": "Online Metric Tracking & Guardrail Monitoring: Measures online business and performance metrics.", "required": true, "acceptable_evidence": ["Technical keywords: p95, p99, guardrail metrics, inference latency.", "Tracks primary business metrics (conversion rate, click-through rate, fraud detection catch rate, handle time).", "Monitors system guardrail metrics (p95/p99 inference latency, error rates, compute cost per transaction).", "Compares online performance against offline evaluation baselines to detect offline-to-online distribution gaps."]}, {"id": "KP4", "description": "Statistical Significance & Model Iteration: Uses hypothesis testing to guide model improvements.", "required": false, "acceptable_evidence": ["Technical keywords: p-values, confidence intervals, statistical, significance.", "Evaluates statistical significance (p-values, confidence intervals) ensuring sample size satisfies pre-experiment power calculations.", "Extracts error analysis from the challenger model''s failed predictions to guide subsequent retraining and feature engineering.", "Executes automated promotion of challenger to champion upon passing statistical and performance thresholds."]}], "critical_failures": ["Deploys new ML models directly to 100% of production traffic without any canary, shadow, or A/B testing validation.", "Declares a model superior based on raw numbers without verifying statistical significance or monitoring guardrail metrics."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your approach to solving a pattern-based problem using a stack?', '{"key_points": [{"id": "KP1", "description": "Stack Mechanics & Pattern Identification: Recognizes problems requiring Last-In-First-Out processing.", "required": true, "acceptable_evidence": ["Technical keywords: time complexity, O(1), LIFO, `push`.", "Identifies LIFO problem patterns: matching brackets/parentheses, undo operations, nested expression evaluation, and backtracking.", "Explains core operations (`push`, `pop`, `peek`) with O(1) time complexity.", "Uses stack to maintain immediate context while deferring resolution of outer elements."]}, {"id": "KP2", "description": "Monotonic Stack Technique & Invariant Maintenance: Solves next-greater/smaller element problems.", "required": true, "acceptable_evidence": ["Technical keywords: monotonic stack, monotonic, stack, technique.", "Explains monotonic stack concept: maintaining elements in strictly increasing or decreasing order.", "Walks through standard pattern (e.g. Next Greater Element, Daily Temperatures, Largest Rectangle in Histogram).", "Demonstrates how popping violating elements resolves the query for popped items while maintaining the invariant."]}, {"id": "KP3", "description": "Complexity Analysis & Edge Cases: Proves optimal performance and handles boundary conditions.", "required": false, "acceptable_evidence": ["Technical keywords: space complexity, O(n), time complexity.", "Proves overall O(N) time complexity via amortized analysis (each element pushed and popped at most once).", "Analyzes O(N) auxiliary space complexity in worst-case scenarios.", "Handles edge cases: empty input strings, unbalanced brackets, duplicate values, and strictly monotonic arrays."]}], "critical_failures": ["Cannot explain how a stack works (confuses LIFO with FIFO queue).", "Reverts to a naive O(N^2) nested loop without understanding how a monotonic stack achieves O(N) time."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your approach to solving the longest substring problem where each character appears at most twice?', '{"key_points": [{"id": "KP1", "description": "Sliding Window State & Two Pointers: Defines window pointers and frequency tracking.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, two pointers, window state, integer array `count[256]`.", "Initializes two pointers: `left = 0` and iterates `right` from 0 to N-1 over the string.", "Maintains a character frequency map (hash map or integer array `count[256]` / `count[26]`).", "Explains that the window `s[left:right+1]` represents the candidate valid substring."]}, {"id": "KP2", "description": "Expansion & Contraction Conditions: Expands right and shrinks left when invariant is violated.", "required": true, "acceptable_evidence": ["Technical keywords: max_len, expansion, contraction, conditions.", "Expands window by adding `s[right]` to frequency count on each step.", "Checks invariant: if `count[s[right]] > 2`, shrinks window by decrementing `count[s[left]]` and incrementing `left` until `count[s[right]] <= 2`.", "Updates `max_len = max(max_len, right - left + 1)` whenever the window is in a valid state."]}, {"id": "KP3", "description": "Complexity Proof & Edge Case Handling: Analyzes time/space efficiency and boundaries.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(1), O(n).", "Proves linear time complexity O(N): both `left` and `right` pointers traverse the string at most once.", "Analyzes space complexity: O(1) or O(K) where K is character set size (at most 26 lowercase English letters or 128 ASCII).", "Handles edge cases: empty string, single character string, string with no duplicates, and all identical characters."]}], "critical_failures": ["Proposes an inefficient O(N^3) or O(N^2) brute force algorithm generating all substrings.", "Fails to contract the left pointer correctly when a character frequency exceeds 2."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Can you mention some Spark operations you used?', '{"key_points": [{"id": "KP1", "description": "Narrow vs Wide Transformations: Categorizes transformations and explains shuffle implications.", "required": true, "acceptable_evidence": ["Technical keywords: narrow, transformations, categorizes, shuffle.", "Names narrow transformations: `select()`, `filter()`/`where()`, `withColumn()`, `map()`, `flatMap()` (execute within single partition without cross-network shuffle).", "Names wide transformations: `groupBy()`, `join()`, `distinct()`, `repartition()`, `orderBy()` (require data shuffling across cluster nodes).", "Explains how minimizing wide transformations reduces network I/O and job execution time."]}, {"id": "KP2", "description": "Actions & Execution Triggering: Differentiates lazy transformations from eager actions.", "required": true, "acceptable_evidence": ["Technical keywords: lazy evaluation, parquet, write.save, write.parquet.", "Names Spark actions: `count()`, `collect()`, `show()`, `take()`, `write.save()` / `write.parquet()`.", "Explains lazy evaluation: transformations only build the execution DAG; actions trigger Catalyst optimization and cluster computation.", "Warns against calling `collect()` on massive distributed datasets to prevent Driver Out-Of-Memory (OOM) crashes."]}, {"id": "KP3", "description": "Advanced Spark SQL Operations: Details joins, windowing, and caching.", "required": false, "acceptable_evidence": ["Technical keywords: row_number, Window.partitionBy, StorageLevel.MEMORY_AND_DISK, SQL.", "Uses `broadcast()` joins for small lookup tables to eliminate costly full-cluster shuffle joins.", "Employs Spark SQL Window functions (`row_number().over(Window.partitionBy().orderBy())`) for deduplication and ranking.", "Uses `.cache()` / `.persist(StorageLevel.MEMORY_AND_DISK)` judiciously on DataFrames reused across multiple downstream actions."]}], "critical_failures": ["Cannot distinguish between Spark transformations and actions.", "Believes transformations execute immediately upon invocation without requiring an action."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Can you share an example where your personality or interpersonal skills positively influenced a professional interaction or outcome?', '{"key_points": [{"id": "KP1", "description": "Interpersonal Context & Challenge: Frames a professional scenario requiring emotional intelligence.", "required": true, "acceptable_evidence": ["Technical keywords: emotional states, interpersonal, context, challenge.", "Describes a real-world situation involving interpersonal friction, stakeholder resistance, a demoralized team, or a cross-functional impasse.", "Demonstrates awareness of other participants'' emotional states, motivations, and unstated concerns.", "Sets a clear constructive goal for resolving the situation positively."]}, {"id": "KP2", "description": "Empathetic Action & Relationship Building: Uses active listening and warmth to build alignment.", "required": true, "acceptable_evidence": ["Technical keywords: empathetic, action, relationship, building.", "Initiates empathetic 1-on-1 dialogue, listening without judgment and validating the other person''s perspective.", "Uses humor, humility, or shared human commonalities to de-escalate tension and establish psychological safety.", "Bridges communication styles, translating technical concerns into empathetic human terms."]}, {"id": "KP3", "description": "Concrete Professional Outcome & Lasting Impact: Delivers measurable success and strengthens culture.", "required": false, "acceptable_evidence": ["Technical keywords: concrete, professional, outcome, lasting.", "Achieves the desired professional goal (e.g., stakeholder approved the project, teammates reconciled, cross-team partnership unblocked).", "Builds enduring trust and ongoing collaboration beyond the immediate incident.", "Reflects with self-awareness on how their interpersonal approach fostered positive team culture."]}], "critical_failures": ["Shares an example of manipulation, arrogance, or aggressive behavior rather than genuine interpersonal skills.", "Cannot provide a concrete scenario or describes an outcome where relationships were damaged."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Did you ever run over budget and how did you deliver on expectations after meeting your allotted budget?', '{"key_points": [{"id": "KP1", "description": "Budget Overrun Root-Cause Analysis: Diagnoses financial expenditure drivers with precision.", "required": true, "acceptable_evidence": ["Technical keywords: precision, Datadog, LLM, AWS.", "Identifies exact causes of budget overrun (e.g. unpredicted LLM token spikes, under-provisioned GPU cluster hours, unindexed database query scans).", "Conducts cost auditing using AWS Cost Explorer, Datadog cost monitoring, or API billing dashboards.", "Separates one-time experimentation spike costs from recurring operational expenditures."]}, {"id": "KP2", "description": "Technical Cost Optimization & Waste Elimination: Implements engineering optimizations to cut spend.", "required": true, "acceptable_evidence": ["Technical keywords: prompt caching, AWS, SLMs.", "Optimizes model spend: introduces prompt caching, compresses context chunks, routes simple queries to smaller models (SLMs).", "Right-sizes compute instances, switches idle resources to Spot instances, and cleans up orphaned test environments.", "Sets up AWS Budgets and automated billing alerts with Slack notifications to prevent runaway spend."]}, {"id": "KP3", "description": "Stakeholder Transparency & Expectation Delivery: Realigns deliverables constructively with leadership.", "required": false, "acceptable_evidence": ["Technical keywords: stakeholder, expectation, realigns, deliverables.", "Communicates budget status transparently to engineering leadership and finance with actionable remediation options.", "Negotiates phased delivery milestones to ensure high-priority business value ships on schedule.", "Delivers expected product capabilities within newly calibrated cost boundaries, earning leadership trust."]}], "critical_failures": ["Hides budget overruns from leadership until financial limits are breached with zero warning.", "Fails to implement any technical cost optimizations (caching, right-sizing, prompt compression) to control spend."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Did you use A/B testing or statistical methods to validate improvements in your system?', '{"key_points": [{"id": "KP1", "description": "Statistical Hypothesis Testing & Significance: Applies rigorous statistical tests to evaluation data.", "required": true, "acceptable_evidence": ["Technical keywords: alpha = 0.05, minimum meaningful effect, statistical, hypothesis.", "Applies appropriate statistical tests: paired two-sample t-test (for normally distributed evaluation metric scores) or Wilcoxon signed-rank test (for non-parametric scores).", "Calculates p-values against significance threshold (alpha = 0.05) and calculates 95% confidence intervals around effect size.", "Differentiates practical significance (minimum meaningful effect) from raw statistical significance."]}, {"id": "KP2", "description": "A/B Testing Architecture & Traffic Splitting: Validates online improvements in production.", "required": true, "acceptable_evidence": ["Technical keywords: A/B testing, 50 control, variant.", "Splits live user traffic via randomized bucketing (e.g. 50/50 control vs variant) using deterministic hashing on user IDs.", "Maintains a consistent user experience (user remains in the same variant bucket throughout their entire session).", "Runs A/A tests prior to experimentation to verify baseline balance and eliminate instrumentation bias."]}, {"id": "KP3", "description": "Metric Correlation & Bias Mitigation: Aligns offline metrics with online user outcomes.", "required": false, "acceptable_evidence": ["Technical keywords: DeepEval, SRM, user metrics, guardrail metrics.", "Correlates offline evaluation gains (Hit Rate, Faithfulness, DeepEval scores) with online user metrics (conversion, user satisfaction).", "Monitors guardrail metrics (latency, error rate, cancellation rate) during experiments to detect unintended trade-offs.", "Accounts for confounding variables: day-of-week seasonality, novelty bias, and sample ratio mismatch (SRM)."]}], "critical_failures": ["Claims an improvement is valid based on a tiny percentage difference without any statistical testing or significance checks.", "Confuses offline benchmark evaluations with live production A/B testing."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'Do you know how to do dimensional modeling?', '{"key_points": [{"id": "KP1", "description": "Fact vs Dimension Table Architecture: Differentiates quantitative measures from business context.", "required": true, "acceptable_evidence": ["Technical keywords: table architecture, quantitative metrics, additive, semi-additive.", "Fact Tables: store numeric quantitative metrics and foreign keys representing business events (additive, semi-additive, non-additive facts).", "Dimension Tables: store descriptive textual context attributes (who, what, where, when, why) providing query filtering and grouping context.", "Defines surrogate keys (independent integer keys) instead of natural business keys for dimension primary keys."]}, {"id": "KP2", "description": "Schema Topology: Star Schema vs Snowflake Schema: Contrasts normalization trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: Snowflake, BigQuery, OLAP, star schema.", "Star Schema: denormalized dimension tables joined directly to fact table (simpler queries, faster join performance, optimized for OLAP).", "Snowflake Schema: normalized dimension tables split into sub-dimensions (reduces redundancy, but increases join complexity and query latency).", "Justifies star schema dominance in modern columnar data warehouses (Snowflake, BigQuery, Redshift)."]}, {"id": "KP3", "description": "Slowly Changing Dimensions (SCD) & Conformed Dimensions: Handles temporal attribute changes.", "required": false, "acceptable_evidence": ["Technical keywords: SCD, no historical tracking, slowly, changing.", "Explains SCD Type 1: overwrite historical value (no historical tracking).", "Explains SCD Type 2: add new row with surrogate key, effective start/end dates, and current flag (preserves full historical record).", "Explains SCD Type 3: add new column to store previous value (tracks limited change history)."]}], "critical_failures": ["Cannot distinguish between Fact tables and Dimension tables.", "Applies third normal form (3NF) transactional OLTP modeling indiscriminately to analytical data warehouse designs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Do you talk to customers and identify the use cases and then bring them to solutions or are the use cases already given to you?', '{"key_points": [{"id": "KP1", "description": "Direct Customer Engagement & Problem Discovery: Uncovers root needs through active inquiry.", "required": true, "acceptable_evidence": ["Technical keywords: AI, customer, engagement, problem.", "Engages directly with customers and end users to observe real workflows rather than relying solely on secondhand specs.", "Differentiates what users ask for (''build me an AI chatbot'') from what they actually need (''automate this 40-minute manual claim verification'').", "Asks targeted ''Why'' questions to uncover underlying operational bottlenecks and business metrics."]}, {"id": "KP2", "description": "Translating Discovery into Technical Architecture: Converts qualitative pain points into engineering specs.", "required": true, "acceptable_evidence": ["Technical keywords: API, success metrics, time saved, error reduction.", "Synthesizes customer conversations into user journey maps, technical requirements, and API interface boundaries.", "Builds low-fidelity prototypes or technical spikes to validate workflow solutions with customers early.", "Defines verifiable success metrics (time saved, error reduction, throughput) jointly with customer stakeholders."]}, {"id": "KP3", "description": "Collaboration with Product Management: Balances customer intimacy with product roadmap.", "required": false, "acceptable_evidence": ["Technical keywords: product, management, intimacy, customer.", "Partners closely with Product Managers, sharing customer discovery insights to enrich the product roadmap.", "Avoids building one-off custom hacks for single vocal customers; extracts generalized platform capabilities.", "Demonstrates adaptability to work both from high-level customer discovery and structured predefined specs."]}], "critical_failures": ["Shows complete disinterest in user needs, viewing software engineering strictly as mindless ticket-taking.", "Builds bespoke unmaintainable hacks for individual customers without architectural generalization or product alignment."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Explain everything about state management.', '{"key_points": [{"id": "KP1", "description": "State Types & Separation of Concerns: Differentiates ephemeral working state from durable persistent state.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, PostgreSQL, TypedDict.", "Differentiates ephemeral in-flight state (working memory, request context, LangGraph graph state) from durable persistent state (PostgreSQL, DynamoDB).", "Defines strongly-typed state schemas using Pydantic or TypedDict to enforce contract consistency across components.", "Separates user identity state, session conversation state, and workflow execution state."]}, {"id": "KP2", "description": "State Transitions, Reducers & Immutability: Manages deterministic updates and concurrency.", "required": true, "acceptable_evidence": ["Technical keywords: immutability, Redis, add_messages, pure state.", "Employs pure state reducers (e.g. `Annotated[list, add_messages]` in LangGraph) to append or merge state predictably.", "Enforces immutability: nodes return delta updates rather than mutating shared global state in place.", "Handles race conditions and concurrency using optimistic locking (version numbers) or distributed Redis locks."]}, {"id": "KP3", "description": "Durable Checkpointing, Time-Travel & Replay: Implements fault recovery and state snapshots.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointing, PostgreSQL, TTL, snapshot state.", "Configures persistent checkpointers (Redis/PostgreSQL/DynamoDB) to snapshot state at every graph node transition.", "Enables time-travel debugging: ability to inspect historical state at step N, modify parameters, and re-execute from that checkpoint.", "Implements state cleanup policies: TTL expiration for inactive sessions to prevent database bloat."]}], "critical_failures": ["Mutates global variables in-memory across concurrent user requests, introducing severe race conditions and data corruption.", "Cannot differentiate ephemeral in-memory state from persistent database storage."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Explain your strategy for managing secrets, environment variables, and configurations across different environments (e.g., local development vs. production).', '{"key_points": [{"id": "KP1", "description": "Environment Configuration & 12-Factor Discipline: Separates code from configuration cleanly.", "required": true, "acceptable_evidence": ["Technical keywords: environment, configuration, factor, discipline.", "Strictly adheres to 12-Factor App methodology: stores config in environment variables, never hardcoded in source code.", "Uses `.env` files for local development explicitly excluded from version control via `.gitignore`."]}, {"id": "KP2", "description": "Employs typed configuration parsers (e.g., Pydantic `BaseSettings`) with environment variable overrides and validation on startup.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic BaseSettings, AWS Secrets Manager, HashiCorp Vault, runtime validation, environment variables, .env security.", "Employs typed configuration parsers (e.g., Pydantic `BaseSettings`) with environment variable overrides and validation on startup.", "Uses Pydantic BaseSettings to enforce strict typing, default values, and runtime validation for all environment variables upon application initialization."]}, {"id": "KP3", "description": "Enterprise Secrets Vaults & Production Ingestion: Ingests credentials dynamically from secure vaults.", "required": true, "acceptable_evidence": ["Technical keywords: REST, Docker, Kubernetes, API.", "Stores production credentials (API keys, DB passwords, private keys) in AWS Secrets Manager, SSM Parameter Store, or HashiCorp Vault.", "Injects secrets securely into containers at runtime (e.g. AWS ECS secrets mapping from Secrets Manager, Kubernetes Secrets) without baking into Docker images.", "Enforces KMS encryption at rest and TLS encryption in transit for all secret values."]}, {"id": "KP4", "description": "Access Governance, Rotation & Leakage Prevention: Manages secret lifecycle and pre-commit scanning.", "required": false, "acceptable_evidence": ["Technical keywords: IAM, TruffleHog, CI, access governance.", "Enforces least-privilege IAM policies controlling which roles can read specific secret paths.", "Configures automated secret rotation (e.g. database password rotation via Lambda triggers).", "Runs automated pre-commit hooks (TruffleHog, git-secrets) and CI secret scanning to prevent accidental credential leakage to Git."]}], "critical_failures": ["Hardcodes sensitive production secrets or API keys in Git repository source code.", "Bakes plaintext secrets directly into Docker images or shares production credentials via Slack/email."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'For the conditional nodes, how do you decide whether to invoke that node or not?', '{"key_points": [{"id": "KP1", "description": "Conditional Edge Routing Mechanics: Explains how router functions evaluate state and return destination nodes.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, conditional edges, add_conditional_edges, router_function.", "Implements LangGraph conditional edges (`add_conditional_edges(source, router_function, path_map)`).", "Router function inspects current graph state (e.g., `state[''classified_intent'']`, `state[''confidence_score'']`).", "Maps router output deterministically to candidate node names (e.g., ''eligibility_node'', ''claims_node'', ''escalation_node'')."]}, {"id": "KP2", "description": "Decision Criteria & Intent Classification: Leverages structured outputs and thresholds to branch.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, human-in-the-loop, structured outputs, policy validation.", "Uses a Triage/Classifier agent generating structured Pydantic outputs with strict intent enums and confidence floats.", "Enforces confidence threshold gating (e.g. if `confidence < 0.75`, route to human review or clarification node).", "Evaluates policy validation flags (e.g., if action is financial or high-risk, route to Human-in-the-Loop approval node)."]}, {"id": "KP3", "description": "Fallback Paths, Loop Guards & Edge Cases: Prevents infinite cycles and unhandled branches.", "required": false, "acceptable_evidence": ["Technical keywords: iteration_count, CloudWatch, recursion loop, infinite loops.", "Provides a robust default fallback path for unrecognized or ambiguous intents.", "Implements recursion loop guards (tracking `iteration_count` in state) to prevent infinite loops between conditional nodes.", "Logs routing decisions with input features and chosen path for offline analysis in Langfuse / CloudWatch."]}], "critical_failures": ["Hardcodes static branching without inspecting state or relies on unconstrained free-text LLM output to determine node routing.", "Fails to provide a default fallback path, resulting in unhandled exceptions or infinite agent loops."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Have you built AI systems from scratch, and what key technical and architectural decisions did you make during that process?', '{"key_points": [{"id": "KP1", "description": "Architecture Decomposition & Component Selection: Selects and bounds core system layers.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, MCP, RAG, Milvus.", "Decomposes system into clean architectural layers: Experience/API layer, Orchestration layer (LangGraph), Knowledge/RAG layer (Milvus), and Action/Tool layer (MCP).", "Justifies model selection: choosing foundation models (GPT-4o, Claude 3.5 Sonnet) based on reasoning needs vs lightweight models for classification."]}, {"id": "KP2", "description": "Selects storage architecture: vector database (Milvus) for semantic search, PostgreSQL for transactions, Redis for ephemeral session caching.", "required": true, "acceptable_evidence": ["Technical keywords: polyglot persistence, Milvus vector store, PostgreSQL ACID, Redis cache, FastAPI, LangGraph orchestration.", "Selects storage architecture: vector database (Milvus) for semantic search, PostgreSQL for transactions, Redis for ephemeral session caching.", "Architects a tiered polyglot persistence model: Milvus for vector embeddings, PostgreSQL for relational transactions and audit history, and Redis for ephemeral session state."]}, {"id": "KP3", "description": "Retrieval & Context Engineering Design: Crafts reliable context retrieval and token management.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, cross-encoder reranking, HNSW, sliding window.", "Designs offline ingestion: document parsing (Docling), chunking with overlap (512 tokens), and BGE embeddings.", "Implements hybrid retrieval (dense Milvus HNSW + sparse BM25) paired with Cross-Encoder reranking.", "Employs context pruning, sliding window compaction, and citation injection to maximize answer fidelity."]}, {"id": "KP4", "description": "Production Hardening, Guardrails & Evaluation: Ensures reliability, safety, and continuous testing.", "required": false, "acceptable_evidence": ["Technical keywords: PII redaction, distributed tracing, CI/CD, PII.", "Installs guardrails: Presidio PII redaction, input sanitization, and output hallucination verification.", "Establishes automated evaluation pipelines (DeepEval) with golden datasets to gate CI/CD deployments.", "Deploys containerized microservices on AWS ECS with distributed tracing (Langfuse) and CloudWatch monitoring."]}], "critical_failures": ["Describes building a toy prototype (e.g. single unconstrained prompt in a notebook) rather than an architected system.", "Cannot justify why specific architectural components (orchestrator, vector DB, guardrails) were chosen."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Have you ever created a platform?', '{"key_points": [{"id": "KP1", "description": "Platform Problem Identification & Core Abstractions: Solves developer toil through shared platforms.", "required": true, "acceptable_evidence": ["Technical keywords: REST, gRPC, SDK, CLI.", "Identified systemic engineering friction: multiple teams independently reinventing ingestion, model deployment, and monitoring pipelines.", "Built standardized platform abstractions: unified model gateway, shared vector search APIs, standardized tool wrappers.", "Exposed clean developer interfaces: Python SDK, REST/gRPC endpoints, and scaffolding CLI templates."]}, {"id": "KP2", "description": "Multi-Tenant Isolation, Governance & Scaling: Enforces security and resource boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, IAM, tenant isolation, database schemas.", "Enforces strict multi-tenancy: isolated vector collections/partitions, tenant-scoped database schemas, and IAM policies.", "Implements rate limiting, compute quotas, and cost chargeback/attribution tracking per onboarding team.", "Automates high availability, blue/green deployments, and infrastructure scaling behind platform load balancers."]}, {"id": "KP3", "description": "Developer Experience, Documentation & Adoption: Drives internal organizational adoption.", "required": false, "acceptable_evidence": ["Technical keywords: SDK, API, developer, experience.", "Authored comprehensive documentation, sample starter repos, and conducted internal workshops to train engineering teams.", "Measured developer productivity gains: reduced feature onboarding time from weeks to hours.", "Maintained backward compatibility and semantic versioning across platform SDK and API releases."]}], "critical_failures": ["Confuses building a single feature or standalone app with architecting a reusable multi-tenant platform.", "Ignores multi-tenancy, resource quotas, or developer onboarding experience when describing platform engineering."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Have you heard about duck typing? Can you explain what that is?', '{"key_points": [{"id": "KP1", "description": "Duck Typing Definition & Behavioral Typing: Explains polymorphism determined by methods rather than class inheritance.", "required": true, "acceptable_evidence": ["Technical keywords: duck typing, typing, definition, behavioral.", "Quotes or explains the idiom: ''If it walks like a duck and quacks like a duck, it''s a duck''.", "Explains that Python evaluates an object''s suitability based on the presence of specific methods and attributes, not its explicit inheritance hierarchy."]}, {"id": "KP2", "description": "Contrasts dynamic duck typing with nominal typing in statically typed languages (Java/C++ requiring explicit interface implementation).", "required": true, "acceptable_evidence": ["Technical keywords: duck typing, dynamic dispatch, hasattr, typing.Protocol, nominal typing, structural subtyping, interface inheritance.", "Contrasts dynamic duck typing with nominal typing in statically typed languages (Java/C++ requiring explicit interface implementation).", "Contrasts Python''s runtime duck typing (''if it walks like a duck, it''s a duck'') with static nominal typing in Java/C++, illustrating with hasattr() or typing.Protocol."]}, {"id": "KP3", "description": "Python Protocols & Dunder Methods: Illustrates duck typing with standard Python protocols.", "required": true, "acceptable_evidence": ["Technical keywords: __enter__, __exit__, __iter__, __getitem__.", "Iterable protocol: any object implementing `__iter__()` or `__getitem__()` works in a `for` loop without inheriting from an Iterable class.", "File-like object protocol: any object implementing `.read()` and `.write()` works with file processors (e.g. `io.StringIO`).", "Context Manager protocol: any object implementing `__enter__()` and `__exit__()` works with `with` statements."]}, {"id": "KP4", "description": "EAFP vs LBYL & Modern Type Hints: Connects duck typing to Python idioms and typing.Protocol.", "required": false, "acceptable_evidence": ["Technical keywords: typing.Protocol, structural subtyping, EAFP, LBYL.", "Explains Python''s EAFP philosophy (''Easier to Ask for Forgiveness than Permission''): using `try...except AttributeError` over explicit `isinstance()` checks.", "Explains modern structural subtyping using `typing.Protocol` (PEP 544) to get static type checking with duck typing flexibility.", "Discusses trade-offs: high flexibility and decoupling vs runtime AttributeErrors if required methods are missing."]}], "critical_failures": ["Does not know what duck typing is or confuses it with static typing or inheritance.", "Believes an object in Python must explicitly inherit from a base class to be used polymorphically."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Have you heard about hooks, like running something before a tool execution?', '{"key_points": [{"id": "KP1", "description": "Pre-Execution Hook Architecture: Explains interceptor/middleware pattern wrapping tool execution.", "required": true, "acceptable_evidence": ["Technical keywords: decorators, LangChain, MCP, on_tool_start.", "Defines hooks as interceptor functions/callbacks triggered automatically immediately prior to invoking an external tool.", "Implements hooks via MCP wrapper layers, LangChain tool callbacks (`on_tool_start`), or custom Python decorators.", "Maintains separation of concerns: the agent LLM decides *what* to do, while the hook enforces *safety/policy constraints*."]}, {"id": "KP2", "description": "Validation, Security & Policy Gating: Enforces safety checks before tools execute.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, PII redaction, LLM, PII.", "Input parameter validation: parses and validates LLM-generated arguments against Pydantic schemas before calling external APIs.", "Security & PII redaction: screens arguments for sensitive data or malicious payloads before network egress.", "Authorization & Policy checks: verifies user permissions (e.g. check if user has role to issue refunds) and blocks unauthorized invocations."]}, {"id": "KP3", "description": "Audit Logging, Tracing & Error Handling: Captures execution telemetry.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, ID, LLM.", "Emits structured audit logs with timestamp, tool name, user ID, and sanitized inputs for compliance tracking.", "Starts distributed tracing spans (OpenTelemetry, Langfuse) to measure tool latency and downstream dependency health.", "Implements graceful error handling: raises clean, model-interpretable errors if hook validation fails, allowing LLM self-correction."]}], "critical_failures": ["Has no concept of hooks or executes arbitrary LLM tool calls directly without any validation, logging, or security interceptor.", "Believes pre-execution hooks can only be implemented inside the LLM prompt rather than in deterministic application code."]}', 1),
('HIRING_MANAGER', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'BROAD', 150, 'How can AI tools be integrated into the SDLC to improve developer productivity and reduce inefficiencies?', '{"key_points": [{"id": "KP1", "description": "SDLC Phase Integration: Integrates AI across planning, authoring, and review workflows.", "required": true, "acceptable_evidence": ["Technical keywords: SDLC, AI, RFC, IDE.", "Planning: AI tools summarize user stories, generate acceptance criteria, and draft architecture RFC templates.", "Authoring: IDE assistants (Cursor, GitHub Copilot) accelerate boilerplate generation, regex construction, and API client scaffolding.", "Code Review: Automated PR bots (Coderabbit, GitHub Copilot PR) detect linter issues, flag missed edge cases, and summarize changes."]}, {"id": "KP2", "description": "Testing Automation & Bug Hunting: Accelerates test suite synthesis and defect prevention.", "required": true, "acceptable_evidence": ["Technical keywords: SAST, CI, API, SAST scan summaries.", "Generates comprehensive unit and integration test suites, boundary condition mocks, and synthetic seed datasets.", "Identifies security vulnerabilities (SAST scan summaries) and dependency vulnerabilities early in CI pipelines.", "Automates documentation updates: syncs API docs (OpenAPI/Swagger) and markdown guides with code modifications."]}, {"id": "KP3", "description": "Quality Safeguards & Governance: Prevents bad code injection and maintains developer craftsmanship.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CD, PR, velocity metrics.", "Enforces strict human review: AI generates drafts, but senior engineers maintain final merge approval and accountability.", "Maintains mandatory CI/CD quality gates: automated tests, static analysis, and security scanners must pass regardless of author.", "Tracks developer velocity metrics (PR cycle time, deployment frequency) alongside defect escape rates to ensure genuine productivity."]}], "critical_failures": ["Advocates auto-merging unverified AI code directly to production without human review or CI test suites.", "Fails to identify concrete SDLC integration points beyond basic autocomplete."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'BROAD', 150, 'How can a QA engineer become a trusted contributor and proactively prevent issues rather than just identifying them?', '{"key_points": [{"id": "KP1", "description": "Shift-Left Testing & Requirements Engineering: Identifies defects before code is written.", "required": true, "acceptable_evidence": ["Technical keywords: BDD, Gherkin syntax, ADRs.", "Engages in early requirements and design grooming sessions to question ambiguities and define clear edge cases.", "Helps write concrete, testable Acceptance Criteria using Behavior-Driven Development (BDD / Gherkin syntax).", "Collaborates on Architecture Decision Records (ADRs) to ensure systems are architected for testability and observability."]}, {"id": "KP2", "description": "Automated Quality Gates & Test Infrastructure: Builds scalable automated testing frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: generators, CI/CD, API, CI.", "Authors robust end-to-end and API integration test frameworks (Playwright, Cypress, Pytest, Postman) embedded in CI/CD pipelines.", "Establishes automated non-functional testing: performance benchmarking (k6, Locust), security vulnerability scans, and chaos testing.", "Provides developers with ephemeral test environments and reliable synthetic test data generators."]}, {"id": "KP3", "description": "Culture, Root-Cause Prevention & Team Trust: Drives systemic engineering quality improvements.", "required": false, "acceptable_evidence": ["Technical keywords: RCA, MTTD, culture, cause.", "Conducts blameless root-cause analysis (RCA) on production incidents to identify process and test coverage gaps.", "Pairs with developers to help them write better unit tests rather than acting as an adversarial gatekeeper.", "Tracks quality telemetry: defect escape rate, mean time to detect (MTTD), and test pass reliability."]}], "critical_failures": ["Believes QA''s role is solely manual black-box testing after all development is complete.", "Acts as an adversarial blocker without contributing automated test infrastructure or early defect prevention."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you balance additional responsibilities while maintaining productivity?', '{"key_points": [{"id": "KP1", "description": "Time Blocking & Deep Work Protection: Guards uninterrupted focus blocks for complex engineering.", "required": true, "acceptable_evidence": ["Technical keywords: email, Slack replies, ticket triaging.", "Schedules dedicated 3-4 hour deep work calendar blocks for complex coding, architectural design, and debugging.", "Batches shallow tasks (email, Slack replies, ticket triaging) into designated morning and afternoon windows.", "Protects against context switching: declines non-essential meetings and requests written asynchronous agendas."]}, {"id": "KP2", "description": "Prioritization Frameworks & Bandwidth Negotiation: Focuses on highest-leverage deliverables.", "required": true, "acceptable_evidence": ["Technical keywords: Urgent, Important, frameworks, bandwidth.", "Applies Eisenhower Matrix (Urgent vs Important) to prioritize high-leverage architectural goals over reactive noise.", "Communicates bandwidth transparently with engineering managers to realign sprint commitments when taking on extra duties.", "Learns to say ''no'' or ''not right now'' diplomatically to scope additions that jeopardize core milestones."]}, {"id": "KP3", "description": "Automation, Delegation & Documentation: Multiplies efficiency through systemic leverage.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD.", "Automates repetitive manual tasks via shell scripts, CI/CD jobs, and automated runbooks.", "Authors comprehensive documentation and FAQs so teammates can self-serve rather than interrupting frequently.", "Delegates appropriate tasks to junior engineers as mentorship and growth opportunities."]}], "critical_failures": ["Takes on unlimited tasks silently until severe burnout, missed deadlines, or dropped responsibilities occur.", "Has no system for managing time or managing interruptions, resulting in zero deep work progress."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you balance engineering execution with business needs?', '{"key_points": [{"id": "KP1", "description": "Business Context & Value Alignment: Frames engineering investments in terms of business impact.", "required": true, "acceptable_evidence": ["Technical keywords: value alignment, vector index, refactoring vector index.", "Understands the core business drivers: revenue targets, customer churn, regulatory deadlines, time-to-market advantage.", "Translates technical investments (e.g. refactoring vector index) into business terms (reducing infrastructure spend by 40%, boosting customer retention).", "Recognizes that perfect software shipped too late to save the business is an engineering failure."]}, {"id": "KP2", "description": "Pragmatic Architecture & The 80/20 Rule: Ships high-quality MVP solutions under constraints.", "required": true, "acceptable_evidence": ["Technical keywords: MVP, pragmatic architecture, pragmatic, architecture.", "Applies Pareto principle: delivers 80% of customer value with 20% of engineering effort to validate market fit early.", "Builds modular architectures that can be quickly iterated or swapped without incurring massive rewrite penalties.", "Avoids premature optimization of edge cases that have minimal probability of impacting actual users."]}, {"id": "KP3", "description": "Managing Technical Debt with Product Leadership: Negotiates ongoing engineering health.", "required": false, "acceptable_evidence": ["Technical keywords: technical debt, managing, product, negotiates.", "Maintains a transparent technical debt backlog with clear risk ratings and business impact assessments.", "Negotiates dedicated sprint capacity (e.g., 20% of every sprint) for platform maintenance, testing, and debt remediation.", "Builds strong mutual trust with Product Managers through consistent delivery and transparent communication."]}], "critical_failures": ["Demands months of perfectionist architectural refactoring while ignoring critical business survival deadlines.", "Completely abandons all software engineering standards, producing unmaintainable spaghetti code that collapses immediately after launch."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you construct your gold evaluation dataset, and how did you ensure it covered real-world and edge-case scenarios?', '{"key_points": [{"id": "KP1", "description": "Data Sampling & Stratification: Sources representative queries from production distributions.", "required": true, "acceptable_evidence": ["Technical keywords: single-hop, multi-hop, sampling, stratification.", "Samples anonymized historical production logs, real customer support tickets, or authentic candidate resumes/JDs.", "Stratifies query distribution across domains, user personas, complexity tiers (single-hop vs multi-hop), and intent categories."]}, {"id": "KP2", "description": "Pairs queries with verified ground-truth reference texts, target metadata, and expected tool call sequences.", "required": true, "acceptable_evidence": ["Technical keywords: golden benchmark, ground-truth reference, target context chunks, expected tool calls, negative retrieval, RAGAS.", "Pairs queries with verified ground-truth reference texts, target metadata, and expected tool call sequences.", "Curates golden test cases containing user query, verified canonical response, target context chunks, and expected tool invocation parameters."]}, {"id": "KP3", "description": "Edge Case & Adversarial Scenario Engineering: Deliberately constructs challenging stress cases.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, PII, adversarial, scenario.", "Engineers edge cases: ambiguous phrasing, misspelled technical terms, out-of-vocabulary acronyms, and conflicting policy clauses.", "Includes adversarial tests: prompt injection attempts, toxic inputs, queries probing for unauthorized PII/salary data.", "Includes negative test queries: questions where no supporting document exists, requiring the system to gracefully decline."]}, {"id": "KP4", "description": "Curation, Tooling & Synthetic Augmentation: Uses LLM-in-the-loop generation with human expert audit.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, LLM, DeepEval, LangSmith.", "Augments dataset with synthetically generated question-answer pairs using frontier LLMs, audited and filtered by domain experts.", "Integrates with evaluation platforms (DeepEval, Ragas, LangSmith) to automate regression benchmarking in CI/CD pipelines.", "Maintains version control (Git LFS, DVC) over the evaluation dataset to track benchmark improvements over time."]}], "critical_failures": ["Uses only 5-10 trivial, manually typed happy-path questions to evaluate an entire production AI system.", "Fails to include negative test cases, adversarial tests, or edge cases in the evaluation dataset."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you create and maintain ground-truth evaluation datasets, and how were domain experts involved in that process?', '{"key_points": [{"id": "KP1", "description": "Domain Expert Annotation Workflow: Structures labeling with clear guidelines and tooling.", "required": true, "acceptable_evidence": ["Technical keywords: TalentScreen, medicaid compliance, domain, expert.", "Partners with subject matter experts (e.g. senior recruiters in TalentScreen, Medicaid compliance officers in healthcare).", "Authors comprehensive labeling guidelines defining acceptable answers, citation requirements, and grading criteria."]}, {"id": "KP2", "description": "Provides intuitive annotation interfaces (Label Studio, Prodigy, custom web forms) rather than asking experts to edit raw JSON.", "required": true, "acceptable_evidence": ["Technical keywords: Label Studio, Prodigy, annotation UI, inter-annotator agreement, Cohen''s kappa, factual accuracy scoring.", "Provides intuitive annotation interfaces (Label Studio, Prodigy, custom web forms) rather than asking experts to edit raw JSON.", "Deploys web-based annotation tooling (Label Studio, Prodigy) with structured rubric forms, allowing domain experts to score factual accuracy and citation quality easily."]}, {"id": "KP3", "description": "Inter-Annotator Agreement & Consensus Resolution: Measures consistency and resolves discrepancies.", "required": true, "acceptable_evidence": ["Technical keywords: Cohen''s Kappa, Fleiss'' Kappa, inter, annotator.", "Measures Inter-Annotator Agreement (Cohen''s Kappa, Fleiss'' Kappa) across multiple expert reviews on the same test cases.", "Holds adjudication sessions to resolve disagreements on ambiguous policy edge cases.", "Refines labeling rubrics based on consensus discussions to eliminate subjective ambiguity."]}, {"id": "KP4", "description": "Dataset Maintenance & Feedback Loop: Keeps ground truth fresh as policies evolve.", "required": false, "acceptable_evidence": ["Technical keywords: feedback loop, dataset, maintenance, feedback.", "Updates ground truth datasets when enterprise policies, hiring rubrics, or product specs change.", "Channels production human review escalations and thumbs-down feedback into candidate dataset reviews.", "Versions ground truth datasets alongside model release candidates to maintain historical benchmark comparability."]}], "critical_failures": ["Relies entirely on software engineers to invent ground-truth answers for specialized medical, legal, or recruitment domains.", "Has no methodology for measuring annotator agreement or updating evaluation datasets over time."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you decide this has to go to human review, in what condition or what basis?', '{"key_points": [{"id": "KP1", "description": "Confidence Thresholds & Ambiguity Gating: Escalates low-confidence or ambiguous classifications.", "required": true, "acceptable_evidence": ["Technical keywords: confidence, gating, escalates, classifications.", "Sets calibrated confidence score thresholds (e.g., if intent classification confidence < 0.80 or retrieval similarity score < 0.65, escalate).", "Triggers escalation when intent classification detects multiple conflicting user intents in a single prompt."]}, {"id": "KP2", "description": "Escalates when the retrieval system finds zero relevant chunks (negative retrieval detection).", "required": true, "acceptable_evidence": ["Technical keywords: confidence threshold, cosine similarity cutoff, negative retrieval, human-in-the-loop, risk intent classifier, escalation queue.", "Escalates when the retrieval system finds zero relevant chunks (negative retrieval detection).", "Implements confidence score thresholds on vector retrieval cosine similarity and triggers human-in-the-loop escalation when top similarity drops below 0.65."]}, {"id": "KP3", "description": "High-Stakes Actions & Policy Guardrails: Mandates human sign-off on irreversible or regulated decisions.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, policy guardrails, refunds above threshold, human-in-the-loop.", "Enforces mandatory Human-in-the-Loop review for irreversible financial actions (refunds above threshold, claim denials).", "Routes sensitive medical/clinical diagnoses or high-risk legal decisions to certified human professionals.", "Triggers review upon detecting prompt injection, toxic user input, or repeated customer frustration sentiment."]}, {"id": "KP4", "description": "Escalation Handoff & Context Packaging: Provides human reviewers with comprehensive context.", "required": false, "acceptable_evidence": ["Technical keywords: UI, handoff, context, packaging.", "Packages conversational history, customer profile, retrieved source documents, and agent reasoning traces into the human queue.", "Provides human operators with one-click approval, modification, or rejection buttons in Zendesk/Slack/custom UI.", "Feeds human corrections back into the evaluation dataset to continuously improve autonomous accuracy."]}], "critical_failures": ["Allows an AI agent to execute high-stakes, irreversible financial or medical actions without human review.", "Fails to establish any confidence scoring or threshold gating to trigger human escalation."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you define the baseline?', '{"key_points": [{"id": "KP1", "description": "Baseline Selection & Heuristic Anchoring: Establishes a simple, reproducible comparison benchmark.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, BM25, AI, review metrics.", "Selects a deterministic baseline: existing manual review metrics, legacy regex/rule-based systems, or standard BM25 keyword search.", "Uses a simple zero-shot off-the-shelf model without RAG as a foundational generative baseline.", "Defines the baseline on the exact same golden test dataset used to evaluate the new AI system."]}, {"id": "KP2", "description": "Metric Quantification & Baseline Performance: Measures baseline across accuracy, latency, and cost.", "required": true, "acceptable_evidence": ["Technical keywords: MRR, precision, baseline retrieval, turnaround latency.", "Quantifies baseline retrieval metrics: Hit Rate@K, Mean Reciprocal Rank (MRR), and precision.", "Quantifies baseline operational metrics: human handle time (e.g. 35 mins/case), processing cost, and turnaround latency.", "Establishes a quantitative hurdle rate (e.g., new RAG system must exceed baseline Hit Rate by at least 15% to justify deployment)."]}, {"id": "KP3", "description": "Incremental Progression & Value Justification: Demonstrates value added over the baseline.", "required": false, "acceptable_evidence": ["Technical keywords: incremental, progression, RAG, BM25.", "Tracks ablation improvements: Baseline -> BM25 + Dense Hybrid -> Hybrid + Reranker -> Full Agentic RAG.", "Justifies infrastructure complexity and GPU hosting cost against measurable gains over the simple baseline.", "Prevents premature optimization by verifying whether basic keyword or heuristic approaches suffice for certain query subsets."]}], "critical_failures": ["Builds complex AI architectures without measuring against any baseline, unable to prove whether the model improved over simple keyword search.", "Evaluates the new system and baseline on different, non-comparable datasets."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you make sure that the data flow was flowing correctly? What were the steps? How did you understand that data flow was moving through the application to get the final results?', '{"key_points": [{"id": "KP1", "description": "Distributed Tracing & Correlation Propagation: Traces data flow across microservice hops.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, correlation_id, trace_id.", "Injects unique `correlation_id` / `trace_id` headers at the API Gateway and propagates them across all microservice requests.", "Instruments services with OpenTelemetry / Langfuse to record span entry/exit, arguments, payloads, and timestamps."]}, {"id": "KP2", "description": "Traces end-to-end journey: HTTP request -> API Gateway -> Triage Agent -> Milvus Vector Search -> LLM Generation -> Output Guardrail.", "required": true, "acceptable_evidence": ["Technical keywords: pipeline tracing, OpenTelemetry spans, API Gateway, vector retrieval, LLM synthesis, output guardrail, payload validation.", "Traces end-to-end journey: HTTP request -> API Gateway -> Triage Agent -> Milvus Vector Search -> LLM Generation -> Output Guardrail.", "Traces data payloads through each pipeline stage: API Gateway -> Authentication -> Router Agent -> Vector Retrieval -> LLM -> Guardrail Validator with OpenTelemetry spans."]}, {"id": "KP3", "description": "State Inspection & Inter-Stage Assertion Testing: Verifies data transformations between nodes.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, data schema, synthetic payloads, intermediate state.", "Asserts data schema validity at stage boundaries using Pydantic models (verifying chunk counts, metadata structure, token limits).", "Runs automated integration tests injecting known synthetic payloads and asserting expected intermediate state mutations."]}, {"id": "KP4", "description": "Logs state deltas before and after every LangGraph node execution for point-in-time state inspection.", "required": false, "acceptable_evidence": ["Technical keywords: LangGraph MemorySaver, checkpointer snapshot, state delta, channel reducers, point-in-time state inspection.", "Logs state deltas before and after every LangGraph node execution for point-in-time state inspection.", "Employs LangGraph MemorySaver checkpointers and state snapshot diffing to inspect channel updates and debug node failures during execution."]}, {"id": "KP5", "description": "Synthetic Canary Probing & Anomaly Detection: Detects data stalls and silent drops in production.", "required": false, "acceptable_evidence": ["Technical keywords: Datadog, CloudWatch, DLQs.", "Deploys automated synthetic canary queries executing end-to-end every 5 minutes to verify data flow liveness.", "Monitors dead letter queues (DLQs) and alerts on message count accumulation between pipeline stages.", "Visualizes trace DAGs and identifies data drop-offs or bottleneck stages using CloudWatch / Datadog trace maps."]}], "critical_failures": ["Relies solely on final HTTP 200 status codes without verifying intermediate data integrity or payload correctness.", "Has no correlation IDs or distributed tracing across service boundaries, making pipeline debugging impossible."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How did you manage and store conversation history, and why is it important for contextual responses?', '{"key_points": [{"id": "KP1", "description": "Storage Architecture & State Modeling: Implements persistent storage for conversational turns.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, Redis, session_id, user_id.", "Persists conversation turns in Amazon RDS PostgreSQL or Redis partitioned by `session_id` and `user_id`.", "Models messages using typed schemas with explicit roles (`system`, `user`, `assistant`, `tool`) and metadata timestamps."]}, {"id": "KP2", "description": "Implement LangGraph checkpointers to persist conversation state graphs across asynchronous turns.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph checkpointer, PostgresSaver, RedisSaver, state persistence, sliding window context, message trimming.", "Implements LangGraph checkpointers to persist conversation state graphs across asynchronous turns.", "Configures LangGraph PostgresSaver or Redis checkpointers to persist cyclic graph state, messages list, and intermediate variables across user turns."]}, {"id": "KP3", "description": "Context Window Management & Summarization: Prevents context overflow and attention dilution.", "required": true, "acceptable_evidence": ["Technical keywords: context window, sliding window, LLM, prompt tokens.", "Implements sliding window buffering: retains last k turns (e.g. 5-10 turns) in raw verbatim text.", "Applies recursive LLM summarization on older conversational history to condense facts into a compact context summary.", "Enforces strict token budgeting, calculating total prompt tokens before invoking generation models."]}, {"id": "KP4", "description": "Coreference Resolution & Multi-Turn Coherence: Resolves pronouns and maintains intent across turns.", "required": false, "acceptable_evidence": ["Technical keywords: PII redaction, TTL, PII.", "Performs query reformulation / coreference resolution (e.g., rewriting ''What are its benefits?'' to ''What are the benefits of Medicare Advantage?'').", "Filters out obsolete or corrected facts to prevent stale context from confusing downstream model reasoning.", "Applies session TTL and PII redaction to protect user privacy in stored conversation logs."]}], "critical_failures": ["Passes infinite raw conversation history into the model until context window limit crashes the application.", "Treats every turn as an isolated query without maintaining any session state or conversation history."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'How did you manage metadata and ensure its consistency across different components of your system?', '{"key_points": [{"id": "KP1", "description": "Canonical Metadata Modeling: Enforces a single source of truth and strongly-typed schemas.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, Milvus, PostgreSQL, doc_id.", "Defines canonical metadata schemas using Pydantic or Protobuf (e.g. `doc_id`, `version`, `author`, `tenant_id`, `page_number`, `permissions`).", "Maintains a single source of truth in a relational database (PostgreSQL) for all primary document and entity metadata.", "Attaches normalized metadata payloads to vector embeddings in Milvus during ingestion for pre-filtering."]}, {"id": "KP2", "description": "Cross-Store Synchronization & Consistency: Syncs metadata updates across relational and vector stores.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, outbox pattern, CDC, Milvus.", "Implements Change Data Capture (CDC) with Debezium or transactional outbox pattern to propagate metadata updates asynchronously.", "Coordinates dual-writes using distributed transactions or idempotent retry queues when updating PostgreSQL and Milvus.", "Manages document versioning so outdated chunks are purged or marked inactive when metadata changes."]}, {"id": "KP3", "description": "Validation, Auditing & Reconciliation: Enforces consistency across distributed components.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, CI/CD, CI, CD.", "Runs automated periodic reconciliation jobs comparing document IDs and checksums in PostgreSQL vs Milvus.", "Validates metadata integrity during CI/CD ingestion tests (ensuring no orphaned chunks or missing required fields).", "Invalidates Redis metadata cache entries immediately upon updates to prevent stale reads."]}], "critical_failures": ["Allows vector database metadata and relational database metadata to diverge with no synchronization mechanism.", "Lacks any schema definition or validation, allowing arbitrary inconsistent metadata fields to corrupt retrieval filtering."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you manage rate limiting, timeouts, and system reliability in your application?', '{"key_points": [{"id": "KP1", "description": "Rate Limiting & Token Bucket Algorithms: Controls request velocity and quota consumption.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, token bucket, Redis, API.", "Implements token-bucket or leaky-bucket rate limiting in Redis / API Gateway to protect upstream APIs and manage external provider quotas.", "Enforces user-tier rate limits (requests per minute and tokens per minute) to prevent tenant monopolization."]}, {"id": "KP2", "description": "Handle HTTP 429 Too Many Requests responses gracefully by respecting `Retry-After` headers.", "required": true, "acceptable_evidence": ["Technical keywords: HTTP 429, Retry-After header, exponential backoff, jitter, tenacity library, Redis token bucket, circuit breaker.", "Handles HTTP 429 Too Many Requests responses gracefully by respecting `Retry-After` headers.", "Parses HTTP 429 Retry-After headers from LLM provider APIs and implements exponential backoff with jitter using the Python tenacity library."]}, {"id": "KP3", "description": "Timeouts, Exponential Backoff & Jitter: Prevents thundering herds and cascading failures.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, LLM, DB.", "Configures strict timeouts on external LLM and vector DB calls to prevent worker thread hang.", "Applies exponential backoff with full jitter on transient network failures (5xx, timeouts) using tenacity/backoff libraries.", "Limits maximum retry attempts (e.g. 3 retries) before falling back to alternative paths."]}, {"id": "KP4", "description": "Circuit Breakers & Graceful Degradation: Protects system health during provider outages.", "required": false, "acceptable_evidence": ["Technical keywords: circuit breaker, GPT, SLM.", "Deploys circuit breaker pattern (opens circuit after consecutive failures, fast-failing downstream requests).", "Implements automatic fallback model routing (e.g. falling back from primary Claude 3.5 Sonnet to GPT-4o or local SLM during outage).", "Provides graceful degradation responses to users with informative messaging rather than raw system error traces."]}], "critical_failures": ["Performs unbounded tight-loop retries without backoff or jitter upon receiving 429 or 500 errors, worsening outages.", "Has no timeouts configured, allowing slow or hung third-party API calls to exhaust server worker threads."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How did you monitor and maintain your AI system in production?', '{"key_points": [{"id": "KP1", "description": "Operational Telemetry & Performance Monitoring: Tracks latency, errors, and cost.", "required": true, "acceptable_evidence": ["Technical keywords: Datadog, SLA, p95, p99.", "Monitors system health via CloudWatch / Datadog: p50/p95/p99 latency, 4xx/5xx HTTP error rates, CPU/memory usage.", "Tracks LLM token consumption, prompt/completion breakdown, and infrastructure spend in real time.", "Sets up alerting thresholds for error budget burn and latency SLA violations."]}, {"id": "KP2", "description": "Quality Observability, Drift & Evaluation: Tracks semantic accuracy and hallucination rates.", "required": true, "acceptable_evidence": ["Technical keywords: data drift, LangSmith, DeepEval, AI.", "Instruments traces via Langfuse / LangSmith to monitor prompt versions, retrieval chunks, and generation outputs.", "Runs continuous online evaluation: measuring Faithfulness, Answer Relevancy, and Hallucination metrics (DeepEval).", "Monitors for data drift and retrieval quality degradation (Evidently AI) as user query distributions evolve."]}, {"id": "KP3", "description": "Continuous Improvement & Feedback Flywheel: Maintains system quality over time.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, thumbs up, down, user edits.", "Captures explicit user feedback (thumbs up/down, user edits) and human-in-the-loop escalation logs.", "Curates failed production queries into updated golden evaluation test suites for regression testing.", "Automates periodic re-indexing of documents and retraining of intent classifiers/rerankers."]}], "critical_failures": ["Monitors only standard server CPU while completely ignoring AI quality metrics, hallucinations, and token spend.", "Has no feedback loop to capture production failures or update evaluation datasets."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How did you process structured data like tables during document ingestion without losing context?', '{"key_points": [{"id": "KP1", "description": "Layout-Aware Parsing & Table Boundary Extraction: Extracts tabular structure cleanly.", "required": true, "acceptable_evidence": ["Technical keywords: OCR, Docling, PyMuPDF, Camelot.", "Uses advanced layout-aware parsers (Docling, Unstructured, PyMuPDF, Camelot/Tabula) to isolate table bounding boxes and grid cells.", "Avoids naive OCR or whitespace text flattening that merges adjacent columns and scrambles headers.", "Detects complex tabular structures: multi-row headers, merged cells, and multi-page spanning tables."]}, {"id": "KP2", "description": "Context-Preserving Serialization & Chunking: Formats tables into semantic representations.", "required": true, "acceptable_evidence": ["Technical keywords: HTML, preserving serialization, `<table>`, In Year 2023.", "Serializes extracted tables into Markdown tables or structured HTML (`<table>`) preserving header-to-value relationships.", "Generates natural language row summaries (e.g. ''In Year 2023, Product X achieved Revenue $50M'') to enhance semantic embedding matching.", "Prefixes each table chunk with document title, section heading, and table caption to maintain semantic context."]}, {"id": "KP3", "description": "Dual Representation & Hybrid Retrieval: Indexes tables for semantic and exact lookup.", "required": false, "acceptable_evidence": ["Technical keywords: dense embeddings, BM25, Milvus, system prompt.", "Indexes natural language summary in vector database (Milvus) while preserving raw JSON/tabular data in document store.", "Employs hybrid retrieval (BM25 for exact column/cell keyword matching + dense embeddings for concept matching).", "Formats retrieved tables cleanly into the LLM system prompt context with Markdown formatting instructions."]}], "critical_failures": ["Flattens tables into raw unformatted text lines, completely destroying column relationships and row alignments.", "Splits tables across arbitrary token chunk boundaries, separating table headers from corresponding data rows."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you set up logging and alerting for production systems?', '{"key_points": [{"id": "KP1", "description": "Structured Logging & Context Enrichment: Authors standardized, machine-readable logs.", "required": true, "acceptable_evidence": ["Technical keywords: correlation ID, trace_id, user_id, duration_ms.", "Emits logs in structured JSON format with standardized fields (`timestamp`, `level`, `service`, `trace_id`, `user_id`, `duration_ms`).", "Injects distributed trace context (correlation ID) to enable tracing across microservices.", "Enforces strict data hygiene: automatically redacts PII and sanitizes credentials before writing to log streams."]}, {"id": "KP2", "description": "Log Aggregation, Indexing & Querying: Ships logs to centralized search infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: Datadog, S3, FluentBit, AWS.", "Aggregates logs via FluentBit / AWS CloudWatch Agent into centralized stores (CloudWatch Logs, OpenSearch/Elasticsearch, Datadog).", "Defines log retention policies and lifecycle transitions to S3 Glacier for cost optimization and compliance.", "Uses CloudWatch Logs Insights / Kibana queries for fast ad-hoc debugging and log aggregation."]}, {"id": "KP3", "description": "Tiered Alerting, SLOs & Alert Fatigue Prevention: Calibrates actionable, noise-free alarms.", "required": false, "acceptable_evidence": ["Technical keywords: PagerDuty, MTTR, alert payloads, SLOs.", "Implements multi-window burn rate alerts on Service Level Objectives (SLOs) rather than noisy point-in-time CPU thresholds.", "Configures severity tiers: P1 (urgent on-call pager in PagerDuty) vs P3 (Slack channel notification/Jira ticket).", "Links actionable runbook URLs directly inside alert payloads to accelerate mean time to resolve (MTTR)."]}], "critical_failures": ["Uses unstructured console `print()` statements without timestamps, correlation IDs, or error levels.", "Fails to establish alerting tiers, causing either severe alert fatigue or missing critical production outages."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you use tools like Microsoft Presidio to identify and mask sensitive data?', '{"key_points": [{"id": "KP1", "description": "Presidio Analyzer Engine & Entity Detection: Configures detection pipelines across entity types.", "required": true, "acceptable_evidence": ["Technical keywords: AnalyzerEngine, NER, PERSON, PatternRecognizer.", "Uses `AnalyzerEngine` combining regex patterns, checksum validators (Luhn), and spaCy/Transformers NER models.", "Detects standard entities: US_SSN, CREDIT_CARD, PHONE_NUMBER, EMAIL_ADDRESS, LOCATION, PERSON.", "Builds `PatternRecognizer` extensions with custom regular expressions and context words for domain identifiers (e.g. Member ID, Employee ID)."]}, {"id": "KP2", "description": "Presidio Anonymizer Engine & Transformation Operators: Applies appropriate redaction operators.", "required": true, "acceptable_evidence": ["Technical keywords: AnonymizerEngine, OperatorConfig, SHA-256, `OperatorConfig`.", "Uses `AnonymizerEngine` with operator configurations (`OperatorConfig`) to apply targeted transformations.", "Applies transformation types: `replace` (with entity label `<PHONE_NUMBER>`), `redact` (remove), `hash` (SHA-256 for consistent linkage), or `mask` (e.g. `****1234`).", "Maintains deanonymization lookup vaults if downstream workflows require re-identifying records safely."]}, {"id": "KP3", "description": "Pipeline Placement, Performance & Latency Optimization: Integrates Presidio into production pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, precision, recall, en_core_web_sm.", "Executes Presidio at the ingestion boundary before embedding generation in Milvus and before sending prompts to external LLMs.", "Optimizes latency: uses lightweight NER models (en_core_web_sm) or caches analyzer instances to avoid reload overhead.", "Evaluates detection accuracy (Precision/Recall) against domain-specific sensitive validation datasets."]}], "critical_failures": ["Does not know what Microsoft Presidio is or cannot explain the roles of AnalyzerEngine and AnonymizerEngine.", "Believes Presidio is solely an LLM prompt rather than a dedicated Python/NLP detection framework."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How did your system ensure accurate and contextually relevant answers when users queried complex technical manuals?', '{"key_points": [{"id": "KP1", "description": "Hierarchical Parsing & Structure-Aware Chunking: Preserves technical document hierarchy.", "required": true, "acceptable_evidence": ["Technical keywords: aware chunking, Docling, PyMuPDF.", "Parses technical manuals using layout-aware tools (Docling, PyMuPDF) to extract chapter headings, subsections, diagrams, and code snippets.", "Applies hierarchical chunking: bounds chunks by logical section headings rather than arbitrary character splits."]}, {"id": "KP2", "description": "Prepends breadcrumb metadata (e.g., `Manual > Chapter 3: Calibration > Section 3.2`) to every chunk payload.", "required": true, "acceptable_evidence": ["Technical keywords: document breadcrumbs, hierarchical chunking, parent-document retriever, markdown table preservation, semantic density.", "Prepends breadcrumb metadata (e.g., `Manual > Chapter 3: Calibration > Section 3.2`) to every chunk payload.", "Prepends document breadcrumbs (Manual > Chapter 3 > Section 3.2) and table headers to each chunk payload before generating embeddings."]}, {"id": "KP3", "description": "Hybrid Retrieval & Cross-Encoder Reranking: Handles domain jargon and exact part numbers.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, Reciprocal Rank Fusion, RRF, cross-encoder reranking.", "Combines BM25 keyword search (essential for exact model numbers, error codes, part IDs) with dense vector search (Milvus HNSW).", "Fuses results using Reciprocal Rank Fusion (RRF) and passes top-k candidates to a Cross-Encoder reranker (BGE-Reranker-Large).", "Filters out irrelevant or out-of-context chunks to prevent distracting the generation model."]}, {"id": "KP4", "description": "Grounded Generation & Citation Traceability: Enforces strict adherence to technical context.", "required": false, "acceptable_evidence": ["Technical keywords: DeepEval, grounded, generation, citation.", "Constrains generation with strict prompt instructions: answers must be derived solely from provided context, admitting unknowns explicitly.", "Requires inline citations citing exact page number and section heading for every procedural instruction.", "Measures generation faithfulness and hallucination rate using automated evaluation frameworks (DeepEval)."]}], "critical_failures": ["Performs naive fixed-size chunking across technical manuals, tearing procedures and diagrams in half.", "Relies on pure semantic vector search without BM25, causing exact part numbers, model IDs, and error codes to be missed."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did your system support citations, and how was metadata managed for traceability?', '{"key_points": [{"id": "KP1", "description": "Metadata Capture & Chunk Attribution: Binds granular document coordinates to chunks during ingestion.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, doc_id, page_number, section_title.", "Attaches immutable source coordinates to each chunk in Milvus: `doc_id`, `title`, `page_number`, `section_title`, `chunk_id`.", "Maintains character start/end offsets pointing back to the original document text for exact visual highlighting."]}, {"id": "KP2", "description": "Formats retrieved chunks into the prompt context with explicit index tags (e.g. `[Document 1: Page 14]`).", "required": true, "acceptable_evidence": ["Technical keywords: inline citation, prompt indexing, chunk provenance, doc_id metadata, page_number, citation object schema.", "Formats retrieved chunks into the prompt context with explicit index tags (e.g. `[Document 1: Page 14]`).", "Injects numbered citation tokens [Doc-1: Page 12] into retrieved prompt passages and constrains the LLM system prompt to cite sources inline."]}, {"id": "KP3", "description": "Citation Generation & Prompt Constraints: Enforces explicit citation syntax in model output.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, system prompt, citation_ids, JSON.", "Instructs model in system prompt to ground every factual assertion with inline citation bracket tags (`[1]`, `[Doc p. 12]`).", "Requires structured output formats (JSON/Pydantic) returning answer text alongside an array of referenced `citation_ids`.", "Instructs model to explicitly state when context is insufficient to answer rather than inventing citations."]}, {"id": "KP4", "description": "Post-Generation Validation & Interactive UX: Verifies citation veracity and powers UI links.", "required": false, "acceptable_evidence": ["Technical keywords: precision, recall, UX, UI.", "Executes programmatic post-validation: checks that all emitted citation IDs actually exist in retrieved context chunks.", "Measures citation precision and recall using evaluation benchmarks (DeepEval Faithfulness).", "Powers frontend UX: renders clickable citation badges that open the source PDF directly to the referenced page and highlight text."]}], "critical_failures": ["Generates hallucinated citation links that point to non-existent documents or incorrect page numbers.", "Fails to store document metadata (page numbers, document IDs) during ingestion, making citation tracking impossible."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do snapshots ensure immutability of previous states when files and folders are modified after a snapshot is created?', '{"key_points": [{"id": "KP1", "description": "Pointer-Based Snapshot Mechanics: Explains point-in-time metadata pointer preservation.", "required": true, "acceptable_evidence": ["Technical keywords: pointer, based, snapshot, mechanics.", "Explains that snapshots do not copy all physical data instantaneously; they freeze an index of block pointers at a specific point in time.", "The snapshot is a read-only metadata mapping referencing existing data blocks on disk."]}, {"id": "KP2", "description": "Instantaneous creation: snapshot creation takes seconds regardless of volume size because only metadata pointers are frozen.", "required": true, "acceptable_evidence": ["Technical keywords: Copy-on-Write, Redirect-on-Write, metadata pointer freeze, block-level delta, storage immutability, EBS snapshot.", "Instantaneous creation: snapshot creation takes seconds regardless of volume size because only metadata pointers are frozen.", "Freezes filesystem metadata pointers using Copy-on-Write (CoW) or Redirect-on-Write (RoW) algorithms rather than duplicating raw data blocks."]}, {"id": "KP3", "description": "Copy-on-Write (CoW) vs Redirect-on-Write (RoW): Explains mutation handling after snapshot creation.", "required": true, "acceptable_evidence": ["Technical keywords: historical state, CoW, RoW, immutability.", "Copy-on-Write (CoW): when a block is modified post-snapshot, original data block is copied to snapshot storage before new data overwrites it.", "Redirect-on-Write (RoW): when a block is modified, new data is written to a newly allocated block and active volume pointer updates, while snapshot retains pointer to original unchanged block.", "Proves immutability: the snapshot''s block pointers never point to modified blocks, ensuring historical state remains unchanged."]}, {"id": "KP4", "description": "Storage Efficiency, Deletion & Cloud Storage Implementation: Details practical storage lifecycle.", "required": false, "acceptable_evidence": ["Technical keywords: reference counting, S3, AWS, EBS.", "Differential storage: subsequent snapshots only consume space for changed blocks (delta blocks), maximizing storage efficiency.", "Block reference counting: physical blocks are only reclaimed for deletion when both active filesystem and all snapshots release references.", "Relates mechanics to cloud storage: AWS EBS snapshots (backed by S3 incremental block tracking) and ZFS/Btrfs copy-on-write filesystems."]}], "critical_failures": ["Believes creating a snapshot requires copying all multi-terabyte files in full to a new directory immediately.", "Cannot explain either Copy-on-Write or Redirect-on-Write mechanisms for preserving unmodified blocks."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you approach cost optimization and model selection when building AI-powered systems?', '{"key_points": [{"id": "KP1", "description": "Tiered Model Routing & Task Matching: Matches model capability to task complexity.", "required": true, "acceptable_evidence": ["Technical keywords: GPT, Claude 3.5 Haiku, GPT-4o-mini, Llama 3 8B.", "Employs dynamic model routing: routes simple classification, extraction, and intent triage to lightweight models (Claude 3.5 Haiku, GPT-4o-mini, Llama 3 8B).", "Reserves expensive frontier models (GPT-4o, Claude 3.5 Sonnet) exclusively for complex multi-hop reasoning, code synthesis, or nuanced synthesis."]}, {"id": "KP2", "description": "Use distilled, fine-tuned Small Language Models (SLMs) for repetitive domain tasks to reduce per-call inference costs by up to 90%.", "required": true, "acceptable_evidence": ["Technical keywords: Small Language Models, SLM routing, Llama 3 8B, prompt caching, Redis semantic cache, inference unit economics.", "Uses distilled, fine-tuned Small Language Models (SLMs) for repetitive domain tasks to reduce per-call inference costs by up to 90%.", "Routes narrow tasks (classification, entity extraction) to distilled Small Language Models (Llama 3 8B, Phi-3) while reserving Claude 3.5 Sonnet for complex reasoning."]}, {"id": "KP3", "description": "Prompt Caching & Context Compression: Minimizes token consumption per call.", "required": true, "acceptable_evidence": ["Technical keywords: prompt caching, Redis, LLM, minimizes token.", "Leverages Prompt Caching (Anthropic/OpenAI prompt cache) on large static system instructions and few-shot examples (cutting input token costs by up to 90%).", "Applies context compression and pruning: trims whitespace, removes redundant chunks, and summarizes historical dialogue.", "Caches frequent query responses and vector embeddings in Redis to eliminate redundant LLM invocations."]}, {"id": "KP4", "description": "Financial Governance & Unit Economics: Monitors token spend and sets hard limits.", "required": false, "acceptable_evidence": ["Technical keywords: vLLM, unit economics, max_tokens, API.", "Enforces strict `max_tokens` limits on completions and sets hard monthly billing quotas at API Gateway / provider level.", "Tracks unit economics: cost per user session, cost per query, and gross margin impact across production traffic.", "Evaluates self-hosted open-source models (vLLM on reserved instances) vs pay-per-token APIs as query volume scales."]}], "critical_failures": ["Routes all trivial queries (e.g. basic greetings or regex extractions) directly to the most expensive frontier model.", "Has no token monitoring, prompt caching, or cost tracking in place."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you approach problem-solving when faced with unfamiliar or complex challenges?', '{"key_points": [{"id": "KP1", "description": "Problem Decomposition & First Principles: Breaks complex unknowns into manageable primitives.", "required": true, "acceptable_evidence": ["Technical keywords: problem, decomposition, breaks, complex.", "Deconstructs unfamiliar monolithic problems into fundamental technical components and core assumptions.", "Separates verified known facts from unverified assumptions through rigorous questioning."]}, {"id": "KP2", "description": "Consults primary technical sources: RFC specifications, source code repositories, research papers, and official documentation.", "required": true, "acceptable_evidence": ["Technical keywords: RFC specifications, source code inspection, minimal reproducible script, scientific debugging, hypothesis testing.", "Consults primary technical sources: RFC specifications, source code repositories, research papers, and official documentation.", "Reads underlying open-source library source code, GitHub issues, and official RFC specifications rather than relying solely on superficial forum posts."]}, {"id": "KP3", "description": "Rapid Prototyping & Technical Spikes: Tests hypotheses through controlled experiments.", "required": true, "acceptable_evidence": ["Technical keywords: rapid, prototyping, spikes, tests.", "Builds minimal standalone reproduction scripts or isolated technical spikes to test specific hypotheses.", "Profiles performance and behavior using debuggers, profilers, and distributed trace logs.", "Iterates rapidly, using negative experimental results to eliminate unproductive architectural paths."]}, {"id": "KP4", "description": "Knowledge Codification & Peer Collaboration: Documents findings and seeks specialized input.", "required": false, "acceptable_evidence": ["Technical keywords: calm persistence, ADRs, knowledge, codification.", "Reaches out to domain experts or peers with well-framed, context-rich questions after conducting initial research.", "Documents discoveries in Architecture Decision Records (ADRs) or technical wikis to prevent team re-work.", "Demonstrates intellectual humility, calm persistence, and adaptability when initial approaches fail."]}], "critical_failures": ["Freezes or becomes completely paralyzed when encountering an unfamiliar technology or problem.", "Applies random trial-and-error changes blindly without decomposing the problem or formulating hypotheses."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you approach solving production issues or handling errors in a live system?', '{"key_points": [{"id": "KP1", "description": "Incident Triage & Blast Radius Mitigation: Prioritizes immediate service stabilization.", "required": true, "acceptable_evidence": ["Technical keywords: feature flags, incident, blast, radius.", "Prioritizes immediate user impact mitigation over prolonged debugging during an active outage.", "Executes fast rollback of recent deployments or disables offending features via feature flags.", "Redirects traffic via load balancers, engages circuit breakers, or scales up compute capacity to absorb load."]}, {"id": "KP2", "description": "Disciplined Root Cause Isolation: Traces failures using telemetry and logs.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, correlation ID, CloudWatch, ELK.", "Examines distributed traces (OpenTelemetry/Langfuse) and centralized logs (CloudWatch/ELK) filtered by correlation ID.", "Reconstructs failure timeline: correlating deployment events, metric spikes, error logs, and downstream provider alerts.", "Isolates the root cause (e.g. database connection leak, memory exhaustion, schema mismatch, unhandled API 429)."]}, {"id": "KP3", "description": "Blameless Post-Mortem & Preventative Remediation: Drives lasting systemic improvements.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, blameless, mortem, preventative.", "Conducts a blameless post-mortem analyzing systemic vulnerabilities and timeline events rather than human fault.", "Authors actionable remediation items: adding regression tests, improving automated canary rollback, and tuning alerts.", "Shares incident findings transparently with the broader engineering team to elevate collective operational resilience."]}], "critical_failures": ["Attempts to live-debug and test experimental code patches directly in production during a live outage instead of mitigating impact.", "Treats post-incident reviews as punitive blame sessions without implementing automated regression safeguards."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you categorize your metrics into online and offline metrics?', '{"key_points": [{"id": "KP1", "description": "Offline Metrics Categorization & Purpose: Details pre-deployment benchmark metrics.", "required": true, "acceptable_evidence": ["Technical keywords: MRR, NDCG, precision, DeepEval.", "Defines offline metrics: evaluated in controlled testing environments on static golden test datasets prior to deployment.", "Information Retrieval metrics: Hit Rate@K, Mean Reciprocal Rank (MRR), Normalized Discounted Cumulative Gain (NDCG).", "Generative Quality metrics: Faithfulness, Answer Relevancy, Context Precision, Hallucination Score (via DeepEval / Ragas)."]}, {"id": "KP2", "description": "Online Metrics Categorization & Purpose: Details post-deployment production telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: p95, p99, CTR, FCR.", "Defines online metrics: evaluated in live production serving real user traffic with non-deterministic queries.", "Business & User metrics: Click-Through Rate (CTR), Conversion Rate, Task Completion Time, First Contact Resolution (FCR), User Thumbs Up/Down.", "Operational & System metrics: p95/p99 inference latency, token consumption per request, HTTP 5xx error rate, cache hit ratio."]}, {"id": "KP3", "description": "Offline-to-Online Correlation & Drift Management: Connects benchmark gains to live user outcomes.", "required": false, "acceptable_evidence": ["Technical keywords: data drift, concept drift, PSI, KS.", "Analyzes discrepancies where high offline benchmark scores fail to translate into online user satisfaction.", "Monitors data drift and concept drift (KS-test, PSI) to detect when offline datasets no longer match production distributions.", "Uses online user feedback and failed interactions to update and expand offline golden test datasets."]}], "critical_failures": ["Conflates offline metrics with online metrics (e.g. claiming Hit Rate is an online production telemetry metric).", "Cannot name specific metrics for either offline or online AI system evaluation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you cluster users and generate recommendations based on their preferences and behavior?', '{"key_points": [{"id": "KP1", "description": "User Feature Representation & Embedding: Encodes user behavior into mathematical feature vectors.", "required": true, "acceptable_evidence": ["Technical keywords: StandardScaler, MinMaxScaler, SVD, ALS.", "Constructs feature vectors: explicit preferences (tags, categories) and implicit behavioral signals (clicks, watch time, purchase history).", "Normalizes and scales features using StandardScaler / MinMaxScaler, handling sparse interaction matrices.", "Generates dense user embeddings using matrix factorization (SVD/ALS) or two-tower neural network embeddings."]}, {"id": "KP2", "description": "Clustering Methodology & Persona Profiling: Groups users using unsupervised algorithms.", "required": true, "acceptable_evidence": ["Technical keywords: profiles cluster, erratic cluster, Elbow method, power users.", "Applies clustering algorithms: K-Means (with k determined by Silhouette Score/Elbow method) or HDBSCAN for density clustering.", "Profiles cluster centroids to discover actionable persona segments (e.g. power users, price-sensitive shoppers, casual browsers).", "Evaluates cluster separation and stability across time intervals to prevent erratic cluster hopping."]}, {"id": "KP3", "description": "Recommendation Generation & Cold-Start Strategy: Generates recommendations from cluster patterns.", "required": false, "acceptable_evidence": ["Technical keywords: cluster popular items, recommendation, generation, start.", "Generates collaborative recommendations: recommends top-performing items consumed by a user''s cluster peers.", "Handles cold-start users: assigns new users to clusters based on onboarding demographic tags until behavioral data accumulates.", "Balances exploitation (cluster popular items) with exploration to prevent filter bubbles and maintain recommendation diversity."]}], "critical_failures": ["Applies clustering without scaling features or normalizing user interaction counts.", "Cannot explain how user clusters are translated into concrete item recommendations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you communicate complex technical ideas clearly and effectively during discussions or presentations?', '{"key_points": [{"id": "KP1", "description": "Audience Calibration & Abstraction Layering: Calibrates detail to listener technical background.", "required": true, "acceptable_evidence": ["Technical keywords: ROI, API, BLUF.", "Adapts depth: presents business ROI, cost, and timelines to executives; presents API contracts, edge cases, and failure modes to engineers.", "Avoids unnecessary acronyms and jargon when presenting to non-technical stakeholders.", "Uses the ''Bottom-Line Up Front'' (BLUF) principle: states core recommendations and impact before diving into technical mechanics."]}, {"id": "KP2", "description": "Visual Architecture & Intuitive Analogies: Uses diagrams and relatable comparisons to anchor concepts.", "required": true, "acceptable_evidence": ["Technical keywords: visual architecture, vector search, C4 model, sequence flows.", "Uses visual system architecture diagrams (C4 model, sequence flows) to map components and data journeys clearly.", "Employs relatable analogies to explain complex distributed concepts (e.g. comparing vector search to a semantic library catalog).", "Anchors abstract designs in concrete user stories showing the before-and-after user experience."]}, {"id": "KP3", "description": "Active Engagement & Comprehension Verification: Verifies alignment and handles technical scrutiny.", "required": false, "acceptable_evidence": ["Technical keywords: ADRs, active, engagement, comprehension.", "Pauses strategically for questions and checks for comprehension rather than delivering continuous monologues.", "Welcomes technical challenges and scrutiny calmly, using data and trade-off matrices to address concerns.", "Follows up presentations with clear written summaries, architecture decision records (ADRs), and action items."]}], "critical_failures": ["Speaks in impenetrable low-level jargon to executive business leaders, ignoring business impact.", "Cannot explain a technical concept without reading off slides or becoming defensive when questioned."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How do you decide between using a linear model versus a tree-based model for tabular data?', '{"key_points": [{"id": "KP1", "description": "Mathematical Assumptions & Non-Linear Interactions: Analyzes functional relationship capacity.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, Random Forest, recursive partitioning.", "Linear models assume linear relationships between features and log-odds/target; cannot capture non-linear interactions without manual polynomial/cross-features.", "Tree-based models (XGBoost, LightGBM, Random Forest) natively capture complex non-linear relationships and high-order feature interactions via recursive partitioning."]}, {"id": "KP2", "description": "Evaluate data dimensionality: linear models excel with ultra-high-dimensional sparse data (e.g. one-hot text); tree ensembles dominate dense tabular data.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, CatBoost, Logistic Regression, high-dimensional sparse data, non-linear interactions, tabular benchmarks.", "Evaluates data dimensionality: linear models excel with ultra-high-dimensional sparse data (e.g. one-hot text); tree ensembles dominate dense tabular data.", "Selects regularized linear models (Logistic Regression, ElasticNet) for high-dimensional sparse data and gradient boosted trees (XGBoost, LightGBM) for dense tabular data."]}, {"id": "KP3", "description": "Data Preprocessing & Robustness to Outliers: Contrasts preprocessing sensitivity.", "required": true, "acceptable_evidence": ["Technical keywords: overfitting, Lasso, Ridge, StandardScaler.", "Linear models require strict preprocessing: feature scaling (StandardScaler), outlier removal/clipping, one-hot encoding, and imputation of missing values.", "Tree models are invariant to monotonic feature scaling, robust to numeric outliers, and handle missing values natively (e.g. LightGBM default split direction).", "Linear models require regularization (L1 Lasso for feature sparsity, L2 Ridge for multicollinearity) to avoid overfitting."]}, {"id": "KP4", "description": "Interpretability, Inference Latency & Business Context: Evaluates compliance and production constraints.", "required": false, "acceptable_evidence": ["Technical keywords: PR-AUC, SHAP, RMSE, inference latency.", "Chooses linear models when exact interpretability and regulatory compliance are mandated (e.g. credit scorecards requiring clear beta coefficients).", "Chooses tree models when predictive performance (PR-AUC, F1, RMSE) is paramount and SHAP/TreeSHAP values suffice for explainability.", "Inference speed: linear models offer sub-millisecond dot-product scoring; modern compiled tree models (Treelite) achieve high throughput for low latency budgets."]}], "critical_failures": ["Claims tree models require feature scaling (like normalization or standardization) to function properly.", "Cannot explain why tree ensembles generally outperform linear models on complex non-linear tabular datasets."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How do you decide when to shrink or expand the window while solving substring problems?', '{"key_points": [{"id": "KP1", "description": "Expansion Criteria & Right Pointer Movement: Expands window to include new information.", "required": true, "acceptable_evidence": ["Technical keywords: window state, expansion, criteria, right.", "Expands window by advancing the `right` pointer one character at a time across the input string.", "Updates internal state (e.g. character frequency map, distinct character count, running sum) with `s[right]`.", "Expands as long as the current window state has not violated the problem''s feasibility constraint or when seeking a valid window."]}, {"id": "KP2", "description": "Shrink Criteria & Left Pointer Contraction: Contracts window upon invariant violation.", "required": true, "acceptable_evidence": ["Technical keywords: Minimum Window Substring, shrink, criteria, pointer.", "Shrinks window by advancing the `left` pointer when an invariant violation occurs (e.g. character count > k, distinct count > k).", "In minimum window problems (e.g. Minimum Window Substring): shrinks while the window remains valid to find the minimal optimal length.", "Removes `s[left]` from the internal state before incrementing `left` until the window is restored to a valid state."]}, {"id": "KP3", "description": "Optimal Tracking & Invariant Maintenance: Differentiates maximum vs minimum window patterns.", "required": false, "acceptable_evidence": ["Technical keywords: O(n), max_len, min_len.", "Maximum window pattern: expand right freely; shrink left when invalid; record max length `max(max_len, right - left + 1)`.", "Minimum window pattern: expand right until valid; shrink left while valid; record min length `min(min_len, right - left + 1)`.", "Proves overall O(N) runtime because each pointer moves strictly forward from 0 to N at most once."]}], "critical_failures": ["Cannot explain how to decide when to move the left pointer versus the right pointer.", "Proposes resetting the right pointer backward upon violation, causing an accidental O(N^2) runtime."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 210, 'How do you define the differences between a POC and a production system, and what steps are required to productionize a solution?', '{"key_points": [{"id": "KP1", "description": "POC vs Production Foundational Differences: Contrasts prototype characteristics with enterprise reality.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, POC, CI, CD.", "POC characteristics: single-user happy path, hardcoded credentials/paths, run in notebooks or local scripts, unhandled exceptions, zero tests.", "Production characteristics: high availability, multi-tenant isolation, automated CI/CD, comprehensive error handling, observability, security compliance."]}, {"id": "KP2", "description": "Contrasts functional feasibility demonstration with operational resilience and non-functional requirements.", "required": false, "acceptable_evidence": ["Technical keywords: POC vs Production, non-functional requirements, SLA compliance, CI/CD pipeline, Kubernetes, secrets management.", "Contrasts functional feasibility demonstration with operational resilience and non-functional requirements.", "Contrasts a POC''s focus on feasibility (happy path, local prototype) with production requirements: SLA compliance, horizontal scaling, security, and observability."]}, {"id": "KP3", "description": "Reliability, Scalability & Security Hardening: Details steps required to productionize code.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, RBAC, ABAC, AWS.", "Refactors monolithic code into modular containerized microservices running behind load balancers with autoscaling.", "Replaces hardcoded configs with 12-factor environment variables and enterprise secrets vaults (AWS Secrets Manager).", "Implements security controls: RBAC/ABAC authorization, TLS encryption, PII redaction, and input sanitization."]}, {"id": "KP4", "description": "Enforce network resilience: circuit breakers, retries with exponential backoff, and timeouts on all external calls.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breaker, pybreaker, request timeouts, exponential backoff, downstream dependency degradation, cascading failure.", "Enforces network resilience: circuit breakers, retries with exponential backoff, and timeouts on all external calls.", "Configures circuit breakers (e.g. pybreaker) and strict request timeouts to prevent cascading service failures when downstream dependencies degrade."]}, {"id": "KP5", "description": "Testing, CI/CD & Observability Infrastructure: Deploys verification and monitoring gates.", "required": false, "acceptable_evidence": ["Technical keywords: golden dataset, OpenTelemetry, distributed tracing, CI.", "Establishes automated CI/CD pipelines running linters, unit tests, integration tests, and golden dataset evaluation benchmarks.", "Deploys full observability stack: centralized structured logging (CloudWatch), distributed tracing (OpenTelemetry/Langfuse), and metrics alerting.", "Creates operational runbooks, disaster recovery strategies, and database backup routines."]}], "critical_failures": ["Believes productionizing code merely means putting an API endpoint on top of a Jupyter notebook without testing or security.", "Fails to identify non-functional requirements (security, scaling, monitoring, testing, error handling) in production systems."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'How do you differentiate between a data lake and a delta lake, and in what scenarios would you use each?', '{"key_points": [{"id": "KP1", "description": "Data Lake Architecture & Core Limitations: Explains raw object storage and failure modes.", "required": true, "acceptable_evidence": ["Technical keywords: ACID transactions, parquet, GDPR, CCPA.", "Data Lake: centralized repository storing raw structured, semi-structured, and unstructured data (S3, GCS, ADLS) in Parquet, ORC, CSV, JSON.", "Key limitations of traditional Data Lakes: lack of ACID transactions (failed writes leave partial corrupt files), dirty reads, lack of schema enforcement.", "Append-only nature makes GDPR/CCPA individual row deletions and updates (''Delete my data'') extremely slow and costly."]}, {"id": "KP2", "description": "Delta Lake Features & Storage Engine Mechanics: Explains ACID logs, time travel, and schema enforcement.", "required": true, "acceptable_evidence": ["Technical keywords: Delta Lake, ACID, AS, OF.", "Delta Lake: open-source storage framework sitting on top of cloud object storage providing an ACID transaction log (`_delta_log/`).", "ACID Transactions: serializable or snapshot isolation ensuring concurrent reads and writes never observe partial or corrupted states.", "Time Travel: queries point-in-time table versions (`VERSION AS OF` / `TIMESTAMP AS OF`) for reproducibility and rollback."]}, {"id": "KP3", "description": "Schema Enforcement & Evolution: prevents bad data writes with mismatched schemas while supporting controlled schema migrations.", "required": true, "acceptable_evidence": ["Technical keywords: Delta Lake, ACID transactions, _delta_log, schema enforcement, schema evolution, time-travel queries, Parquet.", "Schema Enforcement & Evolution: prevents bad data writes with mismatched schemas while supporting controlled schema migrations.", "Enforces ACID transactions and schema validation using Delta Lake''s transaction log (_delta_log), rejecting corrupt or mismatched record writes automatically."]}, {"id": "KP4", "description": "Scenario Selection & Optimization (Compaction): Recommends optimal use cases.", "required": false, "acceptable_evidence": ["Technical keywords: Compaction, Delta Lake, parquet.", "Use Data Lake for: raw bronze landing zone, unstructured media/document storage, and immutable raw event archives.", "Use Delta Lake for: curated silver/gold analytical tables, streaming-batch unified tables, and scenarios requiring frequent UPSERTs (MERGE).", "Performance optimizations: Auto-compaction / `OPTIMIZE` (merging small files into 1GB Parquet files) and Z-Ordering on multi-dimensional query keys."]}], "critical_failures": ["Claims Data Lake and Delta Lake are identical or cannot explain what the Delta transaction log does.", "Believes a raw S3 data lake natively provides ACID multi-row transactions without an engine like Delta Lake/Iceberg."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How do you differentiate between a product engineer and a traditional software engineer in the context of building AI-driven products?', '{"key_points": [{"id": "KP1", "description": "Core Mindset & Determinism vs Probabilism: Contrasts deterministic logic with managing probabilistic models.", "required": true, "acceptable_evidence": ["Technical keywords: LLM-as-a-judge, AI, LLM, predictable state.", "Traditional Software Engineer: writes deterministic logic, algorithmic code, and predictable state transitions where the same input yields identical output.", "AI Product Engineer: builds around probabilistic, non-deterministic foundation models, mastering prompt engineering, context framing, and guardrail boundaries.", "Embraces ambiguity: tests systems via statistical evaluation distributions and LLM-as-a-judge rather than strict boolean unit assertions alone."]}, {"id": "KP2", "description": "End-to-End User Experience & Rapid Iteration Loops: Prioritizes user workflow and rapid feedback.", "required": true, "acceptable_evidence": ["Technical keywords: UI, UX, API, SE.", "Product Engineer spans from frontend UI/UX through prompt orchestration and API integration to optimize user delight.", "Iterates rapidly on prompt ergonomics, streaming response UX, latency perception, and citation rendering.", "Traditional SE focuses heavily on deep infrastructure, database indexing, horizontal compute scaling, and backend plumbing."]}, {"id": "KP3", "description": "Evaluation, Observability & Symbiotic Collaboration: Drives product-level evaluation and alignment.", "required": false, "acceptable_evidence": ["Technical keywords: SE, symbiotic, drives, AI.", "Product Engineer curates golden evaluation datasets directly reflecting user satisfaction and edge cases.", "Monitors user sentiment, thumb feedback, and task completion rates to guide product refinements.", "Explains how both roles collaborate synergistically: traditional SE ensures high-availability infrastructure while product engineer crafts intuitive AI workflows."]}], "critical_failures": ["Treats AI product engineering as identical to traditional backend coding without recognizing probabilistic model behavior.", "Ignores user experience, prompt iteration, and evaluation loops when describing product engineering."]}', 1);
